  readonly reason:
    | "pending" | "issued" | "output-route-unavailable" | "account-identity-invalid"
    | "bilateral-frame-uncertified" | "certified-frame-invalid"
    | "bilateral-dispute-uncertified" | "certified-dispute-invalid";
