  const h = cj.host;
  const state: EntityState = withJBatch({ ...d.state, ...opt("crossJurisdictionSwaps", h.swaps) }, h.jb);
  return {
    ...d,
    state,
    outputs: [...d.outputs, ...cj.outputs.map((o) => cjOutput(state, o, timestamp))],
    events: [...(d.events ?? []), ...cj.messages.map(status)],
  };
