    return e.reason ?? `ACCOUNT_FRAME_DISPUTE_REQUIRED:${cause._tag}`;
  const window = `lock=${cause.lockId} reserve=${HTLC_ENFORCEMENT_RESERVE_MS}ms localTimestamp=${timestamp}`;
