const accountStateDomain = (d: Domain): Result<Domain, EntityError> =>
  mapErr(accountStateDomainText(d, "ACCOUNT_STATE_DOMAIN"), (reason): EntityError =>
    ({ _tag: "entity_invariant", reason }));
