    const previous = entries[entries.length - 1];
    const e = preparedEntryOf(b, previous === undefined ? "" : preparedHtlcKey(previous.binding));
    return e === null ? htlcReject("HTLC_PREPARED_CONTEXT_INVALID") : ok([...entries, e]);
