        fieldNames(o) === "forwardAmount,innerEnvelope,kind,nextHopEntityId" &&
        isWordId(o["nextHopEntityId"]) &&
        typeof o["forwardAmount"] === "bigint" &&
        o["forwardAmount"] > 0n &&
        o["forwardAmount"] <= amount &&
        htlcEnvelopeHash(o["innerEnvelope"]) !== null
