const processHtlcTimeoutsTx = (s: TxScope, x: EntityTxOf<"processHtlcTimeouts">): Draft =>
  (x.data.expiredLocks ?? []).reduce(
    (d, l) =>
      queueReturned(d, {
        accountId: l.accountId,
        tx: { type: "htlc_resolve", lockId: l.lockId, outcome: "error", reason: "timeout" },
      }),
    s.skip,
  );
