const evidenceHashOf = (evidence: readonly KeyedEvidence[]): string =>
  evidence.length > 0 ? `0x${keccakUtf8(JSON.stringify(evidence.map((x) => x.key)))}` : "";
/** A block's dispute evidence and its hash, both left out when there is none. */
