    mempool: r.mempool,
    blockDelayMs: r.blockDelayMs,
    blockTimeMs: r.blockTimeMs,
    lastBlockTimestamp: 0,
    blockReady: r.blockReady,
    watcherConfirmationDepth: r.watcherConfirmationDepth,
