/** og prepareRuntimeOutputRows: one encodeBuffer row per outbox output, in order. */
export const runtimeOutputRows = (
  rt: Runtime,
  outbox: readonly EntityOutput[],
  routes?: RuntimeRoutes,
): Result<readonly Uint8Array[], RuntimeError> =>
  traverse(outbox, (o) => chain(outputBinary(rt, o, routes), encodeBinary));
// ---- the retained network outbox a Runtime frame commits ----
// og runtime/delivery (identity.ts, pending.ts, plan.ts, recovery-output.ts)
/** og RoutedEntityInput wire object as og keeps it in env.pendingNetworkOutputs and encodes it as one outbox row. */
export type NetworkOutput = { readonly [k: string]: Binary };
/** og LIMITS.MAX_PENDING_NETWORK_OUTPUTS. */
export const MAX_PENDING_NETWORK_OUTPUTS = 10_000;
type WireRecord = { readonly [k: string]: Binary };
type NetworkTx = { readonly type: string; readonly data: WireRecord };
/** A wire value as og's String(...) spells it; absence is the empty string. */
const netText = (v: Binary | undefined): string => {
  switch (true) {
    case typeof v === "string":
      return v;
    case v === undefined || v === null:
      return "";
    default:
      return String(v);
  }
};
const txList = (v: Binary | undefined): readonly NetworkTx[] =>
  Array.isArray(v) ? (v as unknown as readonly NetworkTx[]) : [];
const netTxs = (o: NetworkOutput): readonly NetworkTx[] => txList(o["entityTxs"]);
const netMap = (v: Binary | undefined): ReadonlyMap<Binary, Binary> | undefined =>
  v instanceof Map ? (v as ReadonlyMap<Binary, Binary>) : undefined;
const RUNTIME_ADDRESS = /^0x[0-9a-fA-F]{40}$/;
/** og netRuntimeId: a runtime id is a lowercased address; anything else is no id. */
const netRuntimeId = (v: Binary | undefined): string => {
  const s = netText(v).trim();
  return RUNTIME_ADDRESS.test(s) ? s.toLowerCase() : "";
};
const routeText = (v: Binary | undefined): string => netText(v).trim().toLowerCase();
/** og getEffectiveEntityInputTxs: a runtimeOutput's nested txs stand in for it. */
const standInTxs = (tx: NetworkTx): readonly NetworkTx[] =>
  tx.type === "runtimeOutput" && Array.isArray(tx.data["entityTxs"]) ? txList(tx.data["entityTxs"]) : [tx];
const netEffective = (o: NetworkOutput): readonly NetworkTx[] => netTxs(o).flatMap(standInTxs);


// Account proposals: the one kind of output identified by what it proposes rather than by its bytes.

type NetProposal = {
  readonly from: string;
  readonly to: string;
  readonly height: Binary;
  readonly stateHash: string;
  readonly frameHanko: boolean;
  readonly disputeHanko: boolean;
  readonly ack: boolean;
};
/** og accountInputProposal / accountInputAck over an `accountInput` wire tx. */
const netProposal = (tx: NetworkTx): NetProposal | undefined => {
  const d = tx.data;
  const proposal = d["proposal"] as WireRecord | undefined;
  if (tx.type !== "accountInput" || d["kind"] !== "ack_frame" || proposal === undefined || proposal === null) {
    return undefined;
  }
  const frame = proposal["frame"] as WireRecord;
  return {
    from: netText(d["fromEntityId"]),
    to: netText(d["toEntityId"]),
    height: frame["height"] ?? null,
    stateHash: netText(frame["stateHash"]),
    frameHanko: Boolean(proposal["frameHanko"]),
    disputeHanko: Boolean(proposal["disputeHanko"]),
    ack: Boolean(d["ack"]),
  };
};
const carriedProposals = (o: NetworkOutput): readonly NetProposal[] =>
  netEffective(o).flatMap((tx) => {
    const p = netProposal(tx);
    return p === undefined ? [] : [p];
  });
/** An output whose every effective tx is an Account proposal; anything else is no proposal output. */
const netProposals = (o: NetworkOutput): readonly NetProposal[] | null => {
  const proposals = carriedProposals(o);
  return proposals.length > 0 && proposals.length === netEffective(o).length ? proposals : null;
};
const proposalLegKey = (p: NetProposal): string =>
  `${p.from.toLowerCase()}:${p.to.toLowerCase()}:${netText(p.height)}:${p.stateHash.toLowerCase()}`;
/** og accountProposalOutputIdentity. */
const proposalIdentity = (o: NetworkOutput): string | null => {
  const proposals = netProposals(o);
  if (proposals === null) return null;
  const route = [
    netRuntimeId(o["runtimeId"]),
    routeText(o["entityId"]),
    routeText(o["signerId"]),
    netRuntimeId(o["from"]),
  ];
  return `ap|${route.join("|")}|${proposals.map(proposalLegKey).join(",")}`;
};
/** The Hanko evidence an output's proposals carry. */
const proposalRank = (o: NetworkOutput): number =>
  carriedProposals(o).reduce((rank, p) => rank + Number(p.frameHanko) + Number(p.disputeHanko), 0);


// Route keys and lanes: two outputs on one key merge into one delivery.

const ROUTE_ENCODING_INVALID: RuntimeError = { _tag: "runtime_frame", code: "ROUTE_OUTPUT_ENCODING_INVALID" };
const netDigest = (v: Binary | undefined): Result<string, RuntimeError> =>
  v === undefined ? ok("") : mapErr(map(encodeBinary(v), integrity), () => ROUTE_ENCODING_INVALID);
const compareConsensus = (a: Binary, b: Binary): Result<number, RuntimeError> => {
  const x = encodeConsensus(a);
  const y = encodeConsensus(b);
  return x.ok && y.ok ? ok(compareBytes(x.value, y.value)) : frameErr("ROUTE_OUTPUT_ENCODING_INVALID");
};
/** A present part spelled by `spell`; an absent one is the empty field. */
const spelledIf = <T>(part: T | undefined, spell: (t: T) => string): string => (part ? spell(part) : "");
const sortedKeys = (v: Binary | undefined): string =>
  [...(netMap(v)?.keys() ?? [])].map(netText).toSorted().join(",");
/** A vote without its signature and voter: what two votes of one voter must agree on. */
const voteBodyOf = (vote: WireRecord | undefined): Binary | undefined =>
  vote === undefined
    ? undefined
    : Object.fromEntries(Object.entries(vote).filter(([k]) => k !== "signature" && k !== "voterId"));
/**
 * og buildRouteOutputKey: an Account proposal by its identity, anything else by route, source frame and exact payload.
 * og's tx fingerprints and leader-vote body hash are replaced by equality-equivalent content digests (the key is
 * compared, never stored).
 */
export const routeKeyOf = (o: NetworkOutput): Result<string, RuntimeError> => {
  const identity = proposalIdentity(o);
  if (identity !== null) return ok(identity);
  const source = o["sourceRuntimeFrame"] as { readonly height: Binary; readonly timestamp: Binary } | undefined;
  const proposed = o["proposedFrame"] as WireRecord | undefined;
  const precommit = o["hashPrecommitFrame"] as WireRecord | undefined;
  const vote = o["leaderTimeoutVote"] as WireRecord | undefined;
  const digests = all({
    voteHash: netDigest(voteBodyOf(vote)),
    fingerprints: traverse(netTxs(o), (tx) => netDigest(tx as unknown as Binary)),
  });
  return map(digests, ({ voteHash, fingerprints }) =>
    [
      "ro",
      netText(o["runtimeId"]),
      spelledIf(source, (f) => `${netText(f.height)}:${netText(f.timestamp)}`),
      routeText(o["entityId"]),
      routeText(o["signerId"]),
      netText(o["from"]),
      spelledIf(proposed, (f) => `${netText(f["height"])}:${netText(f["hash"])}`),
      spelledIf(
        precommit,
        (f) => `${netText(f["height"])}:${netText(f["frameHash"])}:${sortedKeys(o["hashPrecommits"])}`,
      ),
      spelledIf(vote, (v) => `${routeText(v["voterId"])}:${voteHash}`),
      sortedKeys(o["jPrefixAttestations"]),
      fingerprints.join("\u0001"),
    ].join("|"),
  );
};
/**
 * og splitRoutedOutputByDeliveryLane: one output per payload kind (frame, precommit bundle, vote, each J-prefix
 * attestation, the txs together).
 */
const splitLanes = (o: NetworkOutput): Result<readonly NetworkOutput[], RuntimeError> => {
  const {
    entityTxs,
    proposedFrame,
    hashPrecommits,
    hashPrecommitFrame,
    jPrefixAttestations,
    leaderTimeoutVote,
    ...route
  } = o;
  const precommits = netMap(hashPrecommits);
  const bundled = precommits !== undefined && precommits.size > 0;
  if (bundled && hashPrecommitFrame === undefined) return frameErr("ROUTE_PRECOMMIT_FRAME_REFERENCE_MISSING");
  if (!bundled && hashPrecommitFrame !== undefined)
    return frameErr("ROUTE_PRECOMMIT_FRAME_REFERENCE_WITHOUT_SIGNATURES");
  const attestations = [...(netMap(jPrefixAttestations) ?? [])];
  const lanes: readonly NetworkOutput[] = [
    ...(proposedFrame === undefined ? [] : [{ ...route, proposedFrame }]),
    ...(bundled && hashPrecommitFrame !== undefined
      ? [{ ...route, hashPrecommitFrame, hashPrecommits: precommits }]
      : []),
    ...(leaderTimeoutVote === undefined ? [] : [{ ...route, leaderTimeoutVote }]),
    ...attestations.map((signed) => ({ ...route, jPrefixAttestations: new Map([signed]) })),
  ];
  const txs = Array.isArray(entityTxs) ? entityTxs : [];
  return ok(txs.length > 0 || lanes.length === 0 ? [...lanes, { ...route, entityTxs: txs }] : lanes);
};


// Merging: one slot per route key, the first output's.

type SourceStamp = SourceRuntimeFrame | undefined;
const sourceFrameOf = (o: NetworkOutput): SourceStamp => o["sourceRuntimeFrame"] as SourceStamp;
/** Whether `incoming` was stamped by a later source frame than `existing`; an unstamped incoming never is. */
const isNewerSource = (incoming: SourceStamp, existing: SourceStamp): boolean => {
  if (incoming === undefined) return false;
  if (existing === undefined) return true;
  return (
    incoming.height > existing.height ||
    (incoming.height === existing.height && incoming.timestamp > existing.timestamp)
  );
};
/**
 * og mergeAccountProposalOutput: more Hanko evidence, else the newer source frame, else the canonically smaller
 * envelope.
 */
const mergeProposal = (existing: NetworkOutput, incoming: NetworkOutput): Result<NetworkOutput, RuntimeError> => {
  const delta = proposalRank(incoming) - proposalRank(existing);
  if (delta !== 0) return ok(delta > 0 ? incoming : existing);
  if (isNewerSource(sourceFrameOf(incoming), sourceFrameOf(existing))) return ok(incoming);
  return map(compareConsensus(existing, incoming), (c) => (c <= 0 ? existing : incoming));
};
type PrecommitBundles = ReadonlyMap<string, readonly Binary[]>;
const NO_BUNDLES: PrecommitBundles = new Map();
/** og normalizePrecommitBundles. */
const precommitBundles = (m: ReadonlyMap<Binary, Binary>): Result<PrecommitBundles, RuntimeError> =>
  foldResult(m, NO_BUNDLES, (bundles, [raw, sigs]) => {
    const signer = routeText(raw);
    return bundles.has(signer)
      ? frameErr(`ROUTE_PRECOMMIT_DUPLICATE_SIGNER:${netText(raw)}`)
      : ok(mapSet(bundles, signer, Array.isArray(sigs) ? sigs : []));
  });
const sameSignatures = (a: readonly Binary[], b: readonly Binary[]): boolean =>
  a.length === b.length && a.every((s, i) => s === b[i]);
/** A signer new to the bundles joins them; a signer already there must repeat its signatures exactly. */
const unionBundles = (held: PrecommitBundles, added: PrecommitBundles): Result<PrecommitBundles, RuntimeError> =>
  foldResult(added, held, (merged, [signer, sigs]) => {
    const prev = merged.get(signer);
    if (prev === undefined) return ok(mapSet(merged, signer, [...sigs]));
    return sameSignatures(prev, sigs) ? ok(merged) : frameErr(`ROUTE_PRECOMMIT_EQUIVOCATION:${signer}`);
  });
/** Two outputs' precommit bundles merge only over one frame reference. */
const mergePrecommits = (
  next: NetworkOutput,
  existing: NetworkOutput,
  incoming: NetworkOutput,
): Result<NetworkOutput, RuntimeError> => {
  const adds = netMap(incoming["hashPrecommits"]);
  if (adds === undefined || adds.size === 0) return ok(next);
  const heldFrame = existing["hashPrecommitFrame"];
  const clash = heldFrame === undefined
    ? ok(false)
    : map(compareConsensus(heldFrame, incoming["hashPrecommitFrame"] ?? null), (c) => c !== 0);
  return chain(clash, (clashes) => {
    const frame = incoming["hashPrecommitFrame"];
    if (clashes) return frameErr("ROUTE_PRECOMMIT_FRAME_CONFLICT");
    if (frame === undefined) return frameErr("ROUTE_PRECOMMIT_FRAME_REFERENCE_MISSING");
    const bundles = all({
      held: precommitBundles(netMap(existing["hashPrecommits"]) ?? new Map()),
      added: precommitBundles(adds),
    });
    return map(chain(bundles, ({ held, added }) => unionBundles(held, added)), (merged) => ({
      ...next,
      hashPrecommitFrame: frame,
      hashPrecommits: new Map(sortWith(merged, ([a], [b]) => asc(a, b))),
    }));
  });
};
/** A proposed frame carrying exactly one Hanko is a commit notice. */
const isCommitNotice = (o: NetworkOutput): boolean => {
  const hankos = (o["proposedFrame"] as WireRecord | undefined)?.["hankos"];
  return Array.isArray(hankos) && hankos.length === 1;
};
/** A proposed frame fills an empty slot, and a commit notice replaces a bare frame. */
const withProposedFrame = (merged: NetworkOutput, incoming: NetworkOutput): NetworkOutput => {
  const frame = incoming["proposedFrame"];
  if (frame === undefined) return merged;
  const replaces = merged["proposedFrame"] === undefined || (isCommitNotice(incoming) && !isCommitNotice(merged));
  return replaces ? { ...merged, proposedFrame: frame } : merged;
};
/** Two leader votes on one route conflict unless both are absent or canonically equal. */
const votesConflict = (held: Binary | undefined, incoming: Binary | undefined): Result<boolean, RuntimeError> => {
  if (held === undefined && incoming === undefined) return ok(false);
  if (held === undefined || incoming === undefined) return ok(true);
  return map(compareConsensus(incoming, held), (c) => c !== 0);
};
const voterOf = (vote: Binary | undefined): string =>
  netText((vote as WireRecord | undefined)?.["voterId"]) || "missing";
/**
 * og mergeOrdinaryOutput: vote equivocation refuses; txs append; precommit bundles union (equivocation refuses); a
 * commit notice replaces a bare frame.
 */
const mergeOrdinary = (existing: NetworkOutput, incoming: NetworkOutput): Result<NetworkOutput, RuntimeError> => {
  const vote = incoming["leaderTimeoutVote"];
  return chain(votesConflict(existing["leaderTimeoutVote"], vote), (conflict) => {
    if (conflict) return frameErr(`ROUTE_LEADER_VOTE_EQUIVOCATION:${voterOf(vote)}`);
    const added = netTxs(incoming);
    const next = added.length > 0
      ? { ...existing, entityTxs: [...netTxs(existing), ...added] as unknown as Binary }
      : existing;
    return map(mergePrecommits(next, existing, incoming), (merged) => withProposedFrame(merged, incoming));
  });
};
/** Same-identity Account proposals merge by evidence; anything else by lane union. */
const mergeSlot = (existing: NetworkOutput, incoming: NetworkOutput): Result<NetworkOutput, RuntimeError> => {
  const identity = proposalIdentity(existing);
  return identity !== null && identity === proposalIdentity(incoming)
    ? mergeProposal(existing, incoming)
    : mergeOrdinary(existing, incoming);
};
type Slots = ReadonlyMap<string, NetworkOutput>;
const NO_SLOTS: Slots = new Map();
const intoSlot = (slots: Slots, o: NetworkOutput): Result<Slots, RuntimeError> =>
  chain(routeKeyOf(o), (key) => {
    const existing = slots.get(key);
    return existing === undefined
      ? ok(mapSet(slots, key, o))
      : map(mergeSlot(existing, o), (merged) => mapSet(slots, key, merged));
  });
/** og buildPendingNetworkOutputs / dedupeEntityOutputs: split lanes, merge by route key into the first slot. */
const dedupeNetwork = (outputs: readonly NetworkOutput[]): Result<readonly NetworkOutput[], RuntimeError> =>
  chain(traverse(outputs, splitLanes), (lanes) =>
    map(foldResult(lanes.flat(), NO_SLOTS, intoSlot), (slots) => [...slots.values()]),
  );
const pendingNetwork = (outputs: readonly NetworkOutput[]): Result<readonly NetworkOutput[], RuntimeError> =>
  chain(dedupeNetwork(outputs), (pending) =>
    pending.length > MAX_PENDING_NETWORK_OUTPUTS
      ? frameErr(`NETWORK_OUTBOX_CAPACITY_EXCEEDED: pending=${pending.length} max=${MAX_PENDING_NETWORK_OUTPUTS}`)
      : ok(pending));


// Settlement: a proposal is owed until its sender's Account stops holding it pending.

const senderAccount = (rt: Runtime, p: NetProposal) =>
  [...rt.entities.values()]
    .filter((r) => lower(r.state.id) === lower(p.from))
    .map((r) => [...r.accountReplicas].find(([id]) => lower(id) === lower(p.to))?.[1])
    .find((a) => a !== undefined);
/**
 * Whether the sender's Account still holds this proposal's frame pending; a sender Account this Runtime lacks refuses.
 */
const stillPending = (rt: Runtime, p: NetProposal): Result<boolean, RuntimeError> => {
  const account = senderAccount(rt, p);
  if (account === undefined) {
    const proposal = {
      runtimeId: rt.runtimeId ?? null,
      fromEntityId: p.from,
      toEntityId: p.to,
      proposalHeight: p.height,
      proposalStateHash: p.stateHash,
    };
    return frameErr(`ACCOUNT_PROPOSAL_OUTBOX_SOURCE_ACCOUNT_MISSING:${stableJson(proposal)}`);
  }
  const pending = account._tag === "proposed" ? account.candidate.frame : undefined;
  return ok(
    pending !== undefined &&
    netText(p.height) === String(pending.height) &&
    pending.stateHash.toLowerCase() === p.stateHash.toLowerCase(),
  );
};
/** An output is owed while it carries no proposal, carries an ACK, or holds a proposal still pending. */
const stillOwed = (rt: Runtime, o: NetworkOutput): Result<boolean, RuntimeError> => {
  const proposals = carriedProposals(o);
  if (proposals.length === 0 || proposals.some((p) => p.ack)) return ok(true);
  // og `every` settled: the first proposal still pending keeps the output, and later legs are not inspected
  return someResult(proposals, (p) => stillPending(rt, p));
};
/**
 * og accountProposalSettledBySender / pruneSettledOutputs: a proposal-only output is settled once the sender's Account
 * no longer holds that frame pending (committed or rolled back); an output that also carries an ACK is still owed.
 */
const pruneSettled = (rt: Runtime, outputs: readonly NetworkOutput[]): Result<readonly NetworkOutput[], RuntimeError> =>
  map(
    traverse(outputs, (o) => map(stillOwed(rt, o), (owed) => [o, owed] as const)),
    (judged) => judged.filter(([, owed]) => owed).map(([o]) => o),
  );


// Planning: each output is this Runtime's own continuation or a delivery to a bound remote Runtime.

/** An output with nothing to deliver but its route. */
const isTriggerOnly = (o: NetworkOutput): boolean =>
  netTxs(o).length === 0 &&
  o["proposedFrame"] === undefined &&
  o["leaderTimeoutVote"] === undefined &&
  (netMap(o["jPrefixAttestations"])?.size ?? 0) === 0 &&
  (netMap(o["hashPrecommits"])?.size ?? 0) === 0;
const txTypesOf = (o: NetworkOutput): string => netTxs(o).map((tx) => tx.type).join(",");
/**
 * og extensions/cross-j/boundary.ts CROSS_J_INTRA_RUNTIME_ENTITY_TX_TYPES: raw cross-j Entity effects never leave their
 * Runtime.
 */
const CROSS_J_INTRA_RUNTIME_TXS = new Set([
  "prepareCrossJurisdictionSwap",
  "materializeCrossJurisdictionSwap",
  "registerCrossJurisdictionSwap",
  "crossJurisdictionFillNotice",
  "requestCrossJurisdictionClear",
  "materializeCrossJurisdictionClear",
  "crossPullClose",
  "crossJurisdictionSalvage",
  "crossJurisdictionForceSiblingDispute",
  "orderbookSweepCrossJurisdiction",
  "admitCrossJurisdictionBookOrder",
  "removeCrossJurisdictionBookOrder",
  "crossJurisdictionBookOrderRemoved",
]);
type NetworkPlan = { readonly local: readonly NetworkOutput[]; readonly remote: readonly NetworkOutput[] };
type PlannedOutput = { readonly lane: keyof NetworkPlan; readonly output: NetworkOutput };
const planned = (lane: keyof NetworkPlan) => (output: NetworkOutput): PlannedOutput => ({ lane, output });
const entityOf = (o: NetworkOutput): string => netText(o["entityId"]);
const resolvedAs = (signer: string, o: NetworkOutput): string => `resolved=${signer} txTypes=${txTypesOf(o)}`;
/** A trigger for a local Entity retargets to its sole local signer; anything else names the wrong signer. */
const retargetLocal = (o: NetworkOutput, sole: string): Result<PlannedOutput, RuntimeError> => {
  if (isTriggerOnly(o)) return ok(planned("local")({ ...o, signerId: sole }));
  const named = `entity=${entityOf(o)} signer=${netText(o["signerId"])}`;
  const payload = netTxs(o).length > 0 ? `txTypes=${txTypesOf(o)}` : `resolved=${sole} consensusOnly=true`;
  return frameErr(`ROUTE_LOCAL_SIGNER_MISMATCH: ${named} ${payload}`);
};
/**
 * og alignRemoteOutputSigner: the verified profile's signer wins; a trigger takes it, txs for another signer refuse.
 */
const alignRemoteSigner = (
  o: NetworkOutput,
  entity: string,
  routes: RuntimeRoutes | undefined,
): Result<NetworkOutput, RuntimeError> => {
  const preferred = routes?.verifiedProfileSigner(entity) ?? "";
  const signer = netText(o["signerId"]);
  const aligned = preferred === "" || preferred.toLowerCase() === signer.trim().toLowerCase();
  switch (true) {
    case aligned:
      return ok(o);
    case isTriggerOnly(o):
      return ok({ ...o, signerId: preferred });
    case netTxs(o).length > 0:
      return frameErr(
        `ROUTE_REMOTE_SIGNER_MISMATCH: entity=${entityOf(o)} signer=${signer} ${resolvedAs(preferred, o)}`,
      );
    default:
      return ok(o);
  }
};
/** An output bound to its target Runtime, and the replay route that bound it (empty outside replay). */
type BoundOutput = { readonly output: NetworkOutput; readonly target: string; readonly replay: string };
/**
 * og bindVerifiedTargetRuntime: a replay route binds outright; else a verified route overrides the persisted hint,
 * which the resolved one backs.
 */
const bindTargetRuntime = (
  o: NetworkOutput,
  entity: string,
  routes: RuntimeRoutes | undefined,
): Result<BoundOutput, RuntimeError> => {
  const signer = netText(o["signerId"]);
  const persisted = netRuntimeId(o["runtimeId"]);
  const replay = netRuntimeId(routes?.replayRuntime?.(entity, routeText(signer)));
  if (replay !== "") {
    return persisted !== "" && persisted !== replay
      ? frameErr(`REPLAY_OUTPUT_RUNTIME_ROUTE_MISMATCH:${entityOf(o)}:${signer}`)
      : ok({ output: o, target: replay, replay });
  }
  const resolved = routes?.resolvedRuntime?.(entity) ?? "";
  const verified = netRuntimeId(routes?.verifiedRuntime?.(entity));
  const output = verified !== "" && persisted !== verified ? { ...o, runtimeId: verified } : o;
  return ok({ output, target: netRuntimeId(output["runtimeId"]) || verified || resolved, replay });
};
/** A lone cross-j runtimeOutput goes only to the Runtime its (Entity, signer) is bound to. */
const crossJTargetVerified = (
  { output, target, replay }: BoundOutput,
  entity: string,
  routes: RuntimeRoutes | undefined,
) => {
  const bound = netRuntimeId(replay !== "" ? replay : routes?.crossJRuntime?.(entity, routeText(output["signerId"])));
  return bound !== "" && bound === target;
};
/** og boundary: a cross-j runtimeOutput or a raw cross-j Entity effect never goes remote. */
const leaksCrossJ = (o: NetworkOutput): boolean =>
  netTxs(o).some((tx) => tx.type === "runtimeOutput" && tx.data["protocol"] === "cross-j") ||
  netEffective(o).some((tx) => CROSS_J_INTRA_RUNTIME_TXS.has(tx.type));
/**
 * og's remote refusals: an unknown or stale self target, a lone cross-j output to an unbound Runtime, and cross-j
 * traffic that must stay home.
 */
const remoteRefusal = (
  rt: Runtime,
  bound: BoundOutput,
  entity: string,
  routes: RuntimeRoutes | undefined,
): Result<void, RuntimeError> => {
  const { output, target } = bound;
  const self = netRuntimeId(rt.runtimeId);
  const txs = netTxs(output);
  const kinds = `txTypes=${txTypesOf(output)}`;
  switch (true) {
    case target === "":
      return frameErr(`ROUTE_TARGET_RUNTIME_UNKNOWN: entity=${entityOf(output)} ${kinds}`);
    case self !== "" && target === self:
      return frameErr(`ROUTE_STALE_SELF_HINT: entity=${entityOf(output)} runtime=${target} ${kinds}`);
    case txs.length === 1 && txs[0]?.type === "runtimeOutput":
      return crossJTargetVerified(bound, entity, routes)
        ? ok(undefined)
        : frameErr(
            `CROSS_J_RUNTIME_OUTPUT_TARGET_UNVERIFIED:${entityOf(output)}:${netText(output["signerId"])}:${target}`,
          );
    case leaksCrossJ(output):
      return frameErr(
        `CROSS_J_REMOTE_OUTPUT_FORBIDDEN: entity=${routeText(output["entityId"])} targetRuntime=${target} ${kinds}`,
      );
    default:
      return ok(undefined);
  }
};
/** A remote output: signer aligned, Runtime bound, og's refusals passed. */
const bindRemote = (
  rt: Runtime,
  o: NetworkOutput,
  entity: string,
  routes: RuntimeRoutes | undefined,
): Result<NetworkOutput, RuntimeError> =>
  chain(alignRemoteSigner(o, entity, routes), (aligned) =>
    chain(bindTargetRuntime(aligned, entity, routes), (bound) =>
      map(remoteRefusal(rt, bound, entity, routes), () => ({ ...bound.output, runtimeId: bound.target }))));
const planOutput = (
  rt: Runtime,
  o: NetworkOutput,
  routes: RuntimeRoutes | undefined,
): Result<PlannedOutput, RuntimeError> => {
  const entity = routeText(o["entityId"]);
  const signer = routeText(o["signerId"]);
  const signers = [...rt.entities.values()].filter((r) => lower(r.state.id) === entity).map((r) => lower(r.signerId));
  const sole = signers.length === 1 ? signers[0] : undefined;
  switch (true) {
    case signer !== "" && signers.includes(signer):
      return ok(planned("local")(o));
    case sole !== undefined:
      return retargetLocal(o, sole);
    default:
      return map(bindRemote(rt, o, entity, routes), planned("remote"));
  }
};
const outputsIn = (plan: readonly PlannedOutput[], lane: keyof NetworkPlan): readonly NetworkOutput[] =>
  plan.filter((p) => p.lane === lane).map((p) => p.output);
/**
 * og planEntityOutputs: a target with a local replica of the named signer is local (a trigger retargets to the sole
 * local signer; anything else refuses ROUTE_LOCAL_SIGNER_MISMATCH); every other output is remote: its signer aligned
 * with the verified profile, its Runtime bound (replay route, else the verified route, else the persisted or resolved
 * one), with og's unknown-route, self-hint and cross-j refusals.
 */
const planNetwork = (
  rt: Runtime,
  outputs: readonly NetworkOutput[],
  routes: RuntimeRoutes | undefined,
): Result<NetworkPlan, RuntimeError> =>
  chain(dedupeNetwork(outputs), (deduped) =>
    map(traverse(deduped, (o) => planOutput(rt, o, routes)), (plan) => ({
      local: outputsIn(plan, "local"),
      remote: outputsIn(plan, "remote"),
    })));
/**
 * og planEntityOutputs' local lane: this frame's outputs deduplicated by route key and kept for this Runtime's own
 * replicas, as og re-enqueues them into runtimeMempool.entityInputs.
 */
export const localNetworkOutputs = (
  rt: Runtime,
  outbox: readonly EntityOutput[],
  routes?: RuntimeRoutes,
): Result<readonly NetworkOutput[], RuntimeError> =>
  chain(traverse(outbox, (o) => outputBinary(rt, o, routes)), (rows) =>
    map(planNetwork(rt, rows as readonly NetworkOutput[], routes), (plan) => plan.local));
/**
 * og applyRecoveryRuntimeOutputPlan after a frame: this frame's outputs are stamped with their source frame, joined to
 * the retained outbox, pruned of settled proposals, deduplicated and planned; the local outputs are this Runtime's own
 * continuations and the remote ones become the new retained outbox, which is exactly what og commits as the frame's
 * runtime outputs.
 */
export const retainedNetworkOutbox = (
  rt: Runtime,
  outbox: readonly EntityOutput[],
  routes?: RuntimeRoutes,
): Result<readonly NetworkOutput[], RuntimeError> =>
  chain(traverse(outbox, (o) => outputBinary(rt, o, routes)), (rows) =>
    networkOutboxStep(rt, rows as readonly NetworkOutput[], routes));
/**
 * og applyRecoveryRuntimeOutputPlan over og-wire outputs: stamp, join the retained outbox, prune, dedupe, plan; the
 * result is the new retained outbox.
 */
export const networkOutboxStep = (
  rt: Runtime,
  outputs: readonly NetworkOutput[],
  routes?: RuntimeRoutes,
): Result<readonly NetworkOutput[], RuntimeError> =>
  chain(all({ height: frameNumber(rt.height), timestamp: frameNumber(rt.timestamp) }), (source) => {
    const originated = outputs.map((o) => (o["sourceRuntimeFrame"] ? o : { ...o, sourceRuntimeFrame: source }));
    const owed = chain(pruneSettled(rt, [...(rt.pendingNetworkOutputs ?? []), ...originated]), pendingNetwork);
    return chain(owed, (pending) => chain(planNetwork(rt, pending, routes), (plan) => pendingNetwork(plan.remote)));
  });
/**
 * og dispatchEntityOutputs retirement: outputs a transport accepted leave the retained outbox (by route key); the rest
 * stay owed.
 */
export const retireNetworkOutputs = (rt: Runtime, accepted: (output: NetworkOutput) => boolean): Runtime => ({
  ...rt,
  pendingNetworkOutputs: (rt.pendingNetworkOutputs ?? []).filter((o) => !accepted(o)),
});


// Recovery: a persisted frame's outputs are proven against the outbox the frames before it retained.

/** An output as retained evidence: its Runtime binding aside. */
const asEvidence = (o: NetworkOutput): NetworkOutput => ({ ...o, runtimeId: "" });
type PriorEvidence = { readonly output: NetworkOutput; readonly index: number };
/** The previous retained outbox by evidence key; a repeated key keeps its last output. */
const priorEvidence = (previous: readonly NetworkOutput[]): Result<ReadonlyMap<string, PriorEvidence>, RuntimeError> =>
  map(
    traverse(previous, (output, index) =>
      map(routeKeyOf(asEvidence(output)), (key) => [key, { output, index }] as const),
    ),
    (rows) => new Map(rows),
  );
/** The prior retained output a recorded row repeats exactly, its Runtime binding aside. */
const provenPrior = (
  prior: ReadonlyMap<string, PriorEvidence>,
  output: NetworkOutput,
  height: number,
): Result<PriorEvidence, RuntimeError> =>
  chain(routeKeyOf(asEvidence(output)), (key) => {
    const verified = prior.get(key);
    const unproven = frameErr(`RECOVERY_OUTBOX_RETAINED_OUTPUT_UNPROVEN:height=${height}`);
    if (verified === undefined) return unproven;
    return chain(compareConsensus(asEvidence(verified.output), asEvidence(output)), (c) =>
      c === 0 ? ok(verified) : unproven,
    );
  });
/** The retained outputs selected so far, and the prior index the last of them came from. */
type RetainedWalk = { readonly retained: readonly NetworkOutput[]; readonly lastIndex: number };
/**
 * A recorded row from an earlier frame is prior evidence, in prior order; this frame's own rows are regenerated by
 * replay.
 */
const retainRecorded = (
  prior: ReadonlyMap<string, PriorEvidence>,
  walk: RetainedWalk,
  output: NetworkOutput,
  height: number,
): Result<RetainedWalk, RuntimeError> => {
  const source = sourceFrameOf(output);
  if (source === undefined || source.height > height || !output["runtimeId"]) {
    return frameErr(`RECOVERY_OUTBOX_SOURCE_FRAME_INVALID:height=${height}`);
  }
  if (source.height === height) return ok(walk);
  return chain(provenPrior(prior, output, height), (verified) => {
    if (verified.index <= walk.lastIndex) return frameErr(`RECOVERY_OUTBOX_RETAINED_ORDER_INVALID:height=${height}`);
    const runtimeId = output["runtimeId"] as Binary;
    const rebound = verified.output["runtimeId"] === runtimeId ? verified.output : { ...verified.output, runtimeId };
    return ok({ retained: [...walk.retained, rebound], lastIndex: verified.index });
  });
};
/**
 * og selectRetainedRecoveryOutbox: a frame's recorded rows from earlier frames must each be exact prior retained
 * evidence (runtimeId aside), in prior order; this frame's own rows are regenerated by replay.
 */
export const selectRetainedRecovery = (
  previous: readonly NetworkOutput[],
  recorded: readonly NetworkOutput[],
  height: number,
): Result<readonly NetworkOutput[], RuntimeError> =>
  chain(priorEvidence(previous), (prior) => {
    const start: RetainedWalk = { retained: [], lastIndex: -1 };
    const walked = foldResult(recorded, start, (walk, output) => retainRecorded(prior, walk, output, height));
    return map(walked, (walk) => walk.retained);
  });
const NO_BINDINGS: ReadonlyMap<string, string> = new Map();
/**
 * og collectOutputSignerHints: each Account-bearing row of a replayed frame names its Entity's signer; two signers for
 * one Entity conflict.
 */
export const replaySignerHints = (
  rows: readonly NetworkOutput[],
  height: number,
): Result<ReadonlyMap<string, string>, RuntimeError> =>
  foldResult(rows, NO_BINDINGS, (hints, o) => {
    if (!netTxs(o).some((tx) => tx.type === "accountInput")) return ok(hints);
    const entity = routeText(o["entityId"]);
    const signer = routeText(o["signerId"]);
    const held = hints.get(entity);
    switch (true) {
      case entity === "" || signer === "":
        return frameErr(`RECOVERY_OUTPUT_SIGNER_HINT_INVALID:height=${height}`);
      case held !== undefined && held !== signer:
        return frameErr(
          `RECOVERY_OUTPUT_SIGNER_HINT_CONFLICT:height=${height}:entity=${entity}:left=${held}:right=${signer}`,
        );
      default:
        return ok(mapSet(hints, entity, signer));
    }
  });
/**
 * og installReplayOutputRuntimeRoutes: a replayed frame's own rows bind each (Entity, signer) to its committed Runtime.
 */
export const replayOutputRoutes = (rows: readonly NetworkOutput[]): Result<ReadonlyMap<string, string>, RuntimeError> =>
  foldResult(rows, NO_BINDINGS, (routes, o) => {
    const key = `${routeText(o["entityId"])}:${routeText(o["signerId"])}`;
    const runtimeId = netRuntimeId(o["runtimeId"]);
    const held = routes.get(key);
    switch (true) {
      case key === ":" || runtimeId === "":
        return frameErr("REPLAY_OUTPUT_RUNTIME_ROUTE_INVALID");
      case held !== undefined && held !== runtimeId:
        return frameErr(`REPLAY_OUTPUT_RUNTIME_ROUTE_CONFLICT:${key}`);
      default:
        return ok(mapSet(routes, key, runtimeId));
    }
  });


// Sealing: a frame that did work becomes one WAL row over its state and its retained outbox.

/** A sealed frame's outbox as its WAL row counts and digests it. */
type OutboxSeal = { readonly count: number; readonly digest: string };
const outboxSeal = (retained: readonly NetworkOutput[]): Result<OutboxSeal, RuntimeError> =>
  chain(traverse(retained, (o) => mapErr(encodeBinary(o), () => ROUTE_ENCODING_INVALID)), (rows) =>
    map(runtimeOutputsDigest(rows), (digest) => ({ count: rows.length, digest })));
type PostState = { readonly metaDigest: string; readonly postStateHash: string };
/** og storage post-state: replica metas, component digests and the outbox digest under one hash. */
const postStateOf = (
  after: Runtime,
  height: number,
  timestamp: number,
  outbox: OutboxSeal,
): Result<PostState, RuntimeError> =>
  chain(replicaMetaRows(after), (metaRows) => {
    const digests = all({
      metaDigest: replicaMetaDigest(metaRows),
      components: runtimeComponentDigests(runtimeView(after)),
    });
    return chain(digests, ({ metaDigest, components }) => {
      const hashed = storagePostStateHash({
        height,
        timestamp,
        replicaMetaDigest: metaDigest,
        runtimeComponentDigests: components,
        runtimeOutputCount: outbox.count,
        runtimeOutputsDigest: outbox.digest,
      });
      return map(hashed, (postStateHash) => ({ metaDigest, postStateHash }));
    });
  });
/** The Entities a frame's applied input touched, lowercased and sorted. */
const touchedEntities = (applied: RuntimeStep["applied"]): readonly string[] => {
  const inputs = applied.entityInputs.map((i) => lower(i.entityId));
  const imports = applied.runtimeTxs.flatMap((tx) => (tx.type === "importReplica" ? [lower(tx.entityId)] : []));
  return [...new Set([...inputs, ...imports])].toSorted(asc);
};
const sealFrame = (
  rt: Runtime,
  step: RuntimeStep,
  routes?: RuntimeRoutes,
): Result<RuntimeFrameCommit, RuntimeError> => {
  const after = step.runtime;
  const coordinates = all({ height: frameNumber(after.height), timestamp: frameNumber(after.timestamp) });
  return chain(coordinates, ({ height, timestamp }) =>
    chain(retainedNetworkOutbox(after, step.outbox, routes), (retained) =>
      chain(outboxSeal(retained), (outbox) =>
        chain(postStateOf(after, height, timestamp, outbox), ({ metaDigest, postStateHash }) =>
          chain(canonicalEntityHashes(after), (entityHashes) => {
            const body: StorageFrame = {
              height,
              timestamp,
              prevFrameHash: rt.frameHash,
              replicaMetaDigest: metaDigest,
              postStateHash,
              materializedState: false,
              canonicalStateHash: canonicalRuntimeStateHash(height, timestamp, entityHashes),
              canonicalEntityHashes: entityHashes,
              runtimeInput: binaryOf(step.applied),
              runtimeOutputCount: outbox.count,
              runtimeOutputsDigest: outbox.digest,
              touchedEntities: touchedEntities(step.applied),
              touchedAccounts: [],
              touchedBookEntities: [],
            };
            return map(storageFrameHash(body), (frameHash) => ({
              runtime: { ...after, frameHash, pendingNetworkOutputs: retained },
              frame: { ...body, frameHash },
              applied: step.applied,
              outbox: step.outbox,
              runtimeOutputs: retained,
              jOutbox: step.jOutbox,
              queuedRetries: step.queuedRetries,
              rejected: step.rejected,
            }));
          }),
        ),
      ),
    ),
  );
};
/**
 * og process + saveRuntimeFrame: apply one Runtime input and, when the frame advanced, seal its WAL row (prev hash
 * chain from ZERO_FRAME_HASH, canonical state hash, post-state oracle, ordered outbox digest). A frame that did no work
 * writes no row.
 */
export const commitRuntimeFrame = (
  rt: Runtime,
  input: RuntimeInput,
  ctx: RuntimeCtx,
): Result<RuntimeFrameCommit | null, RuntimeError> =>
  chain(applyRuntime(rt, input, ctx), (step) => (step.advanced ? sealFrame(rt, step, ctx.routes) : ok(null)));
/**
 * One host Runtime frame: `commit` is the frame (null when it did no work) and `deferred` are the inputs og's
 * entity-height barrier requeued, which the host carries at the front of its queue into the next frame (og puts them
 * ahead of its mempool, entity-height-barrier.ts:205). They are returned even when the frame did no work: og's mempool
 * keeps them either way.
 */
export type RuntimeFrameRun = {
  readonly commit: RuntimeFrameCommit | null;
  readonly deferred: readonly RoutedEntityInput[];
};
/**
 * og prepareRuntimeFrameInput (frame/lifecycle/prepare.ts:49-51) then process: the queued inputs are consensus-
 * prioritized against the frame-start replicas (og hasVerifiedEntityCommitPrecertificate), the entity-height barrier
 * keeps one merge group per certificate lane, and the rest is committed as commitRuntimeFrame. Replay never runs this:
 * a WAL row holds the input the barrier already selected.
 */
export const processRuntimeFrame = (
  rt: Runtime,
  input: RuntimeInput,
  ctx: RuntimeCtx,
): Result<RuntimeFrameRun, RuntimeError> => {
  const prioritized = prioritizeConsensusInputs(input.entityInputs, verifiedCommit(rt.entities, ctx));
  const barrier = entityHeightBarrier(rt.entities, input.runtimeTxs, prioritized);
  return chain(barrier, ({ selected, deferred }) =>
    map(commitRuntimeFrame(rt, { ...input, entityInputs: selected }, ctx), (commit) => ({ commit, deferred })),
  );
};


// Replay: the WAL tail verified row by row and replayed to the same bytes.

export type RuntimeRecovery = { readonly runtime: Runtime; readonly outbox: readonly EntityOutput[] };
type RecoveryCtx = Verifiers & Pick<RuntimeCtx, "routes">;
/**
 * og verifyStorageTailIntegrity for one row: it continues the chain, and its canonical state and frame hashes
 * recompute.
 */
const rowIntegrity = (runtime: Runtime, frame: StorageFrame): Result<void, RuntimeError> => {
  if (BigInt(frame.height) !== runtime.height + 1n) return frameErr("STORAGE_VERIFY_FRAME_HEIGHT_MISMATCH");
  if (frame.prevFrameHash !== runtime.frameHash) return frameErr("STORAGE_VERIFY_FRAME_CHAIN_BROKEN");
  const canonical = () => canonicalRuntimeStateHash(frame.height, frame.timestamp, frame.canonicalEntityHashes ?? []);
  if (frame.canonicalStateHash !== undefined && frame.canonicalStateHash !== canonical()) {
    return frameErr("STORAGE_VERIFY_CANONICAL_HASH_MISMATCH");
  }
  const own = storageFrameHash(frame);
  return own.ok && own.value === frame.frameHash ? ok(undefined) : frameErr("STORAGE_VERIFY_FRAME_HASH_MISMATCH");
};
type ReplaySeed = { readonly runtime: Runtime; readonly routes: RuntimeRoutes | undefined };
/**
 * og replayOneFrame seeding: the retained outbox a row's recorded outputs select, and the signers and Runtimes they
 * bind.
 */
const replaySeed = (
  runtime: Runtime,
  recorded: readonly NetworkOutput[] | undefined,
  height: number,
  routes: RuntimeRoutes | undefined,
): Result<ReplaySeed, RuntimeError> => {
  if (recorded === undefined) return ok({ runtime, routes });
  const evidence = all({
    retained: selectRetainedRecovery(runtime.pendingNetworkOutputs ?? [], recorded, height),
    hints: replaySignerHints(recorded, height),
    bound: replayOutputRoutes(recorded),
  });
  return map(evidence, ({ retained, hints, bound }): ReplaySeed => ({
    runtime: { ...runtime, pendingNetworkOutputs: retained },
    routes: {
      verifiedProfileSigner: (e) => routes?.verifiedProfileSigner(e),
      ...routes,
      replayRuntime: (e, signer) => bound.get(`${lower(e)}:${lower(signer)}`),
      replaySigner: (e) => hints.get(lower(e)),
    },
  }));
};
/**
 * One WAL row: verified, then replayed from its seed to the same frame hash; its recorded outputs become the retained
 * outbox.
 */
const replayRow = (
  ctx: RecoveryCtx,
  done: RuntimeRecovery,
  frame: StorageFrame,
  input: RuntimeInput,
  recorded: readonly NetworkOutput[] | undefined,
): Result<RuntimeRecovery, RuntimeError> =>
  chain(rowIntegrity(done.runtime, frame), () =>
    chain(replaySeed(done.runtime, recorded, frame.height, ctx.routes), (seed) => {
      const stamped = { ...input, timestamp: BigInt(frame.timestamp) };
      const replayed = commitRuntimeFrame(seed.runtime, stamped, { ...ctx, routes: seed.routes, replay: true });
      return chain(replayed, (commit) => {
        if (commit === null || commit.frame.frameHash !== frame.frameHash)
          return frameErr("STORAGE_REPLAY_POST_STATE_MISMATCH");
        const runtime =
          recorded === undefined ? commit.runtime : { ...commit.runtime, pendingNetworkOutputs: recorded };
        return ok({ runtime, outbox: [...done.outbox, ...commit.outbox] });
      });
    }),
  );
/**
 * og verifyStorageTailIntegrity + replay: every row continues the chain (height+1, prevFrameHash), its canonical state
 * hash recomputes from its own coordinates, and its frame hash recomputes; replaying its applied input (with replay
 * capabilities) must reproduce the row byte-for-byte. The recovered outbox is every replayed frame's ordered outputs
 * (nothing is terminal without a receipt) and must equal the persisted rows positionally. `rows`, when given, are each
 * frame's persisted runtime outputs (og frame.runtimeOutputs): og replayOneFrame seeds the retained outbox from the
 * prior evidence they select (og selectRetainedRecoveryOutbox, so transport retirements between frames replay) and
 * binds their Runtime routes.
 */
export const recoverRuntime = (
  checkpoint: Runtime,
  frames: readonly StorageFrame[],
  inputs: readonly RuntimeInput[],
  outbox: readonly EntityOutput[],
  ctx: RecoveryCtx,
  rows?: readonly (readonly NetworkOutput[])[],
): Result<RuntimeRecovery, RuntimeError> => {
  if (frames.length !== inputs.length) return frameErr("STORAGE_VERIFY_FRAME_INPUT_MISSING");
  if (rows !== undefined && rows.length !== frames.length) return frameErr("STORAGE_VERIFY_FRAME_OUTPUTS_MISSING");
  const start: RuntimeRecovery = { runtime: checkpoint, outbox: [] };
  const replayed = foldResult(frames, start, (done, frame, i) =>
    replayRow(ctx, done, frame, inputs[i] as RuntimeInput, rows?.[i]),
  );
  return chain(replayed, (done) =>
    canon(done.outbox) !== canon(outbox) ? frameErr("STORAGE_RECOVERY_OUTBOX_MISMATCH") : ok(done),
  );
};


// ---- the one-Account Host: an Account, its J state and its ladder, driven tx by tx ----

/**
 * og entity j-batch txs (r2r / r2c / r2e / e2r queue into jBatchState; j_broadcast seals it) and the finalized J events
 * that move reserves (entity-runtime ER-16).
 */
export type JOp =
  | { readonly type: "r2r"; readonly toEntity: EntityId; readonly tokenId: TokenId; readonly amount: bigint }
  | {
      readonly type: "r2c";
      readonly counterparty: EntityId;
      readonly tokenId: TokenId;
      readonly amount: bigint;
      readonly receivingEntity?: EntityId | undefined;
      readonly rebalanceFee?: RebalanceFee | undefined;
    }
  | { readonly type: "et2r"; readonly tokenAddress: string; readonly amount: bigint; readonly internalTokenId: TokenId }
  | { readonly type: "r2et"; readonly recipient: EntityId; readonly tokenId: TokenId; readonly amount: bigint }
  | { readonly type: "j_broadcast"; readonly chainId: number; readonly depository: string; readonly signerId: string }
  /**
   * og j_rebroadcast / j_abort_sent_batch / j_clear_batch / mintReserves (entity/tx/handlers/j-batch): the J submit
   * lifecycle.
   */
  | {
      readonly type: "j_rebroadcast";
      readonly chainId: number;
      readonly depository: string;
      readonly signerId: string;
      readonly gasBumpBps?: number | undefined;
    }
  | {
      readonly type: "j_abort_sent_batch";
      readonly reason?: string | undefined;
      readonly requeueToCurrent?: boolean | undefined;
    }
  | { readonly type: "j_clear_batch"; readonly reason?: string | undefined }
  | { readonly type: "mintReserves"; readonly tokenId: number; readonly amount: bigint }
  | { readonly type: "j_event"; readonly blockNumber: number; readonly event: JEvent };
/**
 * og EntityState reserves / outDebtsByToken / inDebtsByToken / jBatchState: reserves change only through finalized J
 * events.
 */
export type JState = {
  readonly reserves: ReadonlyMap<number, bigint>;
  readonly debts: DebtLedger;
  readonly jBatch: JSubmission;
};
export type LadderTx = {
  readonly type: "ladder_reveal";
  readonly revealer: EntityId;
  readonly counter: EntityId;
  readonly ladderHash: Hash;
  readonly targetRole: boolean;
  readonly fillRatio: number;
  readonly revealedAt: bigint;
};
export type EntityRouteTx =
  | {
      readonly type: "directPayment";
      readonly recipient: EntityId;
      readonly tokenId: TokenId;
      readonly amount: bigint;
      readonly description?: string | undefined;
      readonly invoiceId?: string | undefined;
    }
  | ({ readonly type: "placeSwapOffer" } & SwapOfferTerms);
export type HostInput = { readonly kind: "dispute" };
export type HostCtx = { readonly timestamp: bigint; readonly jHeight: bigint; readonly from?: EntityId | undefined };
/**
 * `j_submit`: og jOutputs `{jurisdictionName, jTxs:[jTx]}` plus the jBatch hash the Entity quorum signs;
 * `j_broadcast_request`: og finalizePendingBatch's self input `{entityTxs:[{type:"j_broadcast"}]}`.
 */
export type HostEffect =
  | Effect
  | Tagged<"start_dispute", { start: DisputeStart }>
  | Tagged<"send", { message: AccountPeerInput }>
  | Tagged<"j_submit", { jTx: JBatchTx | JMintTx; hashToSign?: JBatchHashToSign | undefined }>
  | Tagged<"j_broadcast_request", { entityId: string }>;
export type OutboxEntry = { readonly id: Hash; readonly effect: HostEffect };
export type HostTx =
  | { readonly layer: "account"; readonly tx: WireAccountTx }
  | { readonly layer: "frame"; readonly input: AccountInput }
  | { readonly layer: "j"; readonly tx: JOp }
  | { readonly layer: "ladder"; readonly tx: LadderTx }
  | { readonly layer: "entity"; readonly tx: EntityRouteTx }
  | { readonly layer: "input"; readonly input: HostInput }
  | { readonly layer: "receipt"; readonly id: Hash };
/**
 * `deltaTransformer`: og requireAccountDeltaTransformerAddress for the Host's Account (its Runtime's durable
 * jurisdiction stack; never committed).
 */
export type Host = {
  readonly self: EntityId;
  readonly account: AccountReplica;
  readonly j: JState;
  readonly ladder: ReadonlyMap<string, RatioRecord>;
  readonly height: bigint;
  readonly frameHash: RuntimeFrameHash;
  readonly outbox: readonly OutboxEntry[];
  readonly deltaTransformer?: DeltaTransformerRef | undefined;
};
export type HostError =
  | BodyError
  | Tagged<"unsigned" | "chain" | "root" | "version" | "reserve" | "status" | "recipient">
  | Tagged<"candidate", { cause: AccountReplicaError }>
  | JBatchError
  | JObserveError;
export type HostStep = Step<Host, HostEffect>;
export const genesisHost = (self: EntityId, account: AccountReplica): Result<Host, AccountReplicaError> =>
  map(partyOf(replicaId(account), self), () => ({
    self,
    account,
    j: { reserves: new Map(), debts: EMPTY_DEBTS, jBatch: DORMANT },
    ladder: new Map(),
    height: 0n,
    frameHash: ZERO_HASH as RuntimeFrameHash,
    outbox: [],
  }));
/** The Host's one Account seen through the door every Account input enters by. */
const hostDoor = (host: Host, ctx: HostCtx, verify: Verify): DoorContext => ({
  verify,
  self: host.self,
  now: ctx.timestamp,
  ...opt("deltaTransformer", host.deltaTransformer),
});


// The Host's J state: batch lifecycle and finalized J events.

const jEntityOf = (j: JState, self: EntityId, peer: string): JEntity => ({
  entityId: self,
  reserves: j.reserves,
  debts: j.debts,
  jBatch: j.jBatch,
  accounts: new Set([peer]),
});
/**
 * `release`: the Account latches a J recovery tx frees (og applyEntityAccountEnvelopeUpdate setRebalanceSubmittedAt /
 * replaceDisputeLifecycle).
 */
export type JApplied = {
  readonly j: JState;
  readonly effects: readonly HostEffect[];
  readonly release?: JLatchRelease | undefined;
};
const quietly = (j: JState): JApplied => ({ j, effects: [] });
const withBatch = (j: JState, jBatch: JSubmission): JState => ({ ...j, jBatch });
const queuedInto = (j: JState, queued: Result<JQueued, JBatchError>): Result<JApplied, HostError> =>
  map(queued, (q) => quietly(q._tag === "queued" ? withBatch(j, q.jBatch) : j));
/** A broadcast seals the batch and, when it produced a J tx, submits it for the quorum to sign. */
const submitted = (j: JState, b: Broadcast): JApplied => ({
  j: withBatch(j, b.jBatch),
  effects: b.jTx === undefined ? [] : [{ _tag: "j_submit", jTx: b.jTx, ...opt("hashToSign", b.hashToSign) }],
});
const recoveredBatch = (j: JState, r: JRecovered): JApplied => ({
  j: withBatch(j, r.jBatch),
  effects: [],
  release: r.release,
});
/** og's jNonce lookup for a sent batch's counterparty: only the Host's one Account has one. */
const hostJNonce = (account: AccountBody | undefined, peer: string) => (counterparty: string): number =>
  account !== undefined && counterparty === peer.toLowerCase() ? account.jNonce : 0;
/** The token ids the Host's one Account holds rebalance submissions for, by peer, as og clear reads them. */
const submittedTokens = (account: AccountBody | undefined, peer: string) =>
  account === undefined
    ? new Map()
    : new Map([[peer.toLowerCase(), [...(account.submittedAt ?? new Map<number, number>()).keys()]]]);
/**
 * HankoBatchProcessed retires the sent batch (and may ask for the next broadcast); any other J event moves reserves and
 * debts.
 */
const applyJEvent = (
  j: JState,
  self: EntityId,
  x: Extract<JOp, { readonly type: "j_event" }>,
  timestamp: number,
): Result<JApplied, HostError> => {
  if (x.event.type === "HankoBatchProcessed") {
    return map(applyHankoBatchProcessed(j.jBatch, self, x.event, timestamp), (b): JApplied => ({
      j: withBatch(j, b.jBatch),
      effects: b.autoBroadcast ? [{ _tag: "j_broadcast_request", entityId: self }] : [],
    }));
  }
  const observed = observeJBlocks(
    { entityId: self, reserves: j.reserves, debts: j.debts, accounts: new Map() },
    [{ blockNumber: x.blockNumber, events: [x.event] }],
  );
  return map(observed, (o) => quietly({ ...j, reserves: o.observer.reserves, debts: o.observer.debts }));
};
/**
 * og handleR2R / handleR2C / handleR2E / handleE2R / handleJBroadcast / handleJRebroadcast / handleJAbortSentBatch /
 * handleJClearBatch / handleMintReserves and the Entity's reserve, debt and HankoBatchProcessed J-event handlers, for
 * the Host's one Account.
 */
export const applyJ = (
  j: JState,
  op: JOp,
  self: EntityId,
  peer: string,
  ctx: HostCtx,
  account?: AccountBody,
): Result<JApplied, HostError> => {
  const e = jEntityOf(j, self, peer);
  const timestamp = Number(ctx.timestamp);
  return matchBy("type", op, {
    r2r: (x) => queuedInto(j, queueR2R(e, x.toEntity, Number(x.tokenId), x.amount)),
    r2c: (x) =>
      queuedInto(j, queueR2C(e, x.counterparty, Number(x.tokenId), x.amount, x.receivingEntity, x.rebalanceFee)),
    r2et: (x) => queuedInto(j, queueR2E(e, x.recipient, Number(x.tokenId), x.amount)),
    et2r: (x) =>
      queuedInto(
        j,
        queueE2R(e, { contractAddress: x.tokenAddress, amount: x.amount, internalTokenId: Number(x.internalTokenId) }),
      ),
    j_broadcast: (x) => {
      const target = { entityId: self, chainId: x.chainId, depository: x.depository, signerId: x.signerId, timestamp };
      return map(jBroadcast(j.jBatch, target), (b) => submitted(j, b));
    },
    j_rebroadcast: (x) => {
      const target = {
        entityId: self,
        chainId: x.chainId,
        depository: x.depository,
        signerId: x.signerId,
        timestamp,
        gasBumpBps: x.gasBumpBps,
      };
      return map(jRebroadcast(j.jBatch, target), (b) => submitted(j, b));
    },
    j_abort_sent_batch: (x) => ok(recoveredBatch(j, jAbortSentBatch(j.jBatch, x, hostJNonce(account, peer)))),
    j_clear_batch: (x) => ok(recoveredBatch(j, jClearBatch(j.jBatch, x, submittedTokens(account, peer)))),
    mintReserves: (x) =>
      ok({ j, effects: [{ _tag: "j_submit", jTx: mintReservesTx(self, x.tokenId, x.amount, timestamp).jTx }] }),
    j_event: (x) => applyJEvent(j, self, x, timestamp),
  });
};
/**
 * og releaseR2CSubmittedLatches / clear's submitted-marker reset on the Host's one Account (finalize latches: the
 * rewrite never sets finalizeQueued).
 */
const releaseLatches = (account: AccountReplica, peer: string, release: JLatchRelease | undefined): AccountReplica => {
  const mine = (release?.submitted ?? []).filter((r) => r.accountId === peer.toLowerCase());
  if (mine.length === 0) return account;
  return {
    ...account,
    state: mine.reduce((b, r) => setRebalanceSubmittedAt(b, r.tokenId, undefined), account.state),
  } as AccountReplica;
};


// Disputes: a dispute J event on the Host's Account lands on it as external finality.

type DisputeJEvent = Extract<JEvent, { readonly type: "DisputeStarted" | "DisputeFinalized" }>;
type DisputeJOp = { readonly blockNumber: number; readonly event: DisputeJEvent };
const disputeOpOf = (op: JOp): DisputeJOp | undefined =>
  op.type === "j_event" && (op.event.type === "DisputeStarted" || op.event.type === "DisputeFinalized")
    ? { blockNumber: op.blockNumber, event: op.event }
    : undefined;
/** og resolveDisputeAccountContext: the counterentity when we sent it, else the sender. */
const disputedPeer = (self: EntityId, e: DisputeJEvent): string =>
  e.sender.toLowerCase() === self.toLowerCase() ? e.counterentity.toLowerCase() : e.sender.toLowerCase();
const FROZEN_STATE_MISMATCH: JObserveError = { _tag: "j_observe", reason: "DISPUTE_FROZEN_ACCOUNT_STATE_MISMATCH" };
/** The frozen Account's current proof body hash, which the dispute's finality is built against. */
const frozenBodyHash = (host: Host) =>
  chain(mapErr(committedView(host.account.state), () => FROZEN_STATE_MISMATCH), (view) =>
    map(mapErr(localProof(view, host.deltaTransformer), () => FROZEN_STATE_MISMATCH), (p) => p.bodyHash));
/**
 * og j-events.ts applyDisputeStartedJEvent / applyDisputeFinalizedJEvent (J7 dispatch): a DisputeStarted /
 * DisputeFinalized event whose account (og resolveDisputeAccountContext: the counterentity when we sent it, else the
 * sender) is the Host's one Account becomes that Account's external_finality, built by disputeStartedInput /
 * disputeFinalizedInput against the frozen Account's current proof body. Other Accounts' events are og's
 * `account_missing` no-op. The Host's jBatchState then takes og's J-batch retirement (hostDisputeJBatch). Counter-proof
 * selection and HTLC / cross-j follow-ups run on the Entity path (disputeStartedJEvent); the one-Account Host holds no
 * HTLC route or cross-j book to follow up on.
 */
const disputeFinalityOf = (
  host: Host,
  d: DisputeJOp,
  peer: EntityId,
): Result<AccountFinality | undefined, HostError> => {
  if (disputedPeer(host.self, d.event) !== peer.toLowerCase()) return ok(undefined);
  return chain(frozenBodyHash(host), (frozenHash): Result<AccountFinality, HostError> => {
    const e = d.event;
    if (e.type === "DisputeStarted") return disputeStartedInput(e, d.blockNumber, frozenHash);
    const active = host.account._tag === "disputed" ? host.account.active : undefined;
    return disputeFinalizedInput(
      e,
      { jNonce: host.account.state.jNonce, ...opt("initialProposerIsLeft", active?.initialProposerIsLeft) },
      frozenHash,
    );
  });
};


// The Host's steps.

const ladderKey = (tx: LadderTx): string =>
  `${tx.revealer}|${tx.counter}|${tx.ladderHash}|${tx.targetRole ? "t" : "s"}`;
const admitTx = (host: Host, tx: WireAccountTx, ctx: HostCtx, verify: Verify): Result<HostStep, AccountReplicaError> =>
  map(admitAt(host.account, [tx], host.self, { timestamp: ctx.timestamp, jHeight: ctx.jHeight }, verify), (account) =>
    step({ ...host, account }));
const sendEffect = (message: AccountMessage): HostEffect => ({ _tag: "send", message });
/** An Account output as the Host's effect; the Account's plain messages stay with it. */
const hostEffectsOf = (o: AccountOutput): readonly HostEffect[] =>
  o.kind === "message"
    ? []
    : [matchBy("kind", o, {
        effect: (e) => e.effect,
        ack: sendEffect,
        ack_frame: sendEffect,
        start_dispute: ({ start }) => ({ _tag: "start_dispute", start }),
      })];
const accountStep = (
  host: Host,
  applied: Result<AccountApply, AccountReplicaError>,
): Result<HostStep, AccountReplicaError> =>
  map(applied, (a) => step({ ...host, account: a.replica }, a.outputs.flatMap(hostEffectsOf)));
const routeEntity = (tx: EntityRouteTx, self: EntityId, id: AccountId): Result<AccountTx, HostError> =>
  matchBy("type", tx, {
    directPayment: (x) => {
      const party = partyOf(id, self);
      return !party.ok || x.recipient !== party.value.peer
        ? err({ _tag: "recipient" })
        : ok({ type: "payment", tokenId: x.tokenId, amount: x.amount });
    },
    placeSwapOffer: ({ type: _, ...offer }) => ok({ type: "swap_offer", ...offer }),
    // og htlcPayment and the cross-j setup (prepare / materialize / register, foldTx) are Entity txs,
    // never a one-Account Host route.
  });
/**
 * A J op moves the Host's J state and frees its latches; a dispute event on its Account also lands there, then retires
 * the J batch.
 */
const applyHostJ = (
  host: Host,
  op: JOp,
  ctx: HostCtx,
  verify: Verify,
): Result<HostStep, AccountReplicaError | HostError> =>
  chain(partyOf(replicaId(host.account), host.self), (party) =>
    chain(applyJ(host.j, op, host.self, party.peer, ctx, host.account.state), ({ j, effects, release }) => {
      const moved: Host = { ...host, j, account: releaseLatches(host.account, party.peer, release) };
      const dispute = disputeOpOf(op);
      const finality = dispute === undefined ? ok(undefined) : disputeFinalityOf(host, dispute, party.peer);
      return chain(finality, (f): Result<HostStep, AccountReplicaError | HostError> => {
        if (dispute === undefined || f === undefined) return ok(step(moved, effects));
        const envelope = envelopeOf(host.account.state.terms, party);
        const landed = accountStep(
          moved,
          applyAccountInput(
            host.account,
            { kind: "external_finality", ...envelope, finality: f },
            hostDoor(host, ctx, verify),
          ),
        );
        const withFinality = map(landed, (s) => step(s.state, [...effects, ...s.effects]));
        return chain(withFinality, (s) =>
          map(hostDisputeJBatch(s.state.j, host.self, dispute.event), (b) =>
            step({ ...s.state, j: b.j }, [...s.effects, ...b.effects]),
          ),
        );
      });
    }),
  );
export const applyHost = (
  host: Host,
  tx: HostTx,
  ctx: HostCtx,
  verify: Verify,
): Result<HostStep, AccountReplicaError | HostError> =>
  matchBy("layer", tx, {
    account: (i) => admitTx(host, i.tx, ctx, verify),
    frame: (i) => {
      const delivery: Delivery = ctx.from === undefined ? { _tag: "local" } : { _tag: "received", from: ctx.from };
      const door = hostDoor(host, ctx, verify);
      return accountStep(
        host,
        disputeUnsafe(host.account, applyDelivered(host.account, i.input, delivery, door), door),
      );
    },
    j: (i) => applyHostJ(host, i.tx, ctx, verify),
    ladder: (i) => {
      const key = ladderKey(i.tx);
      return map(revealSlot(host.ladder.get(key), i.tx), (slot) =>
        step({ ...host, ladder: mapSet(host.ladder, key, slot) }),
      );
    },
    entity: (i) =>
      chain(routeEntity(i.tx, host.self, replicaId(host.account)), (routed) => admitTx(host, routed, ctx, verify)),
    input: (i) =>
      matchBy("kind", i.input, {
        dispute: () =>
          accountStep(host, applyAccountInput(host.account, { kind: "freeze" }, hostDoor(host, ctx, verify))),
      }),
    receipt: (i) => ok(step({ ...host, outbox: host.outbox.filter((e) => e.id !== i.id) })),
  });

// ---- watchtower ----
// og storage/recovery/bundle/{types,crypto}.ts, watchtower/http.ts verifyTowerAppointment,
// watchtower/store/{appointments,decode,db}.ts
// The HTTP body reader, LevelDB, the store-wide quotas (maxLookupKeys, maxTotalStoredBytes), push, sweep and the
// on-chain action are I/O: the stored lookup document is threaded as a value, and the tower's clock and key are inputs.
export type TowerModeV1 = "blind_backup" | "delayed_last_resort";
export type EncryptedRuntimeRecoveryBundleV1 = {
  readonly version: 1;
  readonly kind?: "snapshot" | "journal_tail" | undefined;
  readonly runtimeId: string;
  readonly lookupKey: string;
  readonly height: number;
  readonly createdAt: number;
  readonly bundleHash: string;
  readonly baseRuntimeHeight?: number | undefined;
  readonly baseCheckpointHash?: string | undefined;
  readonly iv: string;
  readonly ciphertext: string;
  readonly compression?: "gzip" | undefined;
};
export type TowerLastResortWatchV1 = {
  readonly rpcUrl: string;
  readonly chainId: number;
  readonly depositoryAddress: string;
  readonly watchedEntityId: string;
  readonly counterentity: string;
};
export type TowerLastResortPayloadV1 = {
  readonly triggerHint: string;
  readonly watch: TowerLastResortWatchV1;
  readonly encryptedRemedy: string;
  readonly actionKind: "counter_dispute_only";
  readonly appointmentSequence: number;
  readonly proofNonce: number;
  readonly proofBodyHash: string;
  readonly responseMode: "last_resort";
  readonly lastResortWindowSeconds: number;
  readonly maxFeeToken?: string | undefined;
  readonly feeBudget?: string | undefined;
};
export type TowerAppointmentOwnerProofV1 = {
  readonly runtimeId: string;
  readonly signedAt: number;
  readonly signature: string;
};
export type TowerAppointmentV1 = {
  readonly type: "tower_appointment";
  readonly version: 1;
  readonly towerMode?: TowerModeV1 | undefined;
  readonly lookupKey: string;
  readonly slot?: number | undefined;
  readonly bundle: EncryptedRuntimeRecoveryBundleV1;
  readonly lastResortPayload?: TowerLastResortPayloadV1 | undefined;
  readonly ownerProof: TowerAppointmentOwnerProofV1;
};
export type TowerReceiptV1 = {
  readonly type: "tower_receipt";
  readonly version: 1;
  readonly towerId: string;
  readonly lookupKey: string;
  readonly runtimeId: string;
  readonly height: number;
  readonly bundleHash: string;
  readonly towerMode?: TowerModeV1 | undefined;
  readonly slot?: number | undefined;
  readonly storedAt?: number | undefined;
  readonly receivedAt: number;
  readonly expiresAt?: number | undefined;
  readonly sequence: number;
  readonly retainedSlots: number;
  readonly storedBytes?: number | undefined;
  readonly maxStoredBytes?: number | undefined;
  readonly quotaOk?: boolean | undefined;
  readonly appointmentSequence?: number | null | undefined;
  readonly towerSignature?: string | undefined;
};
export type TowerStoredBundle = {
  readonly slot: number;
  readonly towerMode: TowerModeV1;
  readonly bundle: EncryptedRuntimeRecoveryBundleV1;
  readonly ownerSignedAt: number;
  readonly encryptedEnvelopeHash: string;
  readonly lastResortPayloadDigest: string;
  readonly lastResortPayload?: TowerLastResortPayloadV1 | undefined;
};
/** og StoredLookupDoc: one lookup key's receipts (newest first) and retained bundles. */
export type TowerLookupDoc = {
  readonly lookupKey: string;
  readonly runtimeId: string;
  readonly updatedAt: number;
  readonly receipts: readonly TowerReceiptV1[];
  readonly bundles: readonly TowerStoredBundle[];
};
/**
 * og WatchtowerStoreContext minus I/O: `now` is the one `context.now()` reading for this write, `towerPrivateKey` og's
 * `signer`.
 */
export type TowerStoreConfig = {
  readonly towerId: string;
  readonly towerPrivateKey: Uint8Array;
  readonly maxBundlesPerLookupKey: number;
  readonly maxStoredBytesPerLookupKey: number;
  readonly receiptTtlMs: number;
  readonly now: number;
};
/** `code` is og's thrown message. */
export type TowerError = Tagged<"tower", { code: string }>;
type Rec = { readonly [k: string]: unknown };
const towerErr = (code: string): Result<never, TowerError> => err({ _tag: "tower", code });
const errorCode = (r: Result<unknown, TowerError>): string | undefined => (r.ok ? undefined : r.error.code);


// Boundary checks: og throws the first failure, so each check is lazy and names its failure or nothing.

type BoundaryCheck = () => string | undefined;
const codeIf = (failed: boolean, code: string): string | undefined => (failed ? code : undefined);
/** The first failing check, as og's first throw; later checks are not run. */
const firstThrown = (...checks: readonly BoundaryCheck[]): string | undefined => firstDefined(...checks);
const towerChecks = (...checks: readonly BoundaryCheck[]): Result<void, TowerError> => {
  const code = firstThrown(...checks);
  return code === undefined ? ok(undefined) : towerErr(code);
};
/** og requireBoundaryRecord. */
const plainRecord = (v: unknown): v is Rec => {
  if (!v || typeof v !== "object" || Array.isArray(v) || v instanceof Map) return false;
  const proto = Object.getPrototypeOf(v);
  return proto === Object.prototype || proto === null;
};
/** og requireExactBoundaryKeys. */
const exactKeys = (
  r: Rec,
  required: readonly string[],
  optional: readonly string[],
  code: string,
): string | undefined => {
  const allowed = new Set([...required, ...optional]);
  const missing = required.filter((k) => !Object.hasOwn(r, k));
  const extra = Object.keys(r).filter((k) => !allowed.has(k));
  const listed = (keys: readonly string[]): string => keys.join(",") || "none";
  return codeIf(missing.length > 0 || extra.length > 0, `${code}:missing=${listed(missing)}:extra=${listed(extra)}`);
};
/** A boundary record: exactly its fields, with og's codes for a non-record and for wrong fields. */
type RecordShape = {
  readonly required: readonly string[];
  readonly optional: readonly string[];
  readonly invalid: string;
  readonly fieldsInvalid: string;
};
const fieldsCode = (r: Rec, shape: RecordShape): string | undefined =>
  exactKeys(r, shape.required, shape.optional, shape.fieldsInvalid);
const shapeCode = (v: unknown, shape: RecordShape): string | undefined =>
  plainRecord(v) ? fieldsCode(v, shape) : shape.invalid;
const BUNDLE_FIELDS = ["version", "runtimeId", "lookupKey", "height", "createdAt", "bundleHash", "iv", "ciphertext"];
const BUNDLE_OPTIONAL = ["kind", "baseRuntimeHeight", "baseCheckpointHash", "compression"];
const APPOINTMENT_SHAPE: RecordShape = {
  required: ["type", "version", "lookupKey", "bundle", "ownerProof"],
  optional: ["towerMode", "slot", "lastResortPayload"],
  invalid: "TOWER_APPOINTMENT_INVALID",
  fieldsInvalid: "TOWER_APPOINTMENT_FIELDS_INVALID",
};
const BUNDLE_SHAPE: RecordShape = {
  required: BUNDLE_FIELDS,
  optional: BUNDLE_OPTIONAL,
  invalid: "TOWER_BUNDLE_INVALID",
  fieldsInvalid: "TOWER_BUNDLE_FIELDS_INVALID",
};
const OWNER_PROOF_SHAPE: RecordShape = {
  required: ["runtimeId", "signedAt", "signature"],
  optional: [],
  invalid: "TOWER_APPOINTMENT_OWNER_PROOF_INVALID",
  fieldsInvalid: "TOWER_APPOINTMENT_OWNER_PROOF_FIELDS_INVALID",
};
const LAST_RESORT_PAYLOAD_SHAPE: RecordShape = {
  required: [
    "triggerHint",
    "watch",
    "encryptedRemedy",
    "actionKind",
    "appointmentSequence",
    "proofNonce",
    "proofBodyHash",
    "responseMode",
    "lastResortWindowSeconds",
  ],
  optional: ["maxFeeToken", "feeBudget"],
  invalid: "TOWER_LAST_RESORT_PAYLOAD_INVALID",
  fieldsInvalid: "TOWER_LAST_RESORT_PAYLOAD_FIELDS_INVALID",
};
const WATCH_SHAPE: RecordShape = {
  required: ["rpcUrl", "chainId", "depositoryAddress", "watchedEntityId", "counterentity"],
  optional: [],
  invalid: "TOWER_LAST_RESORT_PAYLOAD_WATCH_MISSING",
  fieldsInvalid: "TOWER_LAST_RESORT_PAYLOAD_WATCH_FIELDS_INVALID",
};
const STORED_LOOKUP_SHAPE: RecordShape = {
  required: ["lookupKey", "runtimeId", "updatedAt", "receipts", "bundles"],
  optional: [],
  invalid: "TOWER_STORED_LOOKUP_INVALID",
  fieldsInvalid: "TOWER_STORED_LOOKUP_FIELDS_INVALID",
};
const STORED_RECEIPT_SHAPE: RecordShape = {
  required: [
    "type",
    "version",
    "towerId",
    "lookupKey",
    "runtimeId",
    "height",
    "bundleHash",
    "receivedAt",
    "sequence",
    "retainedSlots",
  ],
  optional: [
    "towerMode",
    "slot",
    "storedAt",
    "expiresAt",
    "storedBytes",
    "maxStoredBytes",
    "quotaOk",
    "appointmentSequence",
    "towerSignature",
  ],
  invalid: "TOWER_STORED_RECEIPT_INVALID",
  fieldsInvalid: "TOWER_STORED_RECEIPT_FIELDS_INVALID",
};
const STORED_ENTRY_SHAPE: RecordShape = {
  required: ["slot", "towerMode", "bundle", "ownerSignedAt", "encryptedEnvelopeHash", "lastResortPayloadDigest"],
  optional: ["lastResortPayload"],
  invalid: "TOWER_STORED_BUNDLE_ENTRY_INVALID",
  fieldsInvalid: "TOWER_STORED_BUNDLE_ENTRY_FIELDS_INVALID",
};
const STORED_BUNDLE_SHAPE: RecordShape = {
  required: BUNDLE_FIELDS,
  optional: BUNDLE_OPTIONAL,
  invalid: "TOWER_STORED_BUNDLE_INVALID",
  fieldsInvalid: "TOWER_STORED_BUNDLE_FIELDS_INVALID",
};


// Values as og coerces them at the boundary.

const jsText = (v: unknown): string => String(v || "");
const jsInt = (v: unknown): number => Math.max(0, Math.floor(Number(v || 0)));
/** og's slot: `?? 0`, so only a missing slot is zero before the floor. */
const slotOf = (v: unknown): number => Math.max(0, Math.floor(Number(v ?? 0)));
/** og normalizeTowerModeV1. */
export const normalizeTowerMode = (mode: unknown): Result<TowerModeV1, TowerError> => {
  const raw = jsText(mode).trim();
  switch (raw) {
    case "":
    case "blind_backup":
      return ok("blind_backup");
    case "delayed_last_resort":
      return ok("delayed_last_resort");
    default:
      return towerErr(`TOWER_MODE_INVALID:${raw}`);
  }
};
const LOWER_HEX_BYTES = /^0x([0-9a-f]{2})*$/;
const towerLookupKey = (v: unknown): Result<string, TowerError> => {
  const k = jsText(v).trim().toLowerCase();
  return WORD32.test(k) ? ok(k) : towerErr(`TOWER_LOOKUP_KEY_INVALID: ${String(v)}`);
};
const bytes32Code = (v: unknown, label: string): string | undefined =>
  codeIf(!WORD32.test(jsText(v).trim().toLowerCase()), `TOWER_${label}_INVALID: ${String(v)}`);
const hexBytesCode = (v: unknown, label: string): string | undefined =>
  codeIf(!LOWER_HEX_BYTES.test(jsText(v).trim().toLowerCase()), `TOWER_${label}_INVALID`);
const nonNegative = (v: unknown): number | undefined => {
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 ? Math.floor(n) : undefined;
};
const nonNegativeCode = (v: unknown, label: string): string | undefined =>
  codeIf(nonNegative(v) === undefined, `TOWER_${label}_INVALID`);
const positiveCode = (v: unknown, label: string): string | undefined => {
  const n = nonNegative(v);
  return codeIf(n === undefined || n <= 0, `TOWER_${label}_INVALID`);
};
const safeIntCode = (v: unknown, code: string): string | undefined =>
  codeIf(typeof v !== "number" || !Number.isSafeInteger(v) || v < 0, code);
const optionalSafeIntCode = (v: unknown, code: string): string | undefined =>
  v === undefined || v === null ? undefined : safeIntCode(v, code);
const textCode = (v: unknown, code: string): string | undefined =>
  codeIf(typeof v !== "string" || v.trim().length === 0, code);


// Hashes and signed messages.

const towerHashText = (text: string): string => keccak256Hex(utf8(text));
/** og computeEncryptedRuntimeRecoveryEnvelopeHash: keccak of the tagged-JSON envelope. */
export const towerEnvelopeHash = (bundle: EncryptedRuntimeRecoveryBundleV1): string =>
  towerHashText(stableJson(bundle));
/** og computeTowerLastResortPayloadDigest: ZeroHash when absent. */
export const towerPayloadDigest = (payload: TowerLastResortPayloadV1 | null | undefined): string =>
  payload ? towerHashText(stableJson(payload)) : ZERO_WORD;
/** og buildTowerAppointmentOwnerMessage. */
export const towerAppointmentOwnerMessage = (
  runtimeId: string,
  towerMode: TowerModeV1,
  lookupKey: string,
  slot: number,
  bundle: EncryptedRuntimeRecoveryBundleV1,
  signedAt: number,
  payload?: TowerLastResortPayloadV1 | null,
): string =>
  [
    "xln:tower:appointment:v1",
    runtimeId.toLowerCase(),
    towerMode,
    lookupKey,
    jsInt(slot),
    towerEnvelopeHash(bundle),
    jsInt(signedAt),
    towerPayloadDigest(payload),
  ].join("|");
/** og appointments.ts buildReceiptMessage. */
export const towerReceiptMessage = (r: TowerReceiptV1): string =>
  [
    "xln:watchtower:receipt:v1",
    r.towerId,
    r.lookupKey,
    r.runtimeId,
    r.height,
    r.bundleHash,
    jsInt(r.sequence),
    jsInt(r.slot),
    String(r.towerMode || "blind_backup"),
    jsInt(r.storedBytes),
    jsInt(r.maxStoredBytes),
    jsInt(r.expiresAt),
  ].join("|");
const eip191Digest = (message: string): Uint8Array => {
  const body = utf8(message);
  return keccak256(concat([utf8(`\x19Ethereum Signed Message:\n${body.length}`), body]));
};
const hexWord = (n: bigint): string => n.toString(16).padStart(64, "0");
/** ethers Wallet.signMessage: EIP-191, RFC 6979 low-s, v = 27 + parity. */
export const signPersonalMessage = (message: string, privateKey: Uint8Array): string => {
  const s = signRaw(eip191Digest(message), privateKey);
  return joinHex([hexWord(s.r), hexWord(s.s), (27 + s.recovery).toString(16)]);
};
/** A signature's r, s and v: 65 bytes as they are, 64 bytes (EIP-2098) with v folded into the top bit of s. */
type SplitSignature = { readonly r: Uint8Array; readonly s: Uint8Array; readonly v: number };
const splitSignature = (bytes: Uint8Array): SplitSignature | undefined => {
  const r = bytes.slice(0, 32);
  const s = bytes.slice(32, 64);
  const top = s[0] ?? 0;
  switch (bytes.length) {
    case 65:
      return { r, s, v: bytes[64] ?? 0 };
    case 64:
      return { r, s: Uint8Array.of(top & 0x7f, ...s.subarray(1)), v: top & 0x80 ? 28 : 27 };
    default:
      return undefined;
  }
};
/** The recovery parity a v byte names (0/1, 27/28 or EIP-155), or undefined where ethers throws. */
const parityOfV = (v: number): 0 | 1 | undefined => {
  switch (true) {
    case v === 0 || v === 27:
      return 0;
    case v === 1 || v === 28:
      return 1;
    case v >= 35:
      return v & 1 ? 0 : 1;
    default:
      return undefined;
  }
};
/**
 * ethers verifyMessage (Signature.from: 64-byte EIP-2098 or 65-byte with v 0/1/27/28/EIP-155): the lowercase signer, or
 * undefined where ethers throws.
 */
export const recoverPersonalMessage = (message: string, signature: string): string | undefined => {
  const sig = EVEN_HEX.test(signature) ? splitSignature(hexToBytes(signature)) : undefined;
  const parity = sig === undefined ? undefined : parityOfV(sig.v);
  if (sig === undefined || parity === undefined) return undefined;
  const pub = recoverPublicKey(eip191Digest(message), sig.r, sig.s, parity);
  return pub === null ? undefined : addressOf(pub).toLowerCase();
};
const ibanDigits = (c: string): string => (/[0-9]/.test(c) ? c : String(c.charCodeAt(0) - 55));
/** A long decimal string mod 97, folded 15 digits at a time as ethers does. */
const mod97 = (digits: string): number =>
  digits.length >= 15
    ? mod97(String(parseInt(digits.substring(0, 15), 10) % 97) + digits.substring(15))
    : parseInt(digits, 10) % 97;
const ibanChecksum = (address: string): string => {
  const upper = address.toUpperCase();
  const expanded = [...`${upper.substring(4)}${upper.substring(0, 2)}00`].map(ibanDigits).join("");
  return String(98 - mod97(expanded)).padStart(2, "0");
};
const ETHERS_HEX_ADDRESS = /^(0x)?[0-9a-fA-F]{40}$/;
const MIXED_CASE = /([A-F].*[a-f])|([a-f].*[A-F])/;
const DIRECT_ICAP = /^XE[0-9]{2}[0-9A-Za-z]{30,31}$/;
/** ethers isAddress: hex with optional 0x (mixed case must checksum), or a direct-mode ICAP. */
export const isEthersAddress = (value: string): boolean => {
  if (ETHERS_HEX_ADDRESS.test(value)) {
    const a = value.startsWith("0x") ? value : `0x${value}`;
    return !MIXED_CASE.test(a) || checksum(a) === a;
  }
  return DIRECT_ICAP.test(value) && value.substring(2, 4) === ibanChecksum(value);
};


// The HTTP appointment: exact envelope, sound bundle, bound owner, mode rules, owner signature.

/** og http.ts decodeTowerAppointmentEnvelope: exact fields before any signed value is read. */
const towerEnvelopeCode = (a: Rec): string | undefined => {
  const payload = a["lastResortPayload"];
  return firstThrown(
    () => fieldsCode(a, APPOINTMENT_SHAPE),
    () => codeIf(a["type"] !== "tower_appointment" || a["version"] !== 1, "TOWER_APPOINTMENT_INVALID"),
    () => shapeCode(a["bundle"], BUNDLE_SHAPE),
    () => shapeCode(a["ownerProof"], OWNER_PROOF_SHAPE),
    () => (payload === undefined ? undefined : shapeCode(payload, LAST_RESORT_PAYLOAD_SHAPE)),
    () => (payload === undefined ? undefined : shapeCode((payload as Rec)["watch"], WATCH_SHAPE)),
  );
};
/** og http.ts verifyEncryptedBundleShape. */
const towerBundleShapeCode = (b: Rec): string | undefined =>
  firstThrown(
    () => codeIf(b["version"] !== 1, "TOWER_BUNDLE_VERSION_UNSUPPORTED"),
    () => codeIf(!jsText(b["runtimeId"]).trim(), "TOWER_BUNDLE_RUNTIME_ID_REQUIRED"),
    () => errorCode(towerLookupKey(b["lookupKey"])),
    () => nonNegativeCode(b["height"], "BUNDLE_HEIGHT"),
    () => nonNegativeCode(b["createdAt"], "BUNDLE_CREATED_AT"),
    () => bytes32Code(b["bundleHash"], "BUNDLE_HASH"),
    () => hexBytesCode(b["iv"], "BUNDLE_IV"),
    () => hexBytesCode(b["ciphertext"], "BUNDLE_CIPHERTEXT"),
    () => codeIf(jsText(b["ciphertext"]).trim().length <= 2, "TOWER_BUNDLE_CIPHERTEXT_EMPTY"),
    () => codeIf(
      b["compression"] !== undefined && b["compression"] !== "gzip",
      `TOWER_BUNDLE_COMPRESSION_UNSUPPORTED: ${String(b["compression"])}`,
    ),
  );
/** og's sealed remedy: a `tower_encrypted_payload` v1 record under watch-seed AES-256-GCM. */
const isSealedRemedy = (v: unknown): boolean =>
  plainRecord(v) &&
  v["type"] === "tower_encrypted_payload" &&
  v["version"] === 1 &&
  v["alg"] === "watch-seed-aes-256-gcm" &&
  typeof v["iv"] === "string" &&
  typeof v["ciphertext"] === "string";
/** og assertEncryptedLastResortPayload: `encryptedRemedy` is a tagged-JSON sealed remedy. */
const encryptedRemedyCode = (payload: Rec | undefined): string | undefined => {
  const raw = jsText(payload?.["encryptedRemedy"]).trim();
  if (!raw) return "TOWER_LAST_RESORT_PAYLOAD_REMEDY_MISSING";
  const parsed = parseTaggedJson(raw);
  return codeIf(!(parsed.ok && isSealedRemedy(parsed.value)), "TOWER_LAST_RESORT_PAYLOAD_REMEDY_NOT_ENCRYPTED");
};
const HTTP_URL = /^https?:\/\//i;
/**
 * og http.ts verifyLastResortWatch: an http(s) RPC, a positive chain, an ethers address depository and two bytes32
 * Entities.
 */
const lastResortWatchCode = (watch: Rec): string | undefined => {
  const rpcUrl = jsText(watch["rpcUrl"]).trim();
  return firstThrown(
    () =>
      codeIf(!rpcUrl || rpcUrl.length > 512 || !HTTP_URL.test(rpcUrl), "TOWER_LAST_RESORT_PAYLOAD_WATCH_RPC_INVALID"),
    () => positiveCode(watch["chainId"], "LAST_RESORT_PAYLOAD_WATCH_CHAIN_ID"),
    () =>
      codeIf(
        !isEthersAddress(jsText(watch["depositoryAddress"])),
        "TOWER_LAST_RESORT_PAYLOAD_WATCH_DEPOSITORY_INVALID",
      ),
    () => bytes32Code(watch["watchedEntityId"], "LAST_RESORT_PAYLOAD_WATCH_ENTITY"),
    () => bytes32Code(watch["counterentity"], "LAST_RESORT_PAYLOAD_WATCH_COUNTERENTITY"),
  );
};
/** og http.ts verifyLastResortPayload + verifyLastResortWatch. */
const lastResortPayloadCode = (p: Rec | undefined): string | undefined => {
  if (!p) return "TOWER_LAST_RESORT_PAYLOAD_MISSING";
  if (p["actionKind"] !== "counter_dispute_only") return "TOWER_LAST_RESORT_PAYLOAD_ACTION_KIND_UNSUPPORTED";
  if (p["responseMode"] !== "last_resort") return "TOWER_LAST_RESORT_PAYLOAD_RESPONSE_MODE_UNSUPPORTED";
  const watch = p["watch"];
  if (!watch || typeof watch !== "object") return "TOWER_LAST_RESORT_PAYLOAD_WATCH_MISSING";
  const hint = jsText(p["triggerHint"]).trim();
  return firstThrown(
    () => lastResortWatchCode(watch as Rec),
    () => codeIf(!hint || hint.length > 256, "TOWER_LAST_RESORT_PAYLOAD_TRIGGER_HINT_INVALID"),
    () => positiveCode(p["appointmentSequence"], "LAST_RESORT_PAYLOAD_APPOINTMENT_SEQUENCE"),
    () => positiveCode(p["proofNonce"], "LAST_RESORT_PAYLOAD_PROOF_NONCE"),
    () => bytes32Code(p["proofBodyHash"], "LAST_RESORT_PAYLOAD_PROOF_BODY_HASH"),
    () => positiveCode(p["lastResortWindowSeconds"], "LAST_RESORT_PAYLOAD_LAST_RESORT_WINDOW"),
    () => encryptedRemedyCode(p),
  );
};
/** og http.ts mode rules: a blind backup carries no payload; a delayed last resort carries a sound one. */
const appointmentModeCode = (towerMode: TowerModeV1, payload: Rec | undefined): string | undefined => {
  switch (towerMode) {
    case "blind_backup":
      return codeIf(Boolean(payload), "TOWER_BACKUP_LAST_RESORT_PAYLOAD_FORBIDDEN");
    case "delayed_last_resort":
      return lastResortPayloadCode(payload);
  }
};
export const TOWER_APPOINTMENT_MAX_CLOCK_SKEW_MS = 24 * 60 * 60 * 1000;
/** The owner an appointment's proof names, and when the owner signed. */
type OwnerClaim = { readonly runtimeId: string; readonly signedAt: number };
/** og: the proof names the bundle's runtime under the requested key, signed within a day of the tower's clock. */
const ownerClaimOf = (bundle: Rec, proof: Rec, lookupKey: string, nowMs: number): Result<OwnerClaim, TowerError> => {
  const runtimeId = jsText(proof["runtimeId"]).trim().toLowerCase();
  const signedAt = jsInt(proof["signedAt"]);
  const bound = towerChecks(
    () => codeIf(bundle["lookupKey"] !== lookupKey, "TOWER_APPOINTMENT_LOOKUP_MISMATCH"),
    () => codeIf(
      !runtimeId || runtimeId !== jsText(bundle["runtimeId"]).trim().toLowerCase(),
      "TOWER_APPOINTMENT_RUNTIME_ID_MISMATCH",
    ),
    () => codeIf(!Number.isSafeInteger(signedAt) || signedAt <= 0, "TOWER_APPOINTMENT_SIGNED_AT_INVALID"),
    () => codeIf(Math.abs(nowMs - signedAt) > TOWER_APPOINTMENT_MAX_CLOCK_SKEW_MS, "TOWER_APPOINTMENT_STALE"),
  );
  return map(bound, () => ({ runtimeId, signedAt }));
};
const ownerSignatureCode = (message: string, signature: string, runtimeId: string): string | undefined => {
  const recovered = recoverPersonalMessage(message, signature);
  if (recovered === undefined) return "TOWER_APPOINTMENT_SIGNATURE_UNREADABLE";
  return codeIf(
    recovered !== runtimeId,
    `TOWER_APPOINTMENT_SIGNATURE_INVALID: recovered=${recovered} expected=${runtimeId}`,
  );
};
/**
 * og http.ts verifyTowerAppointment: exact envelope, bundle shape, lookup/runtime binding, owner clock within 24h of
 * the tower clock `nowMs`, mode/payload rules, and the owner's EIP-191 signature recovering `ownerProof.runtimeId`.
 * Returns og's normalized appointment.
 */
export const verifyTowerAppointment = (input: unknown, nowMs: number): Result<TowerAppointmentV1, TowerError> => {
  if (!plainRecord(input)) return towerErr(APPOINTMENT_SHAPE.invalid);
  const a = input as unknown as TowerAppointmentV1;
  const bundle = input["bundle"] as Rec;
  const proof = input["ownerProof"] as Rec;
  const shaped = towerChecks(
    () => towerEnvelopeCode(input),
    () => towerBundleShapeCode(bundle),
  );
  const owned = chain(shaped, () =>
    chain(towerLookupKey(a.lookupKey), (lookupKey) =>
      map(ownerClaimOf(bundle, proof, lookupKey, nowMs), (owner) => ({ lookupKey, ...owner })),
    ),
  );
  return chain(owned, ({ lookupKey, runtimeId, signedAt }) =>
    chain(normalizeTowerMode(input["towerMode"]), (towerMode) => {
      const slot = slotOf(input["slot"]);
      const signature = jsText(proof["signature"]);
      const message = (): string =>
        towerAppointmentOwnerMessage(runtimeId, towerMode, lookupKey, slot, a.bundle, signedAt, a.lastResortPayload);
      const signed = towerChecks(
        () => appointmentModeCode(towerMode, input["lastResortPayload"] as Rec | undefined),
        () => ownerSignatureCode(message(), signature, runtimeId),
      );
      return map(signed, () => ({
        ...a,
        towerMode,
        lookupKey,
        slot,
        ownerProof: { ...a.ownerProof, runtimeId, signedAt, signature },
        bundle: {
          ...a.bundle,
          runtimeId,
          lookupKey,
          height: jsInt(bundle["height"]),
          createdAt: jsInt(bundle["createdAt"]),
        },
      }));
    }),
  );
};


// The store: one lookup document per key, its bundles retained per (slot, mode, kind) and every write receipted.

export const emptyTowerLookupDoc = (lookupKey: string): TowerLookupDoc => ({
  lookupKey,
  runtimeId: "",
  updatedAt: 0,
  receipts: [],
  bundles: [],
});
/** og computeStoredLookupBytes: UTF-8 bytes of the tagged-JSON document. */
export const towerLookupBytes = (doc: TowerLookupDoc): number => utf8(stableJson(doc)).length;
const quotaExceeded = (bytes: number, cfg: TowerStoreConfig): Result<never, TowerError> =>
  towerErr(`TOWER_QUOTA_EXCEEDED: bytes=${bytes} max=${cfg.maxStoredBytesPerLookupKey}`);
const bundleKind = (b: EncryptedRuntimeRecoveryBundleV1): string => b.kind ?? "snapshot";
/** og sortStoredBundles: height, then createdAt, then slot, all descending (stable). */
const sortTowerBundles = (bundles: readonly TowerStoredBundle[]): readonly TowerStoredBundle[] =>
  bundles.toSorted(
    (l, r) => r.bundle.height - l.bundle.height || r.bundle.createdAt - l.bundle.createdAt || r.slot - l.slot,
  );
const newestBlind = (bundles: readonly TowerStoredBundle[], tail: boolean): TowerStoredBundle | undefined =>
  bundles.find((e) => e.towerMode === "blind_backup" && (e.bundle.kind === "journal_tail") === tail);
/** og retainAppointmentBundles: a blind backup pins the newest snapshot and the newest tail before the cut. */
const retainTowerBundles = (
  bundles: readonly TowerStoredBundle[],
  towerMode: TowerModeV1,
  limit: number,
): readonly TowerStoredBundle[] => {
  const pins = towerMode === "blind_backup" ? [newestBlind(bundles, false), newestBlind(bundles, true)] : [];
  const pinned = pins.filter((e): e is TowerStoredBundle => e !== undefined);
  return [...pinned, ...bundles.filter((e) => !pinned.includes(e))].slice(0, limit);
};
/** og store validateAppointmentMode. */
const towerStoreModeCode = (a: TowerAppointmentV1, towerMode: TowerModeV1): string | undefined => {
  switch (towerMode) {
    case "blind_backup":
      return codeIf(Boolean(a.lastResortPayload), "TOWER_BACKUP_LAST_RESORT_PAYLOAD_FORBIDDEN");
    case "delayed_last_resort":
      return a.lastResortPayload
        ? encryptedRemedyCode(a.lastResortPayload as Rec)
        : "TOWER_LAST_RESORT_PAYLOAD_MISSING";
  }
};
/** A retention slot: one bundle per (slot, mode, kind) survives. */
type SlotId = { readonly slot: number; readonly towerMode: TowerModeV1; readonly kind: string };
const inSlot = (e: TowerStoredBundle, id: SlotId): boolean =>
  e.slot === id.slot && e.towerMode === id.towerMode && bundleKind(e.bundle) === id.kind;
const latestSigned = (bundles: readonly TowerStoredBundle[]): TowerStoredBundle | undefined =>
  bundles.reduce<TowerStoredBundle | undefined>((l, e) => (!l || e.ownerSignedAt > l.ownerSignedAt ? e : l), undefined);
/** og: an older owner signature than the slot's newest is stale; the same one over different bytes is a replay. */
const slotConflictCode = (latest: TowerStoredBundle | undefined, candidate: TowerStoredBundle): string | undefined => {
  if (latest === undefined) return undefined;
  const differs =
    latest.encryptedEnvelopeHash !== candidate.encryptedEnvelopeHash ||
    latest.lastResortPayloadDigest !== candidate.lastResortPayloadDigest;
  switch (true) {
    case latest.ownerSignedAt > candidate.ownerSignedAt:
      return "TOWER_APPOINTMENT_STALE";
    case latest.ownerSignedAt === candidate.ownerSignedAt && differs:
      return "TOWER_APPOINTMENT_REPLAY_MISMATCH";
    default:
      return undefined;
  }
};
/** What a receipt attests about the write it answers. */
type StoredFacts = {
  readonly lookupKey: string;
  readonly runtimeId: string;
  readonly towerMode: TowerModeV1;
  readonly slot: number;
  readonly sequence: number;
  readonly retainedSlots: number;
  readonly storedBytes: number;
};
/** og prepareAppointment's receipt, signed by the tower (EIP-191). */
const towerReceipt = (cfg: TowerStoreConfig, a: TowerAppointmentV1, facts: StoredFacts): TowerReceiptV1 => {
  const appointmentSequence = Number(a.lastResortPayload?.appointmentSequence);
  const unsigned: TowerReceiptV1 = {
    type: "tower_receipt",
    version: 1,
    towerId: cfg.towerId,
    lookupKey: facts.lookupKey,
    runtimeId: facts.runtimeId,
    height: jsInt(a.bundle.height),
    bundleHash: a.bundle.bundleHash,
    towerMode: facts.towerMode,
    slot: facts.slot,
    storedAt: cfg.now,
    receivedAt: cfg.now,
    expiresAt: cfg.now + cfg.receiptTtlMs,
    sequence: facts.sequence,
    retainedSlots: facts.retainedSlots,
    storedBytes: facts.storedBytes,
    maxStoredBytes: cfg.maxStoredBytesPerLookupKey,
    quotaOk: true,
    appointmentSequence: Number.isFinite(appointmentSequence) ? jsInt(a.lastResortPayload?.appointmentSequence) : null,
  };
  return { ...unsigned, towerSignature: signPersonalMessage(towerReceiptMessage(unsigned), cfg.towerPrivateKey) };
};
const nextSequence = (doc: TowerLookupDoc): number => Math.max(0, ...doc.receipts.map((r) => r.sequence || 0)) + 1;
/**
 * og appointments.ts prepareAppointment: per (slot, mode, kind) the newest owner signature wins; an older `signedAt` is
 * TOWER_APPOINTMENT_STALE, the same `signedAt` over different envelope or payload bytes is
 * TOWER_APPOINTMENT_REPLAY_MISMATCH. The tower signs the receipt (EIP-191).
 */
const prepareTowerAppointment = (
  cfg: TowerStoreConfig,
  a: TowerAppointmentV1,
  existing: TowerLookupDoc,
): Result<TowerLookupDoc, TowerError> =>
  chain(
    all({ lookupKey: towerLookupKey(a.lookupKey), towerMode: normalizeTowerMode(a.towerMode) }),
    ({ lookupKey, towerMode }) => {
      const slot = slotOf(a.slot);
      const runtimeId = jsText(a.bundle.runtimeId).trim().toLowerCase();
      const id: SlotId = { slot, towerMode, kind: bundleKind(a.bundle) };
      const candidate: TowerStoredBundle = {
        slot,
        towerMode,
        bundle: a.bundle,
        ownerSignedAt: jsInt(a.ownerProof.signedAt),
        encryptedEnvelopeHash: towerEnvelopeHash(a.bundle),
        lastResortPayloadDigest: towerPayloadDigest(a.lastResortPayload),
        ...opt("lastResortPayload", a.lastResortPayload || undefined),
      };
      const admitted = towerChecks(
        () => towerStoreModeCode(a, towerMode),
        () =>
          codeIf(
            Boolean(existing.runtimeId) && existing.runtimeId !== runtimeId,
            `TOWER_LOOKUP_RUNTIME_ID_MISMATCH:${existing.runtimeId}:${runtimeId}`,
          ),
        () => slotConflictCode(latestSigned(existing.bundles.filter((e) => inSlot(e, id))), candidate),
      );
      return chain(admitted, () => {
        const others = existing.bundles.filter((e) => !inSlot(e, id));
        const bundles = retainTowerBundles(
          sortTowerBundles([candidate, ...others]),
          towerMode,
          cfg.maxBundlesPerLookupKey,
        );
        const draft: TowerLookupDoc = {
          lookupKey,
          runtimeId,
          updatedAt: cfg.now,
          receipts: existing.receipts,
          bundles,
        };
        const storedBytes = towerLookupBytes(draft);
        if (storedBytes > cfg.maxStoredBytesPerLookupKey) return quotaExceeded(storedBytes, cfg);
        const facts = {
          lookupKey,
          runtimeId,
          towerMode,
          slot,
          sequence: nextSequence(existing),
          retainedSlots: bundles.length,
          storedBytes,
        };
        const receipts = [towerReceipt(cfg, a, facts), ...existing.receipts].slice(0, cfg.maxBundlesPerLookupKey);
        return ok({ ...draft, receipts });
      });
    },
  );
export type TowerWrite = { readonly doc: TowerLookupDoc; readonly receipt: TowerReceiptV1 };
/** og writeLookup's per-lookup quota on the final signed document (the store-wide quotas are the host's). */
const sealTowerWrite = (cfg: TowerStoreConfig, doc: TowerLookupDoc): Result<TowerWrite, TowerError> => {
  const bytes = towerLookupBytes(doc);
  const receipt = doc.receipts[0];
  if (bytes > cfg.maxStoredBytesPerLookupKey) return quotaExceeded(bytes, cfg);
  return receipt === undefined ? towerErr("TOWER_RECEIPT_MISSING") : ok({ doc, receipt });
};
/** og store upsertAppointment over the stored lookup document (`existing` undefined when the key is new). */
export const upsertTowerAppointment = (
  cfg: TowerStoreConfig,
  a: TowerAppointmentV1,
  existing?: TowerLookupDoc,
): Result<TowerWrite, TowerError> =>
  chain(towerLookupKey(a.lookupKey), (key) =>
    chain(prepareTowerAppointment(cfg, a, existing ?? emptyTowerLookupDoc(key)), (doc) => sealTowerWrite(cfg, doc)));
type ArchivePair = readonly [TowerAppointmentV1, TowerAppointmentV1];
/** og: one blind-backup snapshot and the tail that continues it, under one key, runtime, slot and owner signature. */
const isArchivePair = ([snapshot, tail]: ArchivePair, modes: readonly TowerModeV1[]): boolean =>
  modes.every((m) => m === "blind_backup") &&
  snapshot.bundle.kind === "snapshot" &&
  tail.bundle.kind === "journal_tail" &&
  snapshot.lookupKey === tail.lookupKey &&
  snapshot.bundle.runtimeId === tail.bundle.runtimeId &&
  slotOf(snapshot.slot) === slotOf(tail.slot) &&
  snapshot.ownerProof.signedAt === tail.ownerProof.signedAt &&
  tail.bundle.baseRuntimeHeight === snapshot.bundle.height &&
  tail.bundle.height > snapshot.bundle.height;
const retainsBoth = (doc: TowerLookupDoc, pair: ArchivePair): boolean =>
  pair.every((a) => doc.bundles.some((e) => e.encryptedEnvelopeHash === towerEnvelopeHash(a.bundle)));
/** og upsertRecoveryArchive: one owner-signed snapshot and its tail, written as one document or not at all. */
export const upsertTowerRecoveryArchive = (
  cfg: TowerStoreConfig,
  pair: ArchivePair,
  existing?: TowerLookupDoc,
): Result<TowerWrite, TowerError> =>
  chain(
    traverse(pair, (a) => normalizeTowerMode(a.towerMode)),
    (modes) => {
      if (!isArchivePair(pair, modes)) return towerErr("TOWER_ARCHIVE_PAIR_INVALID");
      return chain(towerLookupKey(pair[0].lookupKey), (key) => {
        const written = foldResult(pair, existing ?? emptyTowerLookupDoc(key), (doc, a) =>
          prepareTowerAppointment(cfg, a, doc),
        );
        return chain(written, (doc) =>
          retainsBoth(doc, pair) ? sealTowerWrite(cfg, doc) : towerErr("TOWER_ARCHIVE_PAIR_NOT_RETAINED"),
        );
      });
    },
  );
/**
 * Client check of og's receipt signature (og signs in prepareAppointment and ships no verifier): the tower address the
 * receipt message recovers to.
 */
export const verifyTowerReceiptSignature = (
  receipt: TowerReceiptV1,
  towerAddress: string,
): Result<TowerReceiptV1, TowerError> => {
  if (receipt.towerSignature === undefined) return towerErr("TOWER_RECEIPT_SIGNATURE_MISSING");
  const { towerSignature, ...unsigned } = receipt;
  const signer = recoverPersonalMessage(towerReceiptMessage(unsigned as TowerReceiptV1), towerSignature);
  return signer === towerAddress.toLowerCase() ? ok(receipt) : towerErr("TOWER_RECEIPT_SIGNATURE_INVALID");
};


// Decoding a stored lookup document: every record exact and bound to its key and runtime.

/** og's tagged-JSON reviver: BigInt/Map/Set/Buffer/Date/TypedArray envelopes back to values. */
const reviveTagged = (_k: string, v: unknown): unknown => {
  if (!plainRecord(v) || typeof v["__xlnType"] !== "string") return v;
  const x = v["value"];
  switch (v["__xlnType"]) {
    case "BigInt":
      return typeof x === "string" ? BigInt(x) : v;
    case "Map":
      return Array.isArray(x) ? new Map(x as [unknown, unknown][]) : v;
    case "Set":
      return Array.isArray(x) ? new Set(x) : v;
    case "Buffer":
      return Array.isArray(x) ? Uint8Array.from(x as number[]) : v;
    case "Date":
      return typeof x === "string" ? new Date(x) : v;
    case "TypedArray":
      return typeof v["kind"] === "string" && typeof x === "string" ? new Uint8Array(0) : v;
    default:
      return v;
  }
};
/** og deserializeTaggedJson; JSON.parse throws on bad input, so this is the one place a throw becomes a value. */
const parseTaggedJson = (raw: string): Result<unknown, TowerError> => {
  try {
    return ok(JSON.parse(raw, reviveTagged));
  } catch {
    return towerErr("TOWER_JSON_INVALID");
  }
};
/** A stored record's own lookup key must be its document's. */
const boundLookupCode = (v: unknown, lookupKey: string, record: string): string | undefined =>
  textCode(v, `TOWER_STORED_${record}_LOOKUP_INVALID`) ??
  codeIf(v !== lookupKey, `TOWER_STORED_${record}_LOOKUP_MISMATCH`);
/** A stored record's own runtime must be its document's, case aside. */
const boundRuntimeCode = (v: unknown, runtimeId: string, record: string): string | undefined =>
  textCode(v, `TOWER_STORED_${record}_RUNTIME_INVALID`) ??
  codeIf(String(v).toLowerCase() !== runtimeId, `TOWER_STORED_${record}_RUNTIME_MISMATCH`);
const RECEIPT_COUNTS = ["height", "receivedAt", "sequence", "retainedSlots"];
const RECEIPT_OPTIONAL_COUNTS = [
  "slot",
  "storedAt",
  "expiresAt",
  "storedBytes",
  "maxStoredBytes",
  "appointmentSequence",
];
const receiptCountCode = (field: string): string => `TOWER_STORED_RECEIPT_${field.toUpperCase()}_INVALID`;
/**
 * og decode.ts decodeReceipt: a stored receipt bound to its lookup key and runtime; `towerSignature` is optional but
 * non-empty when present.
 */
export const decodeTowerReceipt = (
  value: unknown,
  lookupKey: string,
  runtimeId: string,
): Result<TowerReceiptV1, TowerError> => {
  if (!plainRecord(value)) return towerErr(STORED_RECEIPT_SHAPE.invalid);
  const r = value;
  const checked = towerChecks(
    () => fieldsCode(r, STORED_RECEIPT_SHAPE),
    () => codeIf(r["type"] !== "tower_receipt" || r["version"] !== 1, "TOWER_STORED_RECEIPT_VERSION_INVALID"),
    () => boundLookupCode(r["lookupKey"], lookupKey, "RECEIPT"),
    () => boundRuntimeCode(r["runtimeId"], runtimeId, "RECEIPT"),
    () => textCode(r["towerId"], "TOWER_STORED_RECEIPT_TOWER_INVALID"),
    () => textCode(r["bundleHash"], "TOWER_STORED_RECEIPT_HASH_INVALID"),
    ...RECEIPT_COUNTS.map((f) => () => safeIntCode(r[f], receiptCountCode(f))),
    ...RECEIPT_OPTIONAL_COUNTS.map((f) => () => optionalSafeIntCode(r[f], receiptCountCode(f))),
    () => (r["towerMode"] === undefined ? undefined : errorCode(normalizeTowerMode(r["towerMode"]))),
    () => codeIf(r["quotaOk"] !== undefined && typeof r["quotaOk"] !== "boolean", "TOWER_STORED_RECEIPT_QUOTA_INVALID"),
    () =>
      r["towerSignature"] === undefined
        ? undefined
        : textCode(r["towerSignature"], "TOWER_STORED_RECEIPT_SIGNATURE_INVALID"),
  );
  return map(checked, () => value as unknown as TowerReceiptV1);
};
/** og decode.ts decodeBundle. */
export const decodeTowerBundle = (
  value: unknown,
  lookupKey: string,
  runtimeId: string,
): Result<EncryptedRuntimeRecoveryBundleV1, TowerError> => {
  if (!plainRecord(value)) return towerErr(STORED_BUNDLE_SHAPE.invalid);
  const b = value;
  const checked = towerChecks(
    () => fieldsCode(b, STORED_BUNDLE_SHAPE),
    () => codeIf(b["version"] !== 1, "TOWER_STORED_BUNDLE_VERSION_INVALID"),
    () =>
      codeIf(
        b["kind"] !== undefined && b["kind"] !== "snapshot" && b["kind"] !== "journal_tail",
        "TOWER_STORED_BUNDLE_KIND_INVALID",
      ),
    () => boundLookupCode(b["lookupKey"], lookupKey, "BUNDLE"),
    () => boundRuntimeCode(b["runtimeId"], runtimeId, "BUNDLE"),
    () => safeIntCode(b["height"], "TOWER_STORED_BUNDLE_HEIGHT_INVALID"),
    () => safeIntCode(b["createdAt"], "TOWER_STORED_BUNDLE_CREATED_AT_INVALID"),
    () => optionalSafeIntCode(b["baseRuntimeHeight"], "TOWER_STORED_BUNDLE_BASE_HEIGHT_INVALID"),
    () => textCode(b["bundleHash"], "TOWER_STORED_BUNDLE_HASH_INVALID"),
    () => textCode(b["iv"], "TOWER_STORED_BUNDLE_IV_INVALID"),
    () => textCode(b["ciphertext"], "TOWER_STORED_BUNDLE_CIPHERTEXT_INVALID"),
    () =>
      codeIf(b["compression"] !== undefined && b["compression"] !== "gzip", "TOWER_STORED_BUNDLE_COMPRESSION_INVALID"),
  );
  return map(checked, () => value as unknown as EncryptedRuntimeRecoveryBundleV1);
};
const STORED_ENVELOPE_HASH_INVALID = "TOWER_STORED_ENCRYPTED_ENVELOPE_HASH_INVALID";
/**
 * og decode.ts's bundle entry: its retention slot and mode, its bundle, its owner signature time and its two hashes.
 */
const decodeStoredBundle = (
  v: unknown,
  lookupKey: string,
  runtimeId: string,
): Result<TowerStoredBundle, TowerError> => {
  if (!plainRecord(v)) return towerErr(STORED_ENTRY_SHAPE.invalid);
  const e = v;
  const head = towerChecks(
    () => fieldsCode(e, STORED_ENTRY_SHAPE),
    () => safeIntCode(e["slot"], "TOWER_STORED_BUNDLE_SLOT_INVALID"),
  );
  const decoded = chain(head, () =>
    all({
      towerMode: normalizeTowerMode(e["towerMode"]),
      bundle: decodeTowerBundle(e["bundle"], lookupKey, runtimeId),
    }),
  );
  return chain(decoded, ({ towerMode, bundle }) => {
    const checked = towerChecks(
      () => safeIntCode(e["ownerSignedAt"], "TOWER_STORED_OWNER_SIGNED_AT_INVALID"),
      () =>
        textCode(e["encryptedEnvelopeHash"], STORED_ENVELOPE_HASH_INVALID) ??
        codeIf(!WORD32.test(String(e["encryptedEnvelopeHash"]).toLowerCase()), STORED_ENVELOPE_HASH_INVALID),
      () => textCode(e["lastResortPayloadDigest"], "TOWER_STORED_LAST_RESORT_DIGEST_INVALID"),
      () =>
        codeIf(
          e["lastResortPayload"] !== undefined && !plainRecord(e["lastResortPayload"]),
          "TOWER_STORED_LAST_RESORT_PAYLOAD_INVALID",
        ),
    );
    return map(checked, () => ({
      slot: e["slot"] as number,
      towerMode,
      bundle,
      ownerSignedAt: e["ownerSignedAt"] as number,
      encryptedEnvelopeHash: String(e["encryptedEnvelopeHash"]).toLowerCase(),
      lastResortPayloadDigest: e["lastResortPayloadDigest"] as string,
      ...opt("lastResortPayload", e["lastResortPayload"] as TowerLastResortPayloadV1 | undefined),
    }));
  });
};
/**
 * og decode.ts decodeStoredLookupDoc: a persisted lookup document, every receipt and bundle bound to its key and
 * runtime.
 */
export const decodeTowerLookupDoc = (raw: string, expectedLookupKey?: string): Result<TowerLookupDoc, TowerError> =>
  chain(parseTaggedJson(raw), (value) => {
    if (!plainRecord(value)) return towerErr(STORED_LOOKUP_SHAPE.invalid);
    const d = value;
    const lookupKey = lowerText(d["lookupKey"]);
    const runtimeId = lowerText(d["runtimeId"]);
    const checked = towerChecks(
      () => fieldsCode(d, STORED_LOOKUP_SHAPE),
      () => textCode(d["lookupKey"], "TOWER_STORED_LOOKUP_KEY_INVALID"),
      () => codeIf(!WORD32.test(lookupKey), "TOWER_STORED_LOOKUP_KEY_INVALID"),
      () => codeIf(Boolean(expectedLookupKey) && lookupKey !== expectedLookupKey, "TOWER_STORED_LOOKUP_KEY_MISMATCH"),
      () => textCode(d["runtimeId"], "TOWER_STORED_RUNTIME_INVALID"),
      () => codeIf(!EOA.test(runtimeId), "TOWER_STORED_RUNTIME_INVALID"),
      () => safeIntCode(d["updatedAt"], "TOWER_STORED_UPDATED_AT_INVALID"),
      () => codeIf(!Array.isArray(d["receipts"]), "TOWER_STORED_RECEIPTS_INVALID"),
      () => codeIf(!Array.isArray(d["bundles"]), "TOWER_STORED_BUNDLES_INVALID"),
    );
    const decoded = chain(checked, () =>
      all({
        receipts: traverse(d["receipts"] as readonly unknown[], (r) => decodeTowerReceipt(r, lookupKey, runtimeId)),
        bundles: traverse(d["bundles"] as readonly unknown[], (b) => decodeStoredBundle(b, lookupKey, runtimeId)),
      }),
    );
    return map(decoded, ({ receipts, bundles }) => ({
      lookupKey,
      runtimeId,
      updatedAt: d["updatedAt"] as number,
      receipts,
      bundles,
    }));
  });

// ---- the order book ----
// og orderbook/core.ts (price-page limit order book), orderbook/pages/{page,key}.ts, orderbook/commitment.ts
// og keeps liquidity in two Patricia trees of 16-slot FIFO price pages; the rewrite keeps each side as its pages in
// key-byte order (price, then page sequence) and seals the same radix-16 root. og throws on a broken invariant; here
// every such case is a `book` refusal.
export type BookSide = 0 | 1;
export type BookEntry = {
  readonly orderId: string;
  readonly ownerId: string;
  readonly qtyLots: bigint;
  readonly seq: number;
};
export type BookPage = {
  readonly headSlot: number;
  readonly nextSlot: number;
  readonly liveCount: number;
  readonly totalQtyLots: bigint;
  readonly slots: readonly (BookEntry | null)[];
};
export type BookPageKey = { readonly priceTicks: bigint; readonly pageSequence: number };
export type BookPageRow = { readonly key: BookPageKey; readonly page: BookPage };
/** og BookOrderState: the RAM locator of a resting order (never committed). */
export type BookOrder = BookEntry & {
  readonly side: BookSide;
  readonly priceTicks: bigint;
  readonly pageSequence: number;
  readonly pageSlot: number;
};
export type BookParams = { readonly bucketWidthTicks: bigint; readonly maxOrders: number; readonly stpPolicy: 0 | 1 };
export type Book = {
  readonly params: BookParams;
  readonly orders: ReadonlyMap<string, BookOrder>;
  readonly bidPages: readonly BookPageRow[];
  readonly askPages: readonly BookPageRow[];
  readonly nextSeq: number;
  readonly tradeCount: number;
  readonly tradeQtySum: bigint;
  readonly lastTradePriceTicks: bigint;
  readonly lastAcceptedUsdAskPriceTicks: bigint;
  readonly eventHash: bigint;
};
export type BookTif = 0 | 1 | 2;
export type OrderCmd =
  | {
      readonly kind: 0;
      readonly ownerId: string;
      readonly orderId: string;
      readonly side: BookSide;
      readonly tif: BookTif;
      readonly postOnly: boolean;
      readonly priceTicks: bigint;
      readonly qtyLots: bigint;
    }
  | { readonly kind: 1; readonly ownerId: string; readonly orderId: string }
  | {
      readonly kind: 2;
      readonly ownerId: string;
      readonly orderId: string;
      readonly newPriceTicks: bigint | null;
      readonly qtyDeltaLots: bigint;
    };
type PlaceCmd = Extract<OrderCmd, { readonly kind: 0 }>;
export type BookEvent =
  | { readonly type: "ACK"; readonly orderId: string; readonly ownerId: string }
  | {
      readonly type: "REJECT";
      readonly orderId: string;
      readonly ownerId: string;
      readonly reason: string;
      readonly blockingOrderId?: string | undefined;
    }
  | {
      readonly type: "TRADE";
      readonly price: bigint;
      readonly qty: bigint;
      readonly makerOwnerId: string;
      readonly takerOwnerId: string;
      readonly makerOrderId: string;
      readonly takerOrderId: string;
      readonly makerQtyBefore: bigint;
      readonly takerQtyTotal: bigint;
    }
  | {
      readonly type: "REDUCED";
      readonly orderId: string;
      readonly ownerId: string;
      readonly delta: bigint;
      readonly remain: bigint;
    }
  | { readonly type: "CANCELED"; readonly orderId: string; readonly ownerId: string };
export type MakerDisposition = "eligible" | "suspended" | "cancel";
/** A maker judgment, and anything the caller learned making it (og's memo write inside the classifier). */
export type MakerVerdict<L = never> = { readonly disposition: MakerDisposition; readonly learned?: L | undefined };
/**
 * `F`: the caller's fault a maker judgment can raise; the first one ends the command with it. `L`: what the caller
 * learns while judging.
 */
export type BookOptions<F = never, L = never> = {
  readonly suspendedOrderIds?: ReadonlySet<string> | undefined;
  /** og's classifier, consulted lazily, once per maker per command (og cacheMakerDisposition). */
  readonly makerDisposition?: ((maker: BookOrder) => MakerDisposition) | undefined;
  /** The same, for a caller whose judgment can refuse or learn; it takes the place of `makerDisposition`. */
  readonly makerVerdict?: ((maker: BookOrder) => Result<MakerVerdict<L>, F>) | undefined;
  readonly executionPriceTicksForMatch?: ((maker: bigint, taker: bigint, side: BookSide) => bigint) | undefined;
  readonly executionQtyMultipleAtPrice?: ((priceTicks: bigint) => bigint) | undefined;
};
export type BookError = Tagged<"book", { code: string }>;
export type BookStep = { readonly state: Book; readonly events: readonly BookEvent[] };
/** A command's answer with what the caller learned judging makers, in judgment order. */
export type Judged<T, L> = { readonly value: T; readonly learned: readonly L[] };
export const BOOK_PAGE_CAPACITY = 16;
export const MAX_ORDERBOOK_QTY_LOTS = 10n ** 24n;
const bookErr = (code: string): Result<never, BookError> => err({ _tag: "book", code });


// Commitment: both sides' pages sealed as og's Patricia roots, with the params and counters.

const unsignedBytes = (v: bigint): Uint8Array => {
  const h = v.toString(16);
  return hexToBytes(h.length % 2 === 0 ? h : `0${h}`);
};
/** og encodeBookPricePrefix / encodeBookPricePageKey: length-prefixed minimal price, then the uint16 page. */
const bookPriceKeyBytes = (k: BookPageKey): Uint8Array => {
  const price = unsignedBytes(k.priceTicks);
  return concat([Uint8Array.of(price.length), price, u16(k.pageSequence)]);
};
const u16Framed = (b: Uint8Array): Uint8Array => concat([u16(b.length), b]);
const bookEntryBytes = (e: BookEntry | null): Uint8Array =>
  e === null
    ? Uint8Array.of(0)
    : concat([
        Uint8Array.of(1),
        u16Framed(utf8(e.orderId)),
        u16Framed(utf8(e.ownerId)),
        u16Framed(unsignedBytes(e.qtyLots)),
        u16Framed(unsignedBytes(BigInt(e.seq))),
      ]);
/** og pageHash: the integrity digest of the page's slot layout. */
const bookPageDigest = (p: BookPage): Uint8Array =>
  sha256(concat([
    u16(p.headSlot),
    u16(p.nextSlot),
    u16(p.liveCount),
    u16Framed(unsignedBytes(p.totalQtyLots)),
    ...p.slots.map(bookEntryBytes),
  ]));
const pageLeaf = (r: BookPageRow) => {
  const key = bookPriceKeyBytes(r.key);
  return { nibbles: nibblesOf(key), key, digest: bookPageDigest(r.page) };
};
/**
 * og BookPricePageTree.rootHash(): radix-16 Patricia over key bytes, leaf value = page digest; empty is the zero word.
 */
export const bookPagesRoot = (rows: readonly BookPageRow[]): string => sealRadix(rows.map(pageLeaf));
/**
 * og computeBookCommitmentHash: integrity checksum of the length-framed params, both page roots and the trade/event
 * counters.
 */
export const bookCommitmentHash = (b: Book): string => {
  const parts = [
    "xln.orderbook.book",
    String(b.params.bucketWidthTicks),
    String(b.params.maxOrders),
    String(b.params.stpPolicy),
    bookPagesRoot(b.bidPages),
    bookPagesRoot(b.askPages),
    String(b.nextSeq),
    String(b.tradeCount),
    String(b.tradeQtySum),
    String(b.lastTradePriceTicks),
    String(b.lastAcceptedUsdAskPriceTicks),
    String(b.eventHash),
  ].map(utf8);
  return bytesToHex(sha256(concat(parts.flatMap((p) => [u32(p.length), p]))).slice(0, 16));
};
/** og createBook. */
export const createBook = (params: BookParams): Result<Book, BookError> => {
  if (params.bucketWidthTicks <= 0n) return bookErr("bucketWidthTicks must be positive");
  if (!Number.isFinite(params.maxOrders) || params.maxOrders <= 0) return bookErr("maxOrders must be positive");
  if (params.stpPolicy !== 0 && params.stpPolicy !== 1) return bookErr("unsupported stpPolicy");
  return ok({
    params: { ...params, maxOrders: Math.max(1, Math.floor(params.maxOrders)) },
    orders: new Map(),
    bidPages: [],
    askPages: [],
    nextSeq: 1,
    tradeCount: 0,
    tradeQtySum: 0n,
    lastTradePriceTicks: 0n,
    lastAcceptedUsdAskPriceTicks: 0n,
    eventHash: 0n,
  });
};
const EVENT_HASH_PRIME = 0x1_0000_01n;
const EVENT_HASH_MASK = 0x1f_ffff_ffff_ffffn;
/** og bumpHash tags: what moved the book. */
const BOOK_EVENT_TAG = { rest: 1, trade: 3, usdAsk: 4, cancel: 5 } as const;
/** og bumpHash: the rolling event hash (JS int32 mixing kept bit-exact). */
const bumped = (book: Book, tag: number, a: number | bigint, b: number | bigint): Book => {
  const a32 = Number(BigInt(a) & 0xffff_ffffn);
  const b32 = Number(BigInt(b) & 0xffff_ffffn);
  const mixed = ((tag * 2_654_435_761) >>> 0) ^ a32 ^ (b32 << 7);
  return { ...book, eventHash: (book.eventHash * EVENT_HASH_PRIME + BigInt(mixed)) & EVENT_HASH_MASK };
};


// Pages: each side is its page rows in key order; a page is 16 FIFO slots between its head and its next free slot.

const sideRows = (book: Book, side: BookSide): readonly BookPageRow[] => (side === 0 ? book.bidPages : book.askPages);
const keyOrder = (a: BookPageKey, b: BookPageKey): number =>
  a.priceTicks !== b.priceTicks ? asc(a.priceTicks, b.priceTicks) : a.pageSequence - b.pageSequence;
const pageKeyOf = (o: BookOrder): BookPageKey => ({ priceTicks: o.priceTicks, pageSequence: o.pageSequence });
/** og tree.updated / tree.removed (`page` undefined): one row, key order kept. */
const withPage = (
  rows: readonly BookPageRow[],
  key: BookPageKey,
  page: BookPage | undefined,
): readonly BookPageRow[] => {
  const found = rows.findIndex((r) => keyOrder(r.key, key) >= 0);
  const at = found < 0 ? rows.length : found;
  const hit = at < rows.length && keyOrder((rows[at] as BookPageRow).key, key) === 0;
  return [...rows.slice(0, at), ...(page === undefined ? [] : [{ key, page }]), ...rows.slice(hit ? at + 1 : at)];
};
const withSidePage = (book: Book, side: BookSide, key: BookPageKey, page: BookPage | undefined): Book =>
  side === 0
    ? { ...book, bidPages: withPage(book.bidPages, key, page) }
    : { ...book, askPages: withPage(book.askPages, key, page) };
const getPage = (book: Book, side: BookSide, key: BookPageKey): BookPage | undefined =>
  sideRows(book, side).find((r) => keyOrder(r.key, key) === 0)?.page;
/** A side's pages grouped by price, in key order. */
const priceLevels = (rows: readonly BookPageRow[]): readonly (readonly BookPageRow[])[] =>
  [...Map.groupBy(rows, (r) => r.key.priceTicks).values()];
/** og orderedPages: asks ascending; bids by descending price, FIFO page sequence within a price. */
const orderedPages = (rows: readonly BookPageRow[], side: BookSide): readonly BookPageRow[] =>
  side === 1 ? rows : priceLevels(rows).toReversed().flat();
const slotRange = (page: BookPage): readonly number[] =>
  Array.from({ length: Math.max(0, page.nextSlot - page.headSlot) }, (_, i) => page.headSlot + i);
/** The first live slot at or after `from`: a page's head once the slots before it emptied. */
const nextLive = (slots: readonly (BookEntry | null)[], from: number): number => {
  const live = slots.findIndex((e, i) => i >= from && e !== null);
  return live < 0 ? slots.length : live;
};
const pageOrder = (side: BookSide, row: BookPageRow, slot: number): BookOrder | null => {
  const e = row.page.slots[slot];
  return e ? { ...e, side, priceTicks: row.key.priceTicks, pageSequence: row.key.pageSequence, pageSlot: slot } : null;
};
const pageOrders = (side: BookSide, row: BookPageRow): readonly BookOrder[] =>
  slotRange(row.page).flatMap((slot) => pageOrder(side, row, slot) ?? []);
/** A side's resting orders in price-time priority. */
const makersOf = (book: Book, side: BookSide): readonly BookOrder[] =>
  orderedPages(sideRows(book, side), side).flatMap((row) => pageOrders(side, row));
const bookCrosses = (side: BookSide, taker: bigint, maker: bigint): boolean =>
  side === 0 ? maker <= taker : maker >= taker;
/** og requireEntry. */
const bookEntryCode = (e: BookEntry): string | undefined => {
  const ob = utf8(e.orderId).length;
  const wb = utf8(e.ownerId).length;
  switch (true) {
    case ob === 0 || ob > 323:
      return `BOOK_PAGE_ORDER_ID_BYTES_INVALID:${ob}`;
    case wb === 0 || wb > 66:
      return `BOOK_PAGE_OWNER_ID_BYTES_INVALID:${wb}`;
    case e.qtyLots <= 0n || e.qtyLots > MAX_ORDERBOOK_QTY_LOTS:
      return "BOOK_PAGE_ORDER_QTY_INVALID";
    case !Number.isSafeInteger(e.seq) || e.seq < 0:
      return "BOOK_PAGE_ORDER_SEQ_INVALID";
    default:
      return undefined;
  }
};
const EMPTY_BOOK_PAGE: BookPage = {
  headSlot: 0,
  nextSlot: 0,
  liveCount: 0,
  totalQtyLots: 0n,
  slots: Array.from({ length: BOOK_PAGE_CAPACITY }, () => null),
};
/**
 * og addOrder + appendBookPricePageOrder: FIFO append to the price's tail page, opening the next page sequence when it
 * is full.
 */
const addBookOrder = (book: Book, o: Omit<BookOrder, "pageSequence" | "pageSlot">): Result<Book, BookError> => {
  const entry: BookEntry = { orderId: o.orderId, ownerId: o.ownerId, qtyLots: o.qtyLots, seq: o.seq };
  const bad = bookEntryCode(entry);
  if (bad !== undefined) return bookErr(bad);
  if (o.priceTicks <= 0n) return bookErr(`BOOK_PAGE_PRICE_INVALID:${o.priceTicks}`);
  const tail = sideRows(book, o.side).findLast((r) => r.key.priceTicks === o.priceTicks);
  const tailSequence = tail?.key.pageSequence ?? 0;
  const sequence = tail?.page.nextSlot === BOOK_PAGE_CAPACITY ? tailSequence + 1 : tailSequence;
  if (sequence > 0xffff) return bookErr("BOOK_PAGE_SEQUENCE_EXHAUSTED");
  const page = tail?.key.pageSequence === sequence ? tail.page : EMPTY_BOOK_PAGE;
  const slot = page.nextSlot;
  const appended: BookPage = {
    headSlot: page.liveCount === 0 ? slot : page.headSlot,
    nextSlot: slot + 1,
    liveCount: page.liveCount + 1,
    totalQtyLots: page.totalQtyLots + entry.qtyLots,
    slots: page.slots.with(slot, entry),
  };
  const placed = withSidePage(book, o.side, { priceTicks: o.priceTicks, pageSequence: sequence }, appended);
  return ok({ ...placed, orders: mapSet(book.orders, o.orderId, { ...o, pageSequence: sequence, pageSlot: slot }) });
};
/** og removeOrder + removeBookPricePageOrder; nothing when the order's slot is not where its locator says. */
const removeBookOrder = (book: Book, orderId: string): Book | undefined => {
  const o = book.orders.get(orderId);
  if (!o) return undefined;
  const key = pageKeyOf(o);
  const page = getPage(book, o.side, key);
  const entry = page?.slots[o.pageSlot];
  if (!page || !entry) return undefined;
  const slots = page.slots.with(o.pageSlot, null);
  const liveCount = page.liveCount - 1;
  const headSlot = o.pageSlot === page.headSlot ? nextLive(slots, o.pageSlot + 1) : page.headSlot;
  const left = liveCount === 0
    ? undefined
    : { ...page, headSlot, liveCount, totalQtyLots: page.totalQtyLots - entry.qtyLots, slots };
  return { ...withSidePage(book, o.side, key, left), orders: mapDelete(book.orders, orderId) };
};
/** og reduceOrder + reduceBookPricePageOrder. */
const reduceBookOrder = (book: Book, o: BookOrder, qtyLots: bigint): Result<Book, BookError> => {
  if (qtyLots <= 0n || qtyLots > MAX_ORDERBOOK_QTY_LOTS) return bookErr("BOOK_PAGE_ORDER_QTY_INVALID");
  const key = pageKeyOf(o);
  const page = getPage(book, o.side, key);
  const entry = page?.slots[o.pageSlot];
  if (!page || !entry || entry.orderId !== o.orderId) return bookErr("BOOK_PAGE_LOCATION_MISMATCH");
  if (qtyLots >= entry.qtyLots) return bookErr("BOOK_PAGE_REDUCTION_INVALID");
  const indexed = book.orders.get(o.orderId);
  if (!indexed) return bookErr(`BOOK_ORDER_INDEX_MISSING:${o.orderId}`);
  const reduced: BookPage = {
    ...page,
    totalQtyLots: page.totalQtyLots - entry.qtyLots + qtyLots,
    slots: page.slots.with(o.pageSlot, { ...entry, qtyLots }),
  };
  return ok({
    ...withSidePage(book, o.side, key, reduced),
    orders: mapSet(book.orders, o.orderId, { ...indexed, qtyLots }),
  });
};


// Judging makers: og consults the caller once per maker per command and remembers the verdict. Whatever the caller
// learned while judging (og writes it into its own memo from inside the classifier) comes back with the answer.

/** The verdicts given so far in this command, and what the caller learned giving them, in judgment order. */
type Judge<L> = { readonly verdicts: ReadonlyMap<string, MakerDisposition>; readonly learned: readonly L[] };
const NO_JUDGE: Judge<never> = { verdicts: new Map(), learned: [] };
type Judgment<L> = { readonly disposition: MakerDisposition; readonly judge: Judge<L> };
const judgeMaker = <F, L>(opts: BookOptions<F, L>, judge: Judge<L>, maker: BookOrder): Result<Judgment<L>, F> => {
  const held = judge.verdicts.get(maker.orderId);
  const classify = opts.makerDisposition;
  const verdict = opts.makerVerdict ?? (classify && ((m: BookOrder) => ok({ disposition: classify(m) })));
  if (opts.suspendedOrderIds?.has(maker.orderId)) return ok({ disposition: "suspended", judge });
  if (held !== undefined) return ok({ disposition: held, judge });
  if (verdict === undefined) return ok({ disposition: "eligible", judge });
  return map(verdict(maker), ({ disposition, learned }: MakerVerdict<L>) => ({
    disposition,
    judge: {
      verdicts: mapSet(judge.verdicts, maker.orderId, disposition),
      learned: learned === undefined ? judge.learned : [...judge.learned, learned],
    },
  }));
};
type Best<L> = { readonly best: BookOrder | null; readonly judge: Judge<L> };
/** og findBestOrder: the first eligible maker of `side` in price-time order. */
const findBestOrder = <F, L>(
  book: Book,
  side: BookSide,
  opts: BookOptions<F, L>,
  judge: Judge<L>,
): Result<Best<L>, F> => {
  const start: Best<L> = { best: null, judge };
  return foldResult(makersOf(book, side), start, (found, maker) =>
    found.best !== null
      ? ok(found)
      : map(judgeMaker(opts, found.judge, maker), (j) => ({
          best: j.disposition === "eligible" ? maker : null,
          judge: j.judge,
        })));
};


// Matching: the taker walks the opposite side in price-time order over the pre-match pages, publishing each touched
// page once.

type BookTaker = {
  readonly side: BookSide;
  readonly ownerId: string;
  readonly orderId: string;
  readonly priceTicks: bigint;
  readonly qtyLots: bigint;
};
/** The walk so far: the book as it moves, what is left to fill, the events, and whether the walk has ended. */
type MatchRun<L> = {
  readonly book: Book;
  readonly judge: Judge<L>;
  readonly remaining: bigint;
  readonly events: readonly BookEvent[];
  readonly halted: boolean;
  readonly blockingOrderId?: string | undefined;
};
/** The walk inside one maker page: the page's slots, live count and total as the taker leaves them. */
type PageWalk<L> = MatchRun<L> & {
  readonly slots: readonly (BookEntry | null)[];
  readonly live: number;
  readonly total: bigint;
  readonly changed: boolean;
};
type WalkScope<F, L> = {
  readonly taker: BookTaker;
  readonly makerSide: BookSide;
  readonly row: BookPageRow;
  readonly opts: BookOptions<F, L>;
};
const withoutOrder = (book: Book, orderId: string): Book => ({ ...book, orders: mapDelete(book.orders, orderId) });
/** og's cancel disposition: the maker leaves the book without trading. */
const cancelMaker = <L,>(walk: PageWalk<L>, maker: BookOrder): PageWalk<L> => ({
  ...walk,
  book: bumped(withoutOrder(walk.book, maker.orderId), BOOK_EVENT_TAG.cancel, maker.priceTicks, 0),
  slots: walk.slots.with(maker.pageSlot, null),
  live: walk.live - 1,
  total: walk.total - maker.qtyLots,
  changed: true,
});
/** og self-trade prevention: the taker is refused at its own resting order, and the walk ends there. */
const selfTradeHalt = <L,>(walk: PageWalk<L>, taker: BookTaker, maker: BookOrder): PageWalk<L> => {
  const reject: BookEvent = {
    type: "REJECT",
    orderId: taker.orderId,
    ownerId: taker.ownerId,
    reason: "STP cancel taker",
    blockingOrderId: maker.orderId,
  };
  return { ...walk, events: [...walk.events, reject], halted: true, blockingOrderId: maker.orderId };
};
/** One fill: counters, rolling hash and TRADE; a filled maker leaves, a partly filled one shrinks and ends the walk. */
const tradeWith = <L,>(
  walk: PageWalk<L>,
  { taker, row }: WalkScope<unknown, L>,
  maker: BookOrder,
  price: bigint,
  qty: bigint,
): Result<PageWalk<L>, BookError> => {
  const counted: Book = {
    ...walk.book,
    tradeCount: walk.book.tradeCount + 1,
    tradeQtySum: walk.book.tradeQtySum + qty,
    lastTradePriceTicks: price,
  };
  const trade: BookEvent = {
    type: "TRADE",
    price,
    qty,
    makerOwnerId: maker.ownerId,
    takerOwnerId: taker.ownerId,
    makerOrderId: maker.orderId,
    takerOrderId: taker.orderId,
    makerQtyBefore: maker.qtyLots,
    takerQtyTotal: taker.qtyLots,
  };
  const book = bumped(counted, BOOK_EVENT_TAG.trade, price, qty);
  const traded = {
    ...walk,
    book,
    remaining: walk.remaining - qty,
    total: walk.total - qty,
    changed: true,
    events: [...walk.events, trade],
  };
  if (qty === maker.qtyLots) {
    return ok({
      ...traded,
      book: withoutOrder(book, maker.orderId),
      slots: walk.slots.with(maker.pageSlot, null),
      live: walk.live - 1,
    });
  }
  const remain = maker.qtyLots - qty;
  const entry = row.page.slots[maker.pageSlot] as BookEntry;
  const indexed = book.orders.get(maker.orderId);
  if (!indexed) return bookErr(`BOOK_ORDER_INDEX_MISSING:${maker.orderId}`);
  const reduced: BookEvent = { type: "REDUCED", orderId: maker.orderId, ownerId: maker.ownerId, delta: -qty, remain };
  return ok({
    ...traded,
    book: { ...book, orders: mapSet(book.orders, maker.orderId, { ...indexed, qtyLots: remain }) },
    slots: walk.slots.with(maker.pageSlot, { ...entry, qtyLots: remain }),
    events: [...traded.events, reduced],
    halted: true,
  });
};
/**
 * The fill a maker offers at the execution price, rounded down to the execution multiple; nothing fillable ends the
 * walk.
 */
const fillMaker = <F, L>(
  walk: PageWalk<L>,
  scope: WalkScope<F, L>,
  maker: BookOrder,
): Result<PageWalk<L>, BookError> => {
  const { taker, opts } = scope;
  const price = opts.executionPriceTicksForMatch?.(maker.priceTicks, taker.priceTicks, taker.side) ?? maker.priceTicks;
  if (price <= 0n) return bookErr("BOOK_EXECUTION_PRICE_INVALID");
  const multiple = opts.executionQtyMultipleAtPrice?.(price) ?? 1n;
  if (multiple <= 0n) return bookErr("BOOK_EXECUTION_QTY_MULTIPLE_INVALID");
  const fillable = maker.qtyLots < walk.remaining ? maker.qtyLots : walk.remaining;
  const qty = (fillable / multiple) * multiple;
  return qty <= 0n ? ok({ ...walk, halted: true }) : tradeWith(walk, scope, maker, price, qty);
};
const walkSlot = <F, L>(
  walk: PageWalk<L>,
  scope: WalkScope<F, L>,
  slot: number,
): Result<PageWalk<L>, BookError | F> => {
  const maker = walk.halted || walk.remaining <= 0n ? null : pageOrder(scope.makerSide, scope.row, slot);
  if (maker === null) return ok(walk);
  return chain(judgeMaker(scope.opts, walk.judge, maker), ({ disposition, judge }) => {
    const judged: PageWalk<L> = { ...walk, judge };
    const selfTrade = maker.ownerId === scope.taker.ownerId && judged.book.params.stpPolicy === 1;
    switch (true) {
      case disposition === "suspended":
        return ok(judged);
      case disposition === "cancel":
        return ok(cancelMaker(judged, maker));
      case selfTrade:
        return ok(selfTradeHalt(judged, scope.taker, maker));
      default:
        return fillMaker(judged, scope, maker);
    }
  });
};
/** A walked page goes back into the book once, only if the walk touched it; an emptied page leaves. */
const publishPage = <L,>(walk: PageWalk<L>, side: BookSide, row: BookPageRow): MatchRun<L> => {
  const { slots, live, total, changed, ...run } = walk;
  if (!changed) return run;
  const page = live === 0
    ? undefined
    : { ...row.page, headSlot: nextLive(slots, row.page.headSlot), liveCount: live, totalQtyLots: total, slots };
  return { ...run, book: withSidePage(run.book, side, row.key, page) };
};
const walkPage = <F, L>(
  run: MatchRun<L>,
  taker: BookTaker,
  row: BookPageRow,
  opts: BookOptions<F, L>,
): Result<MatchRun<L>, BookError | F> => {
  if (run.halted || run.remaining <= 0n || !bookCrosses(taker.side, taker.priceTicks, row.key.priceTicks)) {
    return ok({ ...run, halted: true });
  }
  const makerSide: BookSide = taker.side === 0 ? 1 : 0;
  const scope: WalkScope<F, L> = { taker, makerSide, row, opts };
  const start: PageWalk<L> = {
    ...run,
    slots: row.page.slots,
    live: row.page.liveCount,
    total: row.page.totalQtyLots,
    changed: false,
  };
  const walked = foldResult(slotRange(row.page), start, (walk, slot) => walkSlot(walk, scope, slot));
  return map(walked, (walk) => publishPage(walk, makerSide, row));
};
/**
 * og matchPricePages: walk the opposite side in price-time order over the pre-match snapshot, publishing each touched
 * page once.
 */
const matchBook = <F, L>(
  book: Book,
  judge: Judge<L>,
  taker: BookTaker,
  opts: BookOptions<F, L>,
): Result<MatchRun<L>, BookError | F> => {
  const makerSide: BookSide = taker.side === 0 ? 1 : 0;
  const start: MatchRun<L> = { book, judge, remaining: taker.qtyLots, events: [], halted: false };
  return foldResult(orderedPages(sideRows(book, makerSide), makerSide), start, (run, row) =>
    walkPage(run, taker, row, opts),
  );
};


// Commands.

const rejected = (
  book: Book,
  cmd: { readonly orderId: string; readonly ownerId: string },
  reason: string,
): BookStep => ({
  state: book,
  events: [{ type: "REJECT", orderId: cmd.orderId, ownerId: cmd.ownerId, reason }],
});
const unjudged = <T,>(value: T): Judged<T, never> => ({ value, learned: [] });
const cancelCommand = (book: Book, cmd: Extract<OrderCmd, { readonly kind: 1 }>): Result<BookStep, BookError> => {
  const existing = book.orders.get(cmd.orderId);
  if (!existing) return ok(rejected(book, cmd, "not found"));
  if (existing.ownerId !== cmd.ownerId) return ok(rejected(book, cmd, "not owner"));
  const removed = removeBookOrder(book, cmd.orderId);
  if (removed === undefined) return bookErr("BOOK_PAGE_LOCATION_MISMATCH");
  return ok({
    state: bumped(removed, BOOK_EVENT_TAG.cancel, existing.priceTicks, 0),
    events: [{ type: "CANCELED", orderId: cmd.orderId, ownerId: cmd.ownerId }],
  });
};
const placementRefusal = (book: Book, cmd: PlaceCmd): string | undefined => {
  switch (true) {
    case cmd.qtyLots <= 0n || cmd.qtyLots > MAX_ORDERBOOK_QTY_LOTS:
      return "qty out of range";
    case cmd.priceTicks <= 0n:
      return "price must be positive";
    case book.orders.has(cmd.orderId):
      return "duplicate orderId";
    default:
      return undefined;
  }
};
/** A GTC remainder rests at the book's next sequence, rounded down to the execution multiple. */
const restRemainder = <F, L>(
  run: MatchRun<L>,
  cmd: PlaceCmd,
  options: BookOptions<F, L>,
): Result<BookStep, BookError> => {
  const { orderId, ownerId, side, priceTicks } = cmd;
  const settled: BookStep = { state: run.book, events: run.events };
  if (run.book.orders.size >= run.book.params.maxOrders) return bookErr("Out of order slots");
  const multiple = options.executionQtyMultipleAtPrice?.(priceTicks) ?? 1n;
  if (multiple <= 0n) return bookErr("BOOK_EXECUTION_QTY_MULTIPLE_INVALID");
  const resting = (run.remaining / multiple) * multiple;
  if (resting <= 0n) return ok(settled);
  const seq = run.book.nextSeq;
  return map(addBookOrder(run.book, { orderId, ownerId, side, priceTicks, qtyLots: resting, seq }), (added) => ({
    state: bumped({ ...added, nextSeq: seq + 1 }, BOOK_EVENT_TAG.rest, priceTicks, resting),
    events: [...run.events, { type: "ACK", orderId, ownerId }],
  }));
};
/** After the walk: FOK is all or nothing, a GTC remainder rests, and a taker that met nothing is refused. */
const settlePlacement = <F, L>(
  book: Book,
  cmd: PlaceCmd,
  run: MatchRun<L>,
  options: BookOptions<F, L>,
): Result<BookStep, BookError> => {
  const unfilled = run.remaining > 0n;
  switch (true) {
    case cmd.tif === 2 && unfilled:
      return ok(rejected(book, cmd, "FOK cannot fill entirely"));
    case unfilled && run.blockingOrderId === undefined && cmd.tif === 0:
      return restRemainder(run, cmd, options);
    case run.remaining === cmd.qtyLots && run.events.length === 0:
      return ok(rejected(run.book, cmd, "no fill"));
    default:
      return ok({ state: run.book, events: run.events });
  }
};
const placeCommand = <F, L>(
  book: Book,
  cmd: PlaceCmd,
  options: BookOptions<F, L>,
): Result<Judged<BookStep, L>, BookError | F> => {
  const refusal = placementRefusal(book, cmd);
  if (refusal !== undefined) return ok(unjudged(rejected(book, cmd, refusal)));
  const { ownerId, orderId, side, postOnly, priceTicks, qtyLots } = cmd;
  const blocker: Result<Best<L>, F> = postOnly
    ? findBestOrder(book, side === 0 ? 1 : 0, options, NO_JUDGE)
    : ok({ best: null, judge: NO_JUDGE });
  return chain(blocker, ({ best, judge }) => {
    if (best !== null && bookCrosses(side, priceTicks, best.priceTicks)) {
      return ok({ value: rejected(book, cmd, "postOnly would cross"), learned: judge.learned });
    }
    const taker: BookTaker = { side, ownerId, orderId, priceTicks, qtyLots };
    return chain(matchBook(book, judge, taker, options), (run) =>
      map(settlePlacement(book, cmd, run, options), (step) => ({ value: step, learned: run.judge.learned })),
    );
  });
};
/**
 * og applyCommand: place (GTC/IOC/FOK, post-only, STP) or cancel; replace is refused. A refusal event leaves the book
 * unchanged. The answer carries what the caller learned judging makers.
 */
export const judgedBookCommand = <F = never, L = never>(
  book: Book,
  cmd: OrderCmd,
  options: BookOptions<F, L> = {},
): Result<Judged<BookStep, L>, BookError | F> => {
  switch (cmd.kind) {
    case 0:
      return placeCommand(book, cmd, options);
    case 1:
      return map(cancelCommand(book, cmd), unjudged);
    case 2:
      return ok(unjudged(rejected(book, cmd, "replace unsupported")));
  }
};
/** og applyCommand, for a caller that learns nothing while judging makers. */
export const applyBookCommand = <F = never,>(
  book: Book,
  cmd: OrderCmd,
  options: BookOptions<F> = {},
): Result<BookStep, BookError | F> => map(judgedBookCommand(book, cmd, options), (j) => j.value);
export type ResumedBook = BookStep & { readonly takerOrderId: string };
/**
 * The younger top after its walk: blocked by its own owner it is cancelled, filled it leaves, partly filled it shrinks.
 */
const resumedTaker = <L,>(run: MatchRun<L>, taker: BookOrder): Result<Book, BookError> => {
  switch (true) {
    case run.blockingOrderId !== undefined:
      return ok(
        bumped(removeBookOrder(run.book, taker.orderId) ?? run.book, BOOK_EVENT_TAG.cancel, taker.priceTicks, 0),
      );
    case run.remaining === 0n:
      return ok(removeBookOrder(run.book, taker.orderId) ?? run.book);
    case run.remaining < taker.qtyLots:
      return reduceBookOrder(run.book, taker, run.remaining);
    default:
      return ok(run.book);
  }
};
type Tops<L> = { readonly bid: BookOrder | null; readonly ask: BookOrder | null; readonly judge: Judge<L> };
/**
 * og resumeCrossedBook: when the eligible tops cross, the younger resting order takes against the older side. The
 * answer carries what the caller learned judging makers.
 */
export const judgedResume = <F = never, L = never>(
  book: Book,
  options: BookOptions<F, L> = {},
): Result<Judged<ResumedBook | null, L>, BookError | F> => {
  const tops = chain(findBestOrder(book, 0, options, NO_JUDGE), (bid) =>
    map(findBestOrder(book, 1, options, bid.judge), (ask): Tops<L> => ({
      bid: bid.best,
      ask: ask.best,
      judge: ask.judge,
    })),
  );
  return chain(tops, ({ bid, ask, judge }): Result<Judged<ResumedBook | null, L>, BookError | F> => {
    if (!bid || !ask || bid.priceTicks < ask.priceTicks) return ok({ value: null, learned: judge.learned });
    if (bid.seq === ask.seq) return bookErr(`BOOK_CORRUPTION: crossed top orders share seq ${bid.seq}`);
    const taker = bid.seq > ask.seq ? bid : ask;
    return chain(matchBook(book, judge, taker, options), (run) =>
      map(resumedTaker(run, taker), (state) => ({
        value: run.events.length === 0 ? null : { state, events: run.events, takerOrderId: taker.orderId },
        learned: run.judge.learned,
      })),
    );
  });
};
/** og resumeCrossedBook, for a caller that learns nothing while judging makers. */
export const resumeCrossedBook = <F = never,>(
  book: Book,
  options: BookOptions<F> = {},
): Result<ResumedBook | null, BookError | F> => map(judgedResume(book, options), (j) => j.value);
/** og materializeCommittedRemainder: rest a committed remainder at the book's next sequence. */
export const materializeCommittedRemainder = (
  book: Book,
  o: Pick<BookOrder, "orderId" | "ownerId" | "side" | "priceTicks" | "qtyLots">,
): Result<Book, BookError> => {
  if (o.qtyLots <= 0n || o.qtyLots > MAX_ORDERBOOK_QTY_LOTS) return bookErr("BOOK_REMAINDER_QTY_INVALID");
  if (o.priceTicks <= 0n) return bookErr("BOOK_REMAINDER_PRICE_INVALID");
  if (book.orders.has(o.orderId)) return bookErr("BOOK_REMAINDER_DUPLICATE");
  if (book.orders.size >= book.params.maxOrders) return bookErr("Out of order slots");
  const seq = book.nextSeq;
  return map(addBookOrder(book, { ...o, seq }), (added) =>
    bumped({ ...added, nextSeq: seq + 1 }, BOOK_EVENT_TAG.rest, o.priceTicks, o.qtyLots));
};
/** og reduceBookOrderQuantity: committed cross-j fill progress. */
export const reduceBookOrderQuantity = (book: Book, orderId: string, nextQtyLots: bigint): Result<Book, BookError> => {
  const current = book.orders.get(orderId);
  if (!current) return bookErr(`BOOK_ORDER_INDEX_MISSING:${orderId}`);
  if (nextQtyLots <= 0n || nextQtyLots >= current.qtyLots) return bookErr(`BOOK_ORDER_REDUCTION_INVALID:${orderId}`);
  return reduceBookOrder(book, current, nextQtyLots);
};
/** og recordAcceptedUsdAskPrice. */
export const recordAcceptedUsdAskPrice = (book: Book, priceTicks: bigint): Result<Book, BookError> => {
  if (priceTicks <= 0n) return bookErr("BOOK_USD_ASK_PRICE_INVALID");
  if (book.lastAcceptedUsdAskPriceTicks === priceTicks) return ok(book);
  return ok(bumped({ ...book, lastAcceptedUsdAskPriceTicks: priceTicks }, BOOK_EVENT_TAG.usdAsk, priceTicks, 0));
};


// Views.

export const bestBid = (b: Book): bigint | null => b.bidPages.at(-1)?.key.priceTicks ?? null;
export const bestAsk = (b: Book): bigint | null => b.askPages[0]?.key.priceTicks ?? null;
/** og getBookOrders: resting orders by sequence. */
export const bookOrders = (b: Book): readonly BookOrder[] => [...b.orders.values()].toSorted((l, r) => l.seq - r.seq);
export type BookLevel = {
  readonly priceTicks: bigint;
  readonly qtyLots: bigint;
  readonly ownerIds: readonly string[];
  readonly orderIds: readonly string[];
};
const levelOf = (side: BookSide, rows: readonly BookPageRow[]): BookLevel => {
  const orders = rows.flatMap((row) => pageOrders(side, row));
  return {
    priceTicks: (rows[0] as BookPageRow).key.priceTicks,
    qtyLots: orders.reduce((sum, o) => sum + o.qtyLots, 0n),
    ownerIds: [...new Set(orders.map((o) => o.ownerId))],
    orderIds: orders.map((o) => o.orderId),
  };
};
/** og getBookSideLevels: aggregated price levels in priority order. */
export const bookSideLevels = (b: Book, side: BookSide, depth = 10): readonly BookLevel[] =>
  priceLevels(orderedPages(sideRows(b, side), side))
    .filter((_, i) => i < depth)
    .map((rows) => levelOf(side, rows));
/** The rows before the first one `keep` refuses. */
const leadingRows = (rows: readonly BookPageRow[], keep: (r: BookPageRow) => boolean): readonly BookPageRow[] => {
  const stop = rows.findIndex((r) => !keep(r));
  return stop < 0 ? rows : rows.slice(0, stop);
};
/**
 * og bookOrdersOutsidePriceRange: orders priced below `min` or above `max` (asks/bids, low tail first then high tail
 * per side).
 */
export const bookOrdersOutsidePriceRange = (
  b: Book,
  min: bigint,
  max: bigint,
): Result<readonly BookOrder[], BookError> => {
  if (min <= 0n || max < min) return bookErr("BOOK_PRICE_RANGE_INVALID");
  const outside = (side: BookSide): readonly BookOrder[] => {
    const rows = sideRows(b, side);
    const low = leadingRows(rows, (r) => r.key.priceTicks < min);
    const high = leadingRows(orderedPages(rows, 0), (r) => r.key.priceTicks > max);
    return [...low, ...high].flatMap((row) => pageOrders(side, row));
  };
  return ok([...outside(0), ...outside(1)]);
};

// ---- hub order book inside entity consensus: og entity/tx/handlers/account/orderbook/
// {index,queue,cancels,helpers,same/*}.ts, orderbook/cross-j/orderbook.ts applyCommittedSwapCancelsToOrderbook,
// account/utils.ts pair policy, and the cross-j book pass (cross/*); remote cancel routing and the book lifecycle come
// after it. og mutates one pass object from deep inside and throws its halts; here each step takes the pass and hands
// back the next one, and every halt is an `entity_invariant` with og's message. ----
export type SwapRef = { readonly offerId: string; readonly accountId: string };
/** The signed terms of one swap offer, as the book reads them. */
type OfferTerms = {
  readonly makerIsLeft: boolean;
  readonly fromEntity: string;
  readonly toEntity: string;
  readonly createdHeight: number;
  readonly giveTokenId: number;
  readonly giveTokenDecimals: number;
  readonly giveAmount: bigint;
  readonly wantTokenId: number;
  readonly wantTokenDecimals: number;
  readonly wantAmount: bigint;
  readonly maxFee: bigint;
  readonly minNetReceive: bigint;
};
/**
 * og SwapOfferEvent for a committed same-j offer (committed-input.ts buildSameJurisdictionSwapOfferEvent); og marks it
 * accountOutputVerified.
 */
export type SwapOfferEvent = SwapRef & OfferTerms & {
  readonly priceTicks?: bigint | undefined;
  readonly timeInForce?: 0 | 1 | 2 | undefined;
  /**
   * og SwapOfferEvent.crossJurisdiction: a cross-j order the book owner admitted (book-order.ts
   * buildCommittedCrossJurisdictionOfferEvent).
   */
  readonly crossJurisdiction?: CrossRoute | undefined;
  /**
   * og same-j-swap-output.ts: the Account output is the commitment evidence for a same-j offer (orderbook-admission.ts
   * skips the committed-state re-read).
   */
  readonly accountOutputVerified?: true | undefined;
};
/**
 * og CommittedAccountEffects swapOffersCreated / swapOffersCancelled / swapCancelRequests, collected over one Entity
 * frame.
 */
export type SwapEvents = {
  readonly created: readonly SwapOfferEvent[];
  readonly cancelled: readonly SwapRef[];
  readonly cancelRequests: readonly SwapRef[];
};
export const joinSwapEvents = (a: SwapEvents | undefined, b: SwapEvents | undefined): SwapEvents | undefined => {
  if (a === undefined) return b;
  if (b === undefined) return a;
  return {
    created: [...a.created, ...b.created],
    cancelled: [...a.cancelled, ...b.cancelled],
    cancelRequests: [...a.cancelRequests, ...b.cancelRequests],
  };
};
const tif = (t: number | undefined): 0 | 1 | 2 | undefined => (t === 0 || t === 1 || t === 2 ? t : undefined);
/** og buildSameJurisdictionSwapOfferEvent from the Account's swapOfferUpsert snapshot. */
export const swapOfferEvent = (accountId: string, e: Of<Effect, "swap_offer_upsert">): SwapOfferEvent => ({
  offerId: e.offer.offerId,
  accountId,
  makerIsLeft: e.offer.makerIsLeft,
  fromEntity: e.left,
  toEntity: e.right,
  createdHeight: e.offer.createdHeight,
  giveTokenId: Number(e.offer.giveTokenId),
  giveTokenDecimals: e.offer.giveTokenDecimals,
  giveAmount: e.offer.giveAmount,
  wantTokenId: Number(e.offer.wantTokenId),
  wantTokenDecimals: e.offer.wantTokenDecimals,
  wantAmount: e.offer.wantAmount,
  maxFee: e.offer.maxFee,
  minNetReceive: e.offer.minNetReceive,
  priceTicks: e.offer.priceTicks,
  ...opt("timeInForce", tif(e.offer.timeInForce)),
  accountOutputVerified: true,
});
/**
 * The matcher's view of one hub Account (og hubState.accounts row): status, committed offers, and the resolves already
 * queued (mempool + our pending frame).
 */
export type HubAccount = {
  readonly active: boolean;
  readonly left: string;
  readonly right: string;
  readonly offers: ReadonlyMap<string, SwapOffer>;
  readonly queued: readonly WireAccountTx[];
  /** og account.state.pulls: the committed cross-j pulls the clear lifecycle reads (not read by the matcher). */
  readonly pulls?: ReadonlyMap<string, PullRow> | undefined;
};
export type Hub = {
  readonly id: string;
  readonly ext: OrderbookExt;
  readonly accounts: ReadonlyMap<string, HubAccount>;
  readonly takerFeeBps: number;
  /** og hubState.timestamp, crossJurisdictionSwaps and crossJurisdictionBookAdmissions: what the cross-j pass reads. */
  readonly timestamp?: number | undefined;
  readonly crossSwaps?: ReadonlyMap<string, CrossRoute> | undefined;
  readonly crossAdmissions?: BookAdmissions | undefined;
};
export type BookTx = { readonly accountId: string; readonly tx: AccountTx };
/**
 * og MatchResult (same-j): Account txs in queue order, the final book of every touched pair in first-touch order, and
 * the committed pair dimensions.
 */
export type BookMatch = {
  readonly accountTxs: readonly BookTx[];
  readonly books: ReadonlyMap<string, Book>;
  readonly pairDimensions: ReadonlyMap<string, PairDimensions>;
  readonly crossFills: readonly CrossFillInstruction[];
};
/** og NormalizedOrderbookOffer (same-j). */
type BookOffer = SwapRef & OfferTerms & { readonly priceTicks: bigint; readonly timeInForce: 0 | 1 | 2 };
/** An offer as signed, before the book normalizes its price and time in force. */
type RawOffer = { readonly offerId: string } & OfferTerms & {
  readonly priceTicks?: bigint | undefined;
  readonly timeInForce?: number | undefined;
};
const haltMessage = (e: EntityError): string => (e._tag === "entity_invariant" ? e.reason : e._tag);
/** A book refusal where the hub cannot refuse: og throws it, so it halts the frame. */
const bookFault = (e: BookError): EntityError => ({ _tag: "entity_invariant", reason: e.code });
type Mismatch = readonly [field: string, stored: unknown, canonical: unknown];
/** og's mismatch report: each stored field beside its canonical value. */
const mismatchText = (fields: readonly Mismatch[]): string =>
  fields.map(([field, stored, canonical]) => `stored${field}=${stored} canonical${field}=${canonical}`).join(" ");
const swapKeyOf = (accountId: string, offerId: string): string => `${accountId}:${offerId}`;
/** og parseNamespacedOrderId: the account id is everything before the last colon. */
const parseOrderId = (orderId: string, code: string): Result<SwapRef, EntityError> => {
  const i = orderId.lastIndexOf(":");
  if (i <= 0 || i === orderId.length - 1) return invariant(`${code}: order=${orderId}`);
  return ok({ accountId: orderId.slice(0, i), offerId: orderId.slice(i + 1) });
};
const dimsOf = (give: number, want: number, giveDecimals: number, wantDecimals: number): SwapDims => {
  const side = swapSide(give, want);
  return side === 1 ? { side, bd: giveDecimals, qd: wantDecimals } : { side, bd: wantDecimals, qd: giveDecimals };
};
type OfferTokens = Pick<OfferTerms, "giveTokenId" | "wantTokenId" | "giveTokenDecimals" | "wantTokenDecimals">;
const offerDims = (o: OfferTokens): SwapDims =>
  dimsOf(o.giveTokenId, o.wantTokenId, o.giveTokenDecimals, o.wantTokenDecimals);
/** The base amount of an offer: what it gives when it sells the base, what it wants when it buys it. */
const baseAmountOf = (o: OfferTerms, d: SwapDims): bigint => (d.side === 1 ? o.giveAmount : o.wantAmount);
const quoteAmountOf = (o: OfferTerms, d: SwapDims): bigint => (d.side === 1 ? o.wantAmount : o.giveAmount);
const makerOf = (o: OfferTerms): string => (o.makerIsLeft ? o.fromEntity : o.toEntity);
const termsOf = (o: OfferTerms): OfferTerms => ({
  makerIsLeft: o.makerIsLeft,
  fromEntity: o.fromEntity,
  toEntity: o.toEntity,
  createdHeight: o.createdHeight,
  giveTokenId: o.giveTokenId,
  giveTokenDecimals: o.giveTokenDecimals,
  giveAmount: o.giveAmount,
  wantTokenId: o.wantTokenId,
  wantTokenDecimals: o.wantTokenDecimals,
  wantAmount: o.wantAmount,
  maxFee: o.maxFee,
  minNetReceive: o.minNetReceive,
});
/** A committed Account offer in the book's terms, before normalization. */
const storedOffer = (account: HubAccount, offerId: string, o: SwapOffer): RawOffer => ({
  offerId,
  makerIsLeft: o.makerIsLeft,
  fromEntity: account.left,
  toEntity: account.right,
  createdHeight: o.createdHeight,
  giveTokenId: Number(o.giveTokenId),
  giveTokenDecimals: o.giveTokenDecimals,
  giveAmount: o.giveAmount,
  wantTokenId: Number(o.wantTokenId),
  wantTokenDecimals: o.wantTokenDecimals,
  wantAmount: o.wantAmount,
  maxFee: o.maxFee,
  minNetReceive: o.minNetReceive,
  priceTicks: o.priceTicks,
  timeInForce: o.timeInForce,
});
/** og normalizeSwapOfferForOrderbook: a missing price is recomputed from the amounts; a non-positive one halts. */
const normalizeOffer = (o: RawOffer, accountId: string): Result<BookOffer, EntityError> => {
  const d = offerDims(o);
  const signed = o.priceTicks !== undefined && o.priceTicks > 0n ? o.priceTicks : undefined;
  const priceTicks = signed ?? priceTicksOf(d, baseAmountOf(o, d), quoteAmountOf(o, d));
  if (priceTicks <= 0n) return invariant(`ORDERBOOK_NORMALIZE_INVALID_PRICE: offer=${o.offerId}`);
  return ok({ offerId: o.offerId, accountId, ...termsOf(o), priceTicks, timeInForce: tif(o.timeInForce) ?? 0 });
};


// -- pair policy: which pair an offer trades on, its book bucket, and the price band around the book's anchor

/** og account/utils.ts SWAP_PAIR_POLICY_BY_BASE_QUOTE: book bucket width and MM mid price per base/quote. */
type PairPolicy = { readonly bucket: number; readonly mid: bigint };
const PAIR_POLICIES: ReadonlyMap<string, PairPolicy> = new Map([
  ["2/1", { bucket: 10_000, mid: 25_000_000n }],
  ["2/3", { bucket: 10_000, mid: 25_000_000n }],
  ["1/3", { bucket: 10_000, mid: 10_000n }],
  ["4/1", { bucket: 100, mid: 1_200n }],
  ["4/3", { bucket: 100, mid: 1_200n }],
  ["5/1", { bucket: 10, mid: 200n }],
  ["5/3", { bucket: 10, mid: 200n }],
]);
const DEFAULT_PAIR_POLICY: PairPolicy = { bucket: 10_000, mid: 10_000n };
/** The pair's policy, and whether it is the built-in one (only then is its mid an anchor). */
type PairRule = { readonly policy: PairPolicy; readonly explicit: boolean };
type CanonicalPair = { readonly base: number; readonly quote: number; readonly pairId: string };
/** og getSwapPairOrientation: a reference stable is the quote; otherwise the lower id is the base. */
const orientation = (a: number, b: number): readonly [base: number, quote: number] => {
  const aStable = REFERENCE_STABLES.has(a);
  const bStable = REFERENCE_STABLES.has(b);
  switch (true) {
    case aStable && !bStable:
      return [b, a];
    case bStable && !aStable:
      return [a, b];
    default:
      return [Math.min(a, b), Math.max(a, b)];
  }
};
/** The book is keyed by the numerically ordered pair, whichever token is the base. */
const canonicalPairOf = (a: number, b: number): CanonicalPair => {
  const [base, quote] = orientation(a, b);
  return { base, quote, pairId: `${Math.min(a, b)}/${Math.max(a, b)}` };
};
/**
 * og hasSwapPairPolicyForDimensions: the static policy is authority only when both signed decimals match the built-in
 * tokens.
 */
const pairRuleOf = (base: number, quote: number, bd: number, qd: number): PairRule => {
  const policy = PAIR_POLICIES.get(`${base}/${quote}`);
  const explicit = policy !== undefined && TOKEN_DECIMALS.get(base) === bd && TOKEN_DECIMALS.get(quote) === qd;
  return explicit ? { policy, explicit } : { policy: DEFAULT_PAIR_POLICY, explicit };
};
const MAX_ORDERBOOK_ORDERS_PER_PAIR = 10_000;
const PRICE_REJECT_BPS = 3_000n;
/** An empty book for a pair the hub has not traded yet. */
const freshBook = (policy: PairPolicy): Result<Book, EntityError> => {
  const params = {
    bucketWidthTicks: BigInt(Math.max(1, policy.bucket)),
    maxOrders: MAX_ORDERBOOK_ORDERS_PER_PAIR,
    stpPolicy: 1,
  } as const;
  return mapErr(createBook(params), bookFault);
};
/** og resolvePairBandReference: the mid of the touch, else its one side, else the built-in mid. */
const bandAnchor = (rule: PairRule, bid: bigint | null, ask: bigint | null): bigint | null => {
  switch (true) {
    case bid !== null && ask !== null:
      return (bid + ask) / 2n;
    case bid !== null:
      return bid;
    case ask !== null:
      return ask;
    default:
      return rule.explicit ? rule.policy.mid : null;
  }
};
type Band = { readonly min: bigint; readonly max: bigint };
/** og deriveSameOrderbookPriceBandBounds: +/-30% around the anchor. */
const bandBounds = (anchor: bigint): Result<Band, EntityError> => {
  if (anchor <= 0n) return invariant("ORDERBOOK_PRICE_BAND_ANCHOR_INVALID");
  const offset = (anchor * PRICE_REJECT_BPS) / 10_000n;
  return ok({ min: anchor - offset, max: anchor + offset });
};
/** The book's band, when it has an anchor. */
const bookBand = (rule: PairRule, book: Book): Result<Band | undefined, EntityError> => {
  const anchor = bandAnchor(rule, bestBid(book), bestAsk(book));
  return anchor === null ? ok(undefined) : bandBounds(anchor);
};


// -- materializing an offer: its pair, side, lots and price as one book order

type Materialized = {
  readonly offer: BookOffer;
  readonly bookKey: string;
  readonly bd: number;
  readonly qd: number;
  readonly side: BookSide;
  readonly priceTicks: bigint;
  readonly qtyLots: bigint;
  readonly makerId: string;
  readonly orderId: string;
  readonly pair: PairRule;
};
/** An offer ready to trade: materialized, against its pair's hot book as the offer found it. */
type Prepared = Materialized & {
  readonly book: Book;
  readonly bestBid: bigint | null;
  readonly bestAsk: bigint | null;
};
type Materialization = Tagged<"ok", { m: Materialized }> | Tagged<"reject", { reason: string }>;
const refuseOffer = (reason: string): Result<Materialization, never> => ok({ _tag: "reject", reason });
/** The offer's amounts as base and quote of its canonical pair; an offer across any other pair has none. */
const pairAmounts = (
  o: BookOffer,
  { base, quote }: CanonicalPair,
): { readonly b: bigint; readonly q: bigint } | undefined => {
  switch (true) {
    case o.giveTokenId === base && o.wantTokenId === quote:
      return { b: o.giveAmount, q: o.wantAmount };
    case o.giveTokenId === quote && o.wantTokenId === base:
      return { b: o.wantAmount, q: o.giveAmount };
    default:
      return undefined;
  }
};
/**
 * og deriveSameOrderbookMaterialization: direction, amounts, minimum trade size, lot and exact-quote alignment, then
 * the order's bounds.
 */
const materialization = (o: BookOffer, minTradeSize: bigint): Result<Materialization, EntityError> => {
  const pair = canonicalPairOf(o.giveTokenId, o.wantTokenId);
  const amounts = pairAmounts(o, pair);
  if (amounts === undefined) return refuseOffer("invalid-direction");
  const d = offerDims(o);
  const lot = lotScale(d.bd);
  if (amounts.b <= 0n || amounts.q <= 0n) return refuseOffer("zero-amount");
  if (minTradeSize > 0n && amounts.q < minTradeSize) return refuseOffer(`below-minTradeSize:${amounts.q}`);
  if (amounts.b % lot !== 0n) return refuseOffer(`lot-misaligned:${amounts.b}`);
  if (o.priceTicks <= 0n) return invariant("SWAP_EXACT_QUOTE_PRICE_INVALID");
  const qtyLots = amounts.b / lot;
  const multiple = exactQuoteLots(d.bd, d.qd, o.priceTicks);
  if (qtyLots % multiple !== 0n) return refuseOffer(`quote-lot-misaligned:${qtyLots}:${multiple}`);
  if (qtyLots === 0n || qtyLots > MAX_ORDERBOOK_QTY_LOTS)
    return refuseOffer(`invalid-order:${qtyLots}:${o.priceTicks}`);
  return ok({
    _tag: "ok",
    m: {
      offer: o,
      bookKey: pair.pairId,
      bd: d.bd,
      qd: d.qd,
      side: swapSide(o.giveTokenId, o.wantTokenId),
      priceTicks: o.priceTicks,
      qtyLots,
      makerId: makerOf(o),
      orderId: swapKeyOf(o.accountId, o.offerId),
      pair: pairRuleOf(pair.base, pair.quote, d.bd, d.qd),
    },
  });
};


// -- the same-j pass: what one processOrderbookSwaps run has learned and queued so far

/** One og same-j pass: the hot book cache, queued resolves, suspended makers and committed dimensions. */
type Pass = {
  readonly hub: Hub;
  readonly accountTxs: readonly BookTx[];
  readonly queued: ReadonlySet<string>;
  readonly suspended: ReadonlySet<string>;
  readonly meta: ReadonlyMap<string, BookOffer>;
  readonly swept: ReadonlySet<string>;
  readonly cache: ReadonlyMap<string, Book>;
  readonly updates: ReadonlyMap<string, Book>;
  readonly dims: ReadonlyMap<string, PairDimensions>;
};
/** A step's answer, and the pass as the step leaves it. */
type Passed<T> = { readonly pass: Pass; readonly value: T };
const newPass = (hub: Hub): Pass => ({
  hub,
  accountTxs: [],
  queued: new Set(),
  suspended: new Set(),
  meta: new Map(),
  swept: new Set(),
  cache: new Map(),
  updates: new Map(),
  dims: new Map(hub.ext.pairDimensions),
});
const withMember = <T,>(s: ReadonlySet<T>, x: T): ReadonlySet<T> => (s.has(x) ? s : new Set([...s, x]));
/** A book the pass now works on and will commit: og writes both the hot cache and the touched books. */
const publishBook = (pass: Pass, pairId: string, book: Book): Pass => ({
  ...pass,
  cache: mapSet(pass.cache, pairId, book),
  updates: mapSet(pass.updates, pairId, book),
});
/**
 * A book the pass works on but does not commit by itself: a sweep lands in the hot book, and reaches the committed
 * books only when a later command on the pair publishes it.
 */
const warmBook = (pass: Pass, pairId: string, book: Book): Pass => ({
  ...pass,
  cache: mapSet(pass.cache, pairId, book),
});
/** og hasQueuedSwapResolveForEntityState. */
const hasQueuedResolve = (q: Pick<Pass, "hub" | "queued">, accountId: string, offerId: string): boolean => {
  const pending = q.hub.accounts.get(accountId)?.queued ?? [];
  return q.queued.has(swapKeyOf(accountId, offerId))
    || pending.some((tx) => tx.type === "swap_resolve" && tx.offerId === offerId);
};
type ResolveQueue = Pick<Pass, "hub" | "queued" | "accountTxs">;
/** og queueUniqueSwapResolveForEntityState: a second resolve for the same offer is dropped. */
const queueUniqueResolve = <Q extends ResolveQueue>(q: Q, accountId: string, data: SwapResolveTerms): Q => {
  if (hasQueuedResolve(q, accountId, data.offerId)) return q;
  return {
    ...q,
    queued: withMember(q.queued, swapKeyOf(accountId, data.offerId)),
    accountTxs: [...q.accountTxs, { accountId, tx: { type: "swap_resolve", ...data } }],
  };
};
const cancelTerms = (offerId: string, comment: string): SwapResolveTerms => ({
  offerId,
  fillRatio: 0,
  cancelRemainder: true,
  comment,
});
/**
 * og queueSameSwapResolve: the resolving row never trades again in this pass, even when an identical resolve was
 * already queued.
 */
const queueSame = (pass: Pass, accountId: string, data: SwapResolveTerms): Pass => ({
  ...queueUniqueResolve(pass, accountId, data),
  suspended: withMember(pass.suspended, swapKeyOf(accountId, data.offerId)),
});
const cancelSame = (pass: Pass, ref: SwapRef, comment: string): Pass =>
  queueSame(pass, ref.accountId, cancelTerms(ref.offerId, comment));
/** A resting row cancelled by its owner; og throws a refusal, so it halts. */
const cancelRow = (book: Book, order: Pick<BookOrder, "orderId" | "ownerId">): Result<Book, EntityError> => {
  const cancelled = applyBookCommand(book, { kind: 1, ownerId: order.ownerId, orderId: order.orderId });
  return map(mapErr(cancelled, bookFault), (step) => step.state);
};


// -- judging a resting same-j row

/** og buildLiveSameOfferMeta: the committed Account offer behind a book row; a cross-j or missing offer has none. */
const liveMeta = (hub: Hub, orderId: string): Result<BookOffer | null, EntityError> =>
  chain(parseOrderId(orderId, "ORDERBOOK_MALFORMED_BOOK_ORDER"), ({ accountId, offerId }) => {
    const account = hub.accounts.get(accountId);
    const o = account?.offers.get(offerId);
    if (account === undefined || o === undefined || o.crossJurisdiction !== undefined) return ok(null);
    return normalizeOffer(storedOffer(account, offerId, o), accountId);
  });
/** og classifySameBookMaker's last word: the resting row must be exactly its committed offer. */
const sameRowMatches = (pairId: string, order: BookOrder, meta: BookOffer): Result<void, EntityError> => {
  const d = offerDims(meta);
  const owner = makerOf(meta);
  const qtyLots = baseAmountOf(meta, d) / lotScale(d.bd);
  const same =
    order.side === d.side &&
    order.priceTicks === meta.priceTicks &&
    order.ownerId === owner &&
    order.qtyLots === qtyLots;
  const fields = mismatchText([
    ["Owner", order.ownerId, owner],
    ["Side", order.side, d.side],
    ["Price", order.priceTicks, meta.priceTicks],
    ["QtyLots", order.qtyLots, qtyLots],
  ]);
  return same ? ok(undefined) : invariant(`ORDERBOOK_CACHE_MISMATCH: pair=${pairId} order=${order.orderId} ${fields}`);
};
/**
 * og classifySameBookMaker: an inactive Account cancels, a resolving row is suspended, and the row must equal its
 * committed offer. og also memoizes the live offer it read; that memo only ever repeats liveMeta over a hub that
 * does not change during the pass, so the rewrite reads it again instead.
 */
const classifyMaker = (pass: Pass, pairId: string, order: BookOrder): Result<MakerDisposition, EntityError> =>
  chain(parseOrderId(order.orderId, "ORDERBOOK_MALFORMED_BOOK_ORDER"), ({ accountId }) => {
    const account = pass.hub.accounts.get(accountId);
    const missing = `ORDERBOOK_SAME_SNAPSHOT_MISSING: pair=${pairId} order=${order.orderId}`;
    if (account === undefined) return invariant(missing);
    if (!account.active) return ok("cancel");
    const cached = pass.meta.get(order.orderId);
    const meta = cached === undefined ? liveMeta(pass.hub, order.orderId) : ok(cached);
    return chain(meta, (m): Result<MakerDisposition, EntityError> => {
      if (m === null) return invariant(missing);
      if (hasQueuedResolve(pass, m.accountId, m.offerId)) return ok("suspended");
      return map(sameRowMatches(pairId, order, m), () => "eligible");
    });
  });
/** og applyCommand options for a same-j pair; a halt raised while judging a maker ends the command with it. */
const bookOptions = (pass: Pass, p: Prepared): BookOptions<EntityError> => ({
  suspendedOrderIds: pass.suspended,
  makerVerdict: (maker) => map(classifyMaker(pass, p.bookKey, maker), (disposition) => ({ disposition })),
  executionQtyMultipleAtPrice: (price) => exactQuoteLots(p.bd, p.qd, price),
});
/** A book refusal's code, or the halt a maker judgment raised. */
const bookFailureText = (e: BookError | EntityError): string => (e._tag === "book" ? e.code : haltMessage(e));
/** og containSamePairFailure (live mode): a failed pair command halts the frame. */
const pairFailure = (p: Prepared, message: string): Result<never, EntityError> => {
  const at = `pair=${p.bookKey} account=${p.offer.accountId} offer=${p.offer.offerId}`;
  return invariant(`ORDERBOOK_PAIR_COMMAND_FAILED: ${at} error=${message}`);
};


// -- preparing a same-j offer against its pair's hot book

/** A step that moves the pass and one book together. */
type WithBook = { readonly pass: Pass; readonly book: Book };
/** One out-of-band row leaves the book; a live same-j row queues its cancel, a suspended one stays. */
const sweepRow = (pairId: string) => (s: WithBook, order: BookOrder): Result<WithBook, EntityError> =>
  chain(classifyMaker(s.pass, pairId, order), (disposition) => {
    if (disposition === "suspended") return ok(s);
    const live = disposition === "eligible" ? liveMeta(s.pass.hub, order.orderId) : ok(null);
    return chain(live, (meta) => map(cancelRow(s.book, order), (book) => ({
      book,
      pass: meta === null ? s.pass : cancelSame(s.pass, meta, `outside-anchor-band:${order.priceTicks}`),
    })));
  });
/**
 * og sweepSamePairOutOfBandOffers: once per pair and pass, every resting row outside the anchor band leaves the book.
 */
const sweepPair = (pass: Pass, pairId: string, rule: PairRule, book: Book): Result<WithBook, EntityError> =>
  chain(bookBand(rule, book), (band) => {
    if (band === undefined) return ok({ pass, book });
    const outside = mapErr(bookOrdersOutsidePriceRange(book, band.min, band.max), bookFault);
    return chain(outside, (rows) => foldResult(rows, { pass, book }, sweepRow(pairId)));
  });
/** og sweeps each pair once per pass, the first time an offer touches it. */
const sweptOnce = (pass: Pass, m: Materialized, book: Book): Result<WithBook, EntityError> =>
  pass.swept.has(m.bookKey)
    ? ok({ pass, book })
    : sweepPair({ ...pass, swept: withMember(pass.swept, m.bookKey) }, m.bookKey, m.pair, book);
/** The pair's hot book: the pass's working copy, else the committed one (now hot), else a fresh one. */
const hotBook = (pass: Pass, pairId: string, fresh: () => Result<Book, EntityError>): Result<WithBook, EntityError> => {
  const cached = pass.cache.get(pairId);
  const committed = pass.hub.ext.books.get(pairId);
  if (cached !== undefined) return ok({ pass, book: cached });
  if (committed !== undefined)
    return ok({ pass: { ...pass, cache: mapSet(pass.cache, pairId, committed) }, book: committed });
  return map(fresh(), (book) => ({ pass, book }));
};
/**
 * og materializeSameOffer: a resolving offer is skipped; a malformed one or one against the pair's committed dimensions
 * is cancelled.
 */
const materializeSame = (
  pass: Pass,
  o: BookOffer,
  minTradeSize: bigint,
): Result<Passed<Materialized | null>, EntityError> => {
  if (hasQueuedResolve(pass, o.accountId, o.offerId)) return ok({ pass, value: null });
  return map(materialization(o, minTradeSize), (r) => {
    if (r._tag === "reject") return { pass: cancelSame(pass, o, r.reason), value: null };
    const committed = pass.dims.get(r.m.bookKey);
    const clashes =
      committed !== undefined && (committed.baseTokenDecimals !== r.m.bd || committed.quoteTokenDecimals !== r.m.qd);
    return clashes ? { pass: cancelSame(pass, o, "pair-decimals-mismatch"), value: null } : { pass, value: r.m };
  });
};
/** og prepareSameOffer: the pair's hot book, its one sweep, then the price band. */
const prepareSame = (pass: Pass, m: Materialized): Result<Passed<Prepared | null>, EntityError> =>
  chain(hotBook(pass, m.bookKey, () => freshBook(m.pair.policy)), (hot) =>
    chain(sweptOnce(hot.pass, m, hot.book), (swept) => {
      const { book } = swept;
      const touched = book === hot.book ? swept.pass : warmBook(swept.pass, m.bookKey, book);
      return map(bookBand(m.pair, book), (band): Passed<Prepared | null> => {
        if (band !== undefined && (m.priceTicks < band.min || m.priceTicks > band.max)) {
          return { pass: cancelSame(touched, m.offer, `outside-anchor-band:${m.priceTicks}`), value: null };
        }
        const meta = mapSet(touched.meta, m.orderId, { ...m.offer, priceTicks: m.priceTicks });
        return { pass: { ...touched, meta }, value: { ...m, book, bestBid: bestBid(book), bestAsk: bestAsk(book) } };
      });
    }));
/** Materialize then prepare: the offer ready against its pair's hot book, or null once it was cancelled or skipped. */
const readySame = (pass: Pass, o: BookOffer, minTradeSize: bigint): Result<Passed<Prepared | null>, EntityError> =>
  chain(materializeSame(pass, o, minTradeSize), ({ pass: next, value: m }) =>
    m === null ? ok({ pass: next, value: null }) : prepareSame(next, m));
/** og keepIdenticalRestingOrder: an offer already resting unchanged stays; a changed one halts. */
const keepResting = (pass: Pass, p: Prepared): Result<Passed<boolean>, EntityError> => {
  const existing = p.book.orders.get(p.orderId);
  if (existing === undefined) return ok({ pass, value: false });
  const same = existing.ownerId === p.makerId && existing.side === p.side && existing.qtyLots === p.qtyLots
    && existing.priceTicks === p.priceTicks;
  if (!same) return invariant(`ORDERBOOK_CACHE_MISMATCH: pair=${p.bookKey} order=${p.orderId}`);
  return ok({ pass: { ...pass, cache: mapSet(pass.cache, p.bookKey, p.book) }, value: true });
};


// -- placing a same-j offer

/** og applySameOfferCommand: place the offer; a full book cancels it, any other refusal halts. */
const placeSame = (pass: Pass, p: Prepared): Result<Passed<BookStep | null>, EntityError> => {
  const cmd: OrderCmd = {
    kind: 0,
    ownerId: p.makerId,
    orderId: p.orderId,
    side: p.side,
    tif: p.offer.timeInForce,
    postOnly: false,
    priceTicks: p.priceTicks,
    qtyLots: p.qtyLots,
  };
  const r = applyBookCommand(p.book, cmd, bookOptions(pass, p));
  if (r.ok) return ok({ pass, value: r.value });
  const full = r.error._tag === "book" && r.error.code === "Out of order slots";
  if (!full) return pairFailure(p, bookFailureText(r.error));
  return ok({ pass: cancelSame(pass, p.offer, `book-full:${p.book.params.maxOrders}`), value: null });
};
/** og resumeCrossedSameBook. */
const resumeSame = (pass: Pass, p: Prepared): Result<ResumedBook | null, EntityError> => {
  const r = resumeCrossedBook(p.book, bookOptions(pass, p));
  return r.ok ? ok(r.value) : pairFailure(p, bookFailureText(r.error));
};


// -- settling a same-j command: every fill becomes the exact swap_resolve of its Account

/** og SwapNetAuthorizationError (a fee-authority refusal of one fill) versus a halt. */
type FillFault = Tagged<"auth"> | Tagged<"halt", { message: string }>;
const AUTH: FillFault = { _tag: "auth" };
const fillHalt = (message: string): Result<never, FillFault> => err({ _tag: "halt", message });
const fromEntityError = <T,>(r: Result<T, EntityError>): Result<T, FillFault> =>
  mapErr(r, (e): FillFault => ({ _tag: "halt", message: haltMessage(e) }));
/** The terms a resting row trades on: its tokens, amounts and net authority. */
type RestingTerms = Authorized & {
  readonly giveTokenId: number;
  readonly giveTokenDecimals: number;
  readonly wantTokenId: number;
  readonly wantTokenDecimals: number;
};
/** The offer a fill executes against, quantized, at the price it rests at. */
type ExecOffer = RestingTerms & {
  readonly quantizedGive: bigint;
  readonly quantizedWant: bigint;
  readonly priceTicks: bigint;
};
/** og materializeCanonicalRestingOffer: the resting row's original lots at its resting price, as give/want. */
const canonicalResting = (r: RestingTerms, priceTicks: bigint, qtyLots: bigint): Omit<ExecOffer, keyof NetAuth> => {
  const d = offerDims(r);
  const base = qtyLots <= 0n ? 0n : qtyLots * lotScale(d.bd);
  const quote = quoteAt(d.bd, d.qd, base, priceTicks);
  const [give, want] = d.side === 1 ? [base, quote] : [quote, base];
  return {
    giveTokenId: r.giveTokenId,
    giveTokenDecimals: r.giveTokenDecimals,
    wantTokenId: r.wantTokenId,
    wantTokenDecimals: r.wantTokenDecimals,
    giveAmount: give,
    wantAmount: want,
    quantizedGive: give,
    quantizedWant: want,
    priceTicks,
  };
};
/**
 * og deriveSwapFillPolicyFee: the hub's taker fee, bounded by the same pro-rata authority as the maker's signed limit.
 */
const policyFee = (
  o: Pick<Authorized, "giveAmount" | "wantAmount">,
  executed: Pick<Fill, "give" | "want">,
  bps: number,
  closes: boolean,
): Result<bigint, FillFault> => {
  if (o.wantAmount <= 0n || !Number.isSafeInteger(bps) || bps < 0 || bps > 10_000) return err(AUTH);
  const maxFee = (o.wantAmount * BigInt(bps)) / 10_000n;
  const policy: NetAuth = { maxFee, minNetReceive: o.wantAmount - maxFee };
  const authorized: Authorized = { ...o, ...policy };
  const refused = maxFee >= o.wantAmount
    || policy.minNetReceive <= 0n
    || offerAuthError({ giveAmount: 1n, wantAmount: o.wantAmount, ...policy }) !== undefined
    || offerAuthError(authorized) !== undefined
    || executed.give < 0n || executed.give > o.giveAmount || executed.want < 0n;
  if (refused) return err(AUTH);
  const { num, den } = usedShare(authorized, { ...executed, fee: 0n }, closes);
  return ok((maxFee * num) / den);
};
type Trade = Extract<BookEvent, { type: "TRADE" }>;
type SameFill = { readonly filledLots: bigint; readonly originalLots: bigint; readonly weightedCost: bigint };
/** Each trade counts once for its maker and once for its taker. */
const tradeLegs = (t: Trade) => [
  { orderId: t.makerOrderId, originalLots: t.makerQtyBefore, t },
  { orderId: t.takerOrderId, originalLots: t.takerQtyTotal, t },
] as const;
/** og aggregateSameTradeFills: per order, maker then taker, in trade order. */
const aggregateFills = (trades: readonly Trade[]): ReadonlyMap<string, SameFill> =>
  trades.flatMap(tradeLegs).reduce<ReadonlyMap<string, SameFill>>((fills, { orderId, originalLots, t }) => {
    const e = fills.get(orderId);
    const fill = e === undefined
      ? { filledLots: t.qty, originalLots, weightedCost: t.price * t.qty }
      : { ...e, filledLots: e.filledLots + t.qty, weightedCost: e.weightedCost + t.price * t.qty };
    return mapSet(fills, orderId, fill);
  }, new Map());
/** Everything one command's settlement reads: the pass before it, the taker, and the book the command left. */
type Settling = {
  readonly pass: Pass;
  readonly p: Prepared;
  readonly book: Book;
  readonly comment: string | undefined;
};
/** The taker's own terms, or the resting row's original lots re-authorized at its resting price. */
const executingOffer = (
  s: Settling,
  ref: SwapRef,
  orderId: string,
  fill: SameFill,
  account: HubAccount,
): Result<ExecOffer, FillFault> => {
  const { p, pass } = s;
  if (orderId === p.orderId)
    return ok({ ...p.offer, quantizedGive: p.offer.giveAmount, quantizedWant: p.offer.wantAmount });
  const stored = account.offers.get(ref.offerId);
  const fromStore: RestingTerms | undefined =
    stored === undefined
      ? undefined
      : { ...stored, giveTokenId: Number(stored.giveTokenId), wantTokenId: Number(stored.wantTokenId) };
  const resting = pass.meta.get(orderId) ?? fromStore;
  if (resting === undefined) {
    return fillHalt(
      `ORDERBOOK_FILL_SOURCE_MISSING: order=${orderId} pair=${p.bookKey} account=${ref.accountId} offer=${ref.offerId}`,
    );
  }
  const canonical = canonicalResting(resting, fill.weightedCost / fill.filledLots, fill.originalLots);
  const auth = requantizeAuth(resting, canonical.giveAmount, canonical.wantAmount);
  return auth.ok ? ok({ ...canonical, ...auth.value }) : err(AUTH);
};
/** og buildSwapResolveDataFromOrderbookFill: the executed amounts in the offer's give/want terms, as an exact ratio. */
const fillTerms = (s: Settling, ref: SwapRef, orderId: string, o: ExecOffer, fill: SameFill): SwapResolveTerms => {
  const taker = orderId === s.p.orderId;
  const d = offerDims(o);
  const lot = lotScale(d.bd);
  const execBase = fill.filledLots * lot;
  const execQuote = quoteAt(d.bd, d.qd, lot, fill.weightedCost);
  const [give, want] = d.side === 0 ? [execQuote, execBase] : [execBase, execQuote];
  const executed = give > 0n && want > 0n;
  const exact = executed ? exactFillRatio(o.quantizedGive, give) : { n: 0n, d: 1n };
  return {
    offerId: ref.offerId,
    restingGiveTokenId: String(o.giveTokenId) as TokenId,
    restingWantTokenId: String(o.wantTokenId) as TokenId,
    fillRatio: Math.min(fillRatioOf(exact), MAX_FILL),
    fillNumerator: exact.n,
    fillDenominator: exact.d,
    cancelRemainder: !s.book.orders.has(orderId),
    ...(executed ? { executionGiveAmount: give, executionWantAmount: want } : {}),
    restingPriceTicks: o.priceTicks,
    restingGiveAmount: o.giveAmount,
    restingWantAmount: o.wantAmount,
    restingQuantizedGive: o.quantizedGive,
    restingQuantizedWant: o.quantizedWant,
    ...(taker && s.comment ? { comment: s.comment } : {}),
  };
};
/**
 * og buildSameFillResolvePlan: the exact execution of one fill as a swap_resolve, fee included, authorized against the
 * executing offer.
 */
const fillResolve = (
  s: Settling,
  ref: SwapRef,
  orderId: string,
  fill: SameFill,
  account: HubAccount,
): Result<SwapResolveTerms, FillFault> => {
  const { filledLots, weightedCost } = fill;
  const taker = orderId === s.p.orderId;
  if (filledLots <= 0n || weightedCost <= 0n) {
    return fillHalt(
      `ORDERBOOK_FILL_LOOKUP_FAILED: invalid fill aggregate weightedCost=${weightedCost} filledLots=${filledLots}`,
    );
  }
  if (!taker && weightedCost % filledLots !== 0n) {
    return fillHalt(
      `ORDERBOOK_FILL_LOOKUP_FAILED: non-integral resting price weightedCost=${weightedCost} filledLots=${filledLots}`,
    );
  }
  return chain(executingOffer(s, ref, orderId, fill, account), (o) => {
    const base = fillTerms(s, ref, orderId, o, fill);
    const executed = { give: base.executionGiveAmount ?? 0n, want: base.executionWantAmount ?? 0n };
    const fee = taker ? policyFee(o, executed, s.pass.hub.takerFeeBps, base.cancelRemainder) : ok(0n);
    return chain(fee, (feeAmount) => {
      const data: SwapResolveTerms =
        feeAmount > 0n ? { ...base, feeTokenId: String(o.wantTokenId) as TokenId, feeAmount } : base;
      return netAuthError(o, { ...executed, fee: feeAmount }, base.cancelRemainder) === undefined
        ? ok(data)
        : err(AUTH);
    });
  });
};
type FillPlan = { readonly accountId: string; readonly data: SwapResolveTerms };
/** One aggregated fill as the swap_resolve its Account will carry; a participant already resolving halts. */
const planFill = (s: Settling, orderId: string, fill: SameFill): Result<FillPlan, FillFault> =>
  chain(fromEntityError(parseOrderId(orderId, "ORDERBOOK_FILL_LOOKUP_FAILED")), (ref) => {
    const account = s.pass.hub.accounts.get(ref.accountId);
    if (hasQueuedResolve(s.pass, ref.accountId, ref.offerId)) {
      return fillHalt(`ORDERBOOK_TRADE_PARTICIPANT_ALREADY_RESOLVING: account=${ref.accountId} offer=${ref.offerId}`);
    }
    if (account === undefined) {
      return fillHalt(`ORDERBOOK_ACCOUNT_LOOKUP_FAILED: offer=${ref.offerId} accountId=${ref.accountId}`);
    }
    return map(fillResolve(s, ref, orderId, fill, account), (data) => ({ accountId: ref.accountId, data }));
  });
/**
 * og isAuthorizedUsdReferenceAsk: only the hub's USD quote authority, selling a volatile base for the reference token,
 * moves the USD reference.
 */
const usdReferenceAsk = (profile: HubProfile, p: Prepared): boolean =>
  p.side === 1
    && p.offer.giveTokenId !== profile.referenceTokenId
    && p.offer.wantTokenId === profile.referenceTokenId
    && p.makerId.toLowerCase() === profile.usdQuoteAuthorityEntityId.toLowerCase();
/** The book after an accepted USD authority ask records its price. */
const withUsdReference = (pass: Pass, p: Prepared, book: Book): Result<Book, FillFault> =>
  usdReferenceAsk(pass.hub.ext.hubProfile, p)
    ? mapErr(recordAcceptedUsdAskPrice(book, p.priceTicks), (e): FillFault => ({ _tag: "halt", message: e.code }))
    : ok(book);
/**
 * og processSameCommandEvents: an unfilled reject cancels the offer; fills are all authorized before any is queued.
 * Returns the book to commit.
 */
const commandEvents = (pass: Pass, p: Prepared, result: BookStep): Result<Passed<Book>, FillFault> => {
  const rejects = result.events.flatMap((e) => (e.type === "REJECT" && e.orderId === p.orderId ? [e] : []));
  const trades = result.events.flatMap((e) => (e.type === "TRADE" ? [e] : []));
  const stp = rejects.find((e) => e.reason === "STP cancel taker");
  const comment = stp === undefined ? undefined : `STP:${String(stp.blockingOrderId || "")}`;
  if (rejects.length > 0 && trades.length === 0) {
    const reasons = rejects
      .map((e) => e.reason)
      .filter(Boolean)
      .join(", ");
    return ok({
      pass: cancelSame(pass, p.offer, comment ?? `post-only-reject:${reasons || "unknown"}`),
      value: result.state,
    });
  }
  return chain(withUsdReference(pass, p, result.state), (book) => {
    const s: Settling = { pass, p, book, comment };
    const plans = traverse(aggregateFills(trades), ([orderId, fill]) => planFill(s, orderId, fill));
    return map(plans, (ps) => ({
      pass: ps.reduce((queued, plan) => queueSame(queued, plan.accountId, plan.data), pass),
      value: book,
    }));
  });
};
/** og commitSameCommandResult: a fee-authority refusal cancels the taker instead; anything else halts the pair. */
const commitSame = (pass: Pass, p: Prepared, result: BookStep): Result<Pass, EntityError> => {
  const r = commandEvents(pass, p, result);
  if (!r.ok) {
    return r.error._tag === "auth"
      ? ok(cancelSame(pass, p.offer, "fee-authorization-exceeded"))
      : pairFailure(p, r.error.message);
  }
  const { pass: settled, value: book } = r.value;
  const dims = mapSet(settled.dims, p.bookKey, { baseTokenDecimals: p.bd, quoteTokenDecimals: p.qd });
  return ok(publishBook({ ...settled, dims }, p.bookKey, book));
};


// -- draining a crossed same-j book

/** og prepareCrossedRestingTaker: the younger crossed row must still be its committed offer, unchanged. */
const crossedTaker = (
  pass: Pass,
  trigger: Prepared,
  takerOrderId: string,
  minTradeSize: bigint,
): Result<Passed<Prepared>, EntityError> => {
  const mismatch = `ORDERBOOK_CACHE_MISMATCH: pair=${trigger.bookKey} order=${takerOrderId}`;
  return chain(liveMeta(pass.hub, takerOrderId), (live) => {
    if (live === null)
      return invariant(`ORDERBOOK_SAME_SNAPSHOT_MISSING: pair=${trigger.bookKey} order=${takerOrderId}`);
    return chain(readySame(pass, live, minTradeSize), ({ pass: ready, value: p }) =>
      p === null
        ? invariant(mismatch)
        : chain(keepResting(ready, p), (kept) =>
            kept.value ? ok({ pass: kept.pass, value: p }) : invariant(mismatch),
          ),
    );
  });
};
type Drain = { readonly pass: Pass; readonly current: Prepared; readonly done: boolean };
/** One resume of the crossed book: the younger top takes, and the result commits like any command. */
const drainStep =
  (seed: Prepared, minTradeSize: bigint, limit: number) =>
  (d: Drain, resumedCount: number): Result<Drain, EntityError> => {
    if (d.done) return ok(d);
    return chain(resumeSame(d.pass, d.current), (resumed): Result<Drain, EntityError> => {
      if (resumed === null) return ok({ ...d, done: true });
      if (resumedCount >= limit)
        return invariant(`ORDERBOOK_SAME_DRAIN_NON_TERMINATING: pair=${seed.bookKey} limit=${limit}`);
      return chain(crossedTaker(d.pass, d.current, resumed.takerOrderId, minTradeSize), (taker) =>
        chain(commitSame(taker.pass, taker.value, resumed), (committed) => {
          const next = committed.cache.get(seed.bookKey);
          if (next === undefined)
            return invariant(`ORDERBOOK_CACHE_MISMATCH: pair=${seed.bookKey} missing-after-resume`);
          return ok({ pass: committed, current: { ...d.current, book: next }, done: false });
        }),
      );
    });
  };
/**
 * og drainCrossedSameBook: settle crossed resting rows until the book no longer crosses, bounded by its order count.
 */
const drainSame = (pass: Pass, seed: Prepared, minTradeSize: bigint): Result<Pass, EntityError> => {
  const limit = seed.book.orders.size;
  const start: Drain = { pass, current: seed, done: false };
  return map(foldResult(Array(limit + 1).keys(), start, drainStep(seed, minTradeSize, limit)), (d) => d.pass);
};
type SeedSearch = { readonly pass: Pass; readonly found: Prepared | null };
/** A resting row seeds the drain when it is eligible, live, and still exactly its committed offer. */
const trySeed =
  (pairId: string, minTradeSize: bigint) =>
  (s: SeedSearch, order: BookOrder): Result<SeedSearch, EntityError> => {
    if (s.found !== null) return ok(s);
    return chain(classifyMaker(s.pass, pairId, order), (disposition) =>
      disposition !== "eligible"
        ? ok(s)
        : chain(liveMeta(s.pass.hub, order.orderId), (live) =>
            live === null
              ? ok(s)
              : chain(readySame(s.pass, live, minTradeSize), ({ pass, value: p }) =>
                  p === null
                    ? ok({ pass, found: null })
                    : map(keepResting(pass, p), (kept) => ({ pass: kept.pass, found: kept.value ? p : null })),
                ),
          ),
    );
  };
/** og findSamePairResumeSeed: the first eligible resting row, by sequence, that is still its committed offer. */
const resumeSeed = (pass: Pass, pairId: string, minTradeSize: bigint): Result<SeedSearch, EntityError> => {
  const book = pass.cache.get(pairId) ?? pass.hub.ext.books.get(pairId);
  const start: SeedSearch = { pass, found: null };
  return book === undefined ? ok(start) : foldResult(bookOrders(book), start, trySeed(pairId, minTradeSize));
};
/** og processSameOrderbookOffer: an identical resting row drains its crossed book; a new one is placed and settled. */
const processSameOffer = (pass: Pass, o: BookOffer, minTradeSize: bigint): Result<Pass, EntityError> =>
  chain(readySame(pass, o, minTradeSize), ({ pass: ready, value: p }) => {
    if (p === null) return ok(ready);
    return chain(keepResting(ready, p), ({ pass: kept, value: resting }) => {
      if (resting) return drainSame(kept, p, minTradeSize);
      return chain(placeSame(kept, p), ({ pass: placed, value: step }) =>
        step === null ? ok(placed) : commitSame(placed, p, step));
    });
  });
/** Resume each touched same-j pair whose book may still cross, in pair order. */
const resumePair = (minTradeSize: bigint) => (pass: Pass, pairId: string): Result<Pass, EntityError> =>
  chain(resumeSeed(pass, pairId, minTradeSize), ({ pass: seeded, found }) =>
    found === null ? ok(seeded) : drainSame(seeded, found, minTradeSize));
const byCreation = (l: BookOfferInput, r: BookOfferInput): number =>
  l.createdHeight - r.createdHeight || asc(l.accountId, r.accountId) || asc(l.offerId, r.offerId);
/**
 * og processOrderbookSwaps (same-j pass): offers by (createdHeight, accountId, offerId), then each touched pair's
 * crossed resting rows in pair order. The committed offers come from Account outputs (og accountOutputVerified), so no
 * second committed-state check runs here.
 */
export const processOrderbookSwaps = (
  hub: Hub,
  offers: readonly BookOfferInput[],
  resumePairIds: readonly string[] = [],
): Result<BookMatch, EntityError> => {
  const minTradeSize = hub.ext.hubProfile.minTradeSize;
  const sorted = offers.toSorted(byCreation);
  const crossOffers = sorted.flatMap((o) =>
    o.crossJurisdiction === undefined ? [] : [{ ...o, crossJurisdiction: o.crossJurisdiction }],
  );
  const sameOffers = sorted.filter((o) => o.crossJurisdiction === undefined);
  const resumed = [...new Set(resumePairIds)].toSorted().filter((pairId) => !pairId.startsWith("cross:"));
  // og runs the cross-j pass first, on the same hot book cache
  return chain(processCrossOffers(newPass(hub), crossOffers), (cross) => {
    const matched = foldResult(sameOffers, cross.pass, (pass, o) => processSameOffer(pass, o, minTradeSize));
    return map(
      chain(matched, (pass) => foldResult(resumed, pass, resumePair(minTradeSize))),
      (pass) => ({
        accountTxs: pass.accountTxs,
        books: pass.updates,
        pairDimensions: pass.dims,
        crossFills: cross.value,
      }),
    );
  });
};


// -- what enters the book, and what leaves it on a committed cancel

export type BookOfferInput = BookOffer & { readonly crossJurisdiction?: CrossRoute | undefined };
/**
 * og admitOrderbookOfferForMatching: a hub's own maker offer is never listed in its own book; an inactive Account's
 * offer is skipped.
 */
const isAdmitted = (hub: Hub, self: string, o: BookOfferInput): Result<boolean, EntityError> => {
  const route = o.crossJurisdiction;
  // og collectOffersForMatching: a cross-j order is listed only by its canonical book owner, then
  // admitOrderbookOfferForMatching's cross branch
  if (route !== undefined) {
    return crossBookOwnerRef(route) === self
      ? admitCrossForMatching(hub, { ...o, crossJurisdiction: route })
      : ok(false);
  }
  if (makerOf(o) === self) return ok(false);
  const account = hub.accounts.get(o.accountId.toLowerCase());
  if (account === undefined)
    return invariant(`ORDERBOOK_ACCOUNT_OUTPUT_ACCOUNT_MISSING: account=${o.accountId} offer=${o.offerId}`);
  return ok(account.active);
};
/**
 * og collectOffersForMatching + admitOrderbookOfferForMatching: each committed offer once, keyed by the counterparty
 * Account; a missing Account halts. A cross-j offer is matched only by its canonical book owner and only once its
 * admission is live (admitCrossForMatching).
 */
export const offersForMatching = (
  hub: Hub,
  created: readonly SwapOfferEvent[],
): Result<readonly BookOfferInput[], EntityError> => {
  const self = hub.id.toLowerCase();
  const enrich = (e: SwapOfferEvent): Result<BookOfferInput, EntityError> => {
    const counterparty = e.fromEntity.toLowerCase() === self ? e.toEntity.toLowerCase() : e.fromEntity.toLowerCase();
    return map(normalizeOffer(e, counterparty), (o) =>
      e.crossJurisdiction === undefined ? o : { ...o, crossJurisdiction: e.crossJurisdiction },
    );
  };
  return chain(traverse(created, enrich), (enriched) => {
    const unique = firstBy(enriched, (o) => swapKeyOf(o.accountId, o.offerId));
    return map(
      traverse(unique, (o) => isAdmitted(hub, self, o)),
      (admits) => unique.filter((_, i) => admits[i]),
    );
  });
};
/**
 * og getOrderbookPairsForOrder over the derived order-pair index: every pair whose book holds the row, in pair order.
 */
const pairsHolding = (books: ReadonlyMap<string, Book>, orderId: string): readonly string[] =>
  [...books].filter(([, b]) => b.orders.has(orderId)).map(([pairId]) => pairId).toSorted();
type CancelSweep = { readonly books: ReadonlyMap<string, Book>; readonly touched: ReadonlySet<string> };
/** One committed removal: the row leaves the one book that holds it. */
const takeOffBook = (s: CancelSweep, { accountId, offerId }: SwapRef): Result<CancelSweep, EntityError> => {
  const orderId = swapKeyOf(accountId, offerId);
  const pairs = pairsHolding(s.books, orderId);
  if (pairs.length > 1) return invariant(`ORDERBOOK_DUPLICATE_BOOK_ORDER: order=${orderId} matches=${pairs.length}`);
  const pairId = pairs[0];
  const book = pairId === undefined ? undefined : s.books.get(pairId);
  const order = book?.orders.get(orderId);
  if (pairId === undefined || book === undefined || order === undefined) return ok(s);
  return map(cancelRow(book, order), (next) => ({
    books: mapSet(s.books, pairId, next),
    touched: withMember(s.touched, pairId),
  }));
};
/**
 * og applyCommittedSwapCancelsToOrderbook: a committed offer removal takes its row off the book; returns the touched
 * pairs, sorted.
 */
export const applyCommittedSwapCancels = (
  ext: OrderbookExt,
  cancels: readonly SwapRef[],
): Result<{ readonly ext: OrderbookExt; readonly resumePairIds: readonly string[] }, EntityError> => {
  const start: CancelSweep = { books: ext.books, touched: new Set() };
  return map(foldResult(cancels, start, takeOffBook), ({ books, touched }) => ({
    ext: books === ext.books ? ext : { ...ext, books },
    resumePairIds: [...touched].toSorted(),
  }));
};
type CancelRun = {
  readonly queue: ResolveQueue;
  readonly working: ReadonlyMap<string, Book>;
  readonly crossFills: readonly CrossFillInstruction[];
};
/**
 * A requested cancel: the row leaves its book; a same-j offer queues its zero-fill resolve, a cross-j one a cancel
 * instruction.
 */
const cancelRequested =
  (hub: Hub) =>
  (run: CancelRun, { offerId, accountId }: SwapRef): Result<CancelRun, EntityError> => {
    const offer = hub.accounts.get(accountId)?.offers.get(offerId);
    if (offer === undefined) return ok(run);
    const orderId = swapKeyOf(accountId, offerId);
    const matching = pairsHolding(hub.ext.books, orderId).flatMap((pairId) => {
      const book = run.working.get(pairId) ?? hub.ext.books.get(pairId);
      const order = book?.orders.get(orderId);
      return book === undefined || order === undefined ? [] : [{ pairId, book, order }];
    });
    if (matching.length > 1)
      return invariant(`ORDERBOOK_DUPLICATE_BOOK_ORDER: order=${orderId} matches=${matching.length}`);
    const removed = foldResult(matching, run.working, (working, { pairId, book, order }) =>
      map(cancelRow(book, order), (next) => mapSet(working, pairId, next)),
    );
    return chain(removed, (working): Result<CancelRun, EntityError> => {
      const route = offer.crossJurisdiction;
      if (route === undefined) {
        return ok({
          ...run,
          working,
          queue: queueUniqueResolve(run.queue, accountId, cancelTerms(offerId, "cancel_request")),
        });
      }
      const admitted = hub.crossAdmissions?.get(bookAdmissionKey(accountId, offerId))?.route ?? route;
      return map(crossCancelInstruction(accountId, offerId, orderId, admitted), (i) => ({
        ...run,
        working,
        crossFills: [...run.crossFills, i],
      }));
    });
  };
/**
 * og processOrderbookCancels: take the row off its book; a same-j offer queues its zero-fill cancel resolve, a cross-j
 * one a hub-internal cancel instruction at its admitted progress.
 */
export const processOrderbookCancels = (
  hub: Hub,
  cancels: readonly SwapRef[],
): Result<
  {
    readonly accountTxs: readonly BookTx[];
    readonly books: ReadonlyMap<string, Book>;
    readonly crossFills: readonly CrossFillInstruction[];
  },
  EntityError
> => {
  const start: CancelRun = { queue: { hub, queued: new Set(), accountTxs: [] }, working: new Map(), crossFills: [] };
  return map(foldResult(cancels, start, cancelRequested(hub)), (run) => ({
    accountTxs: run.queue.accountTxs,
    books: run.working,
    crossFills: run.crossFills,
  }));
};

// ---- cross-j hub book: og extensions/cross-j/orderbook.ts (admissions, USD caps, market offer, fill and cancel
// instructions), orderbook/cross-j/*, entity/tx/handlers/account/orderbook/cross/* and cancels.ts (cross branch). og
// throws from deep inside; here each halt is an `entity_invariant` with og's message. ----
export type BookAdmissionStatus = "pending" | "admitted" | "resolving" | "closed";
/** og CrossJurisdictionBookAdmission: the book owner's record of one admitted route, keyed by source user and order. */
export type BookAdmission = {
  readonly orderId: string;
  readonly routeHash: string;
  readonly sourceEntityId: string;
  readonly bookOwnerEntityId: string;
  readonly status: BookAdmissionStatus;
  readonly route: CrossRoute;
  readonly admittedAt?: number | undefined;
  readonly resolvingAt?: number | undefined;
  readonly closedAt?: number | undefined;
  readonly closeReason?: string | undefined;
  readonly updatedAt: number;
};
export type BookAdmissions = ReadonlyMap<string, BookAdmission>;
/** og crossJurisdictionBookAdmissionKeyFor (also the book's namespaced order id for a cross-j row). */
export const bookAdmissionKey = (sourceEntityId: string, orderId: string): string =>
  `${entityRef(sourceEntityId)}:${String(orderId || "")}`;
/** og crossJurisdictionBookOwnerRef. */
export const crossBookOwnerRef = (r: CrossRoute): string =>
  entityRef(r.bookOwnerEntityId || r.source.counterpartyEntityId || r.hubEntityId || "");
/** og withCanonicalCrossJurisdictionRouteHash where a throw is a halt. */
const canonRoute = (r: CrossRoute): Result<CrossRoute, EntityError> => {
  const c = canonicalCrossRoute(r);
  return c.ok ? ok(c.value) : invariant(crossRouteErrorText(r, c.error.reason));
};
const cloneRouteE = (r: CrossRoute): Result<CrossRoute, EntityError> => fatalCross(cloneCrossRoute(r));
/** og cloneCrossJurisdictionBookAdmission: the collection forks a leaf through it before any in-place write. */
export const cloneBookAdmission = (a: BookAdmission): Result<BookAdmission, EntityError> =>
  map(cloneRouteE(a.route), (route): BookAdmission => ({
    orderId: String(a.orderId || ""),
    routeHash: String(a.routeHash || ""),
    sourceEntityId: String(a.sourceEntityId || ""),
    bookOwnerEntityId: String(a.bookOwnerEntityId || ""),
    status: a.status,
    route,
    updatedAt: Number(a.updatedAt || 0),
    ...opt("admittedAt", optNum(a.admittedAt)),
    ...opt("resolvingAt", optNum(a.resolvingAt)),
    ...opt("closedAt", optNum(a.closedAt)),
    ...opt("closeReason", optText(a.closeReason)),
  }));
/** og getEntityCollectionValueForWrite + an in-place edit: a missing key is a no-op. */
const writeAdmission = (
  admissions: BookAdmissions | undefined,
  key: string,
  edit: (a: BookAdmission) => BookAdmission | undefined,
): Result<BookAdmissions | undefined, EntityError> => {
  const current = admissions?.get(key);
  if (admissions === undefined || current === undefined) return ok(admissions);
  return map(cloneBookAdmission(current), (forked) => {
    const next = edit(forked);
    return next === undefined ? admissions : mapSet(admissions, key, next);
  });
};
/**
 * og mergeAdmissionRoute: the later route wins field by field, but never lowers the status or drops a pull or the hash.
 */
const mergeAdmissionRoute = (existing: CrossRoute | undefined, next: CrossRoute): Result<CrossRoute, EntityError> =>
  chain(cloneRouteE(next), (n) => existing === undefined ? ok(n) : map(cloneRouteE(existing), (e): CrossRoute => {
    const merged: CrossRoute = { ...e, ...n };
    const kept = <K extends "sourcePull" | "targetPull" | "routeHash">(k: K) =>
      opt(k, e[k] && !merged[k] ? e[k] : undefined);
    return {
      ...merged,
      ...opt("status", compareCrossStatus(e.status, n.status) < 0 ? e.status : undefined),
      ...kept("sourcePull"),
      ...kept("targetPull"),
      ...kept("routeHash"),
    };
  }));
/**
 * og mergeCrossJurisdictionBookAdmission: a new admission starts `pending`; an existing one keeps its status and takes
 * the merged route.
 */
export const mergeBookAdmission = (
  admissions: BookAdmissions | undefined,
  route: CrossRoute,
  now: number,
): Result<{ readonly admissions: BookAdmissions; readonly admission: BookAdmission }, EntityError> =>
  chain(canonRoute(route), (c) => {
    const key = bookAdmissionKey(c.source.entityId, c.orderId);
    const existing = admissions?.get(key);
    return map(mergeAdmissionRoute(existing?.route, c), (merged) => {
      const admission: BookAdmission = existing !== undefined
        ? { ...existing, route: merged, updatedAt: now }
        : {
          orderId: c.orderId,
          routeHash: c.routeHash || "",
          sourceEntityId: entityRef(c.source.entityId),
          bookOwnerEntityId: crossBookOwnerRef(c),
          status: "pending",
          route: merged,
          updatedAt: now,
        };
      return { admissions: mapSet(admissions ?? new Map<string, BookAdmission>(), key, admission), admission };
    });
  });
/** og markCrossJurisdictionBookAdmissionResolving: a live (not closed) admission starts resolving. */
export const markAdmissionResolving = (
  admissions: BookAdmissions | undefined,
  route: CrossRoute,
  now: number,
): Result<BookAdmissions | undefined, EntityError> =>
  chain(canonRoute(route), (c) =>
    writeAdmission(admissions, bookAdmissionKey(c.source.entityId, c.orderId), (a) =>
      a.status === "closed" ? undefined : { ...a, status: "resolving", resolvingAt: now, updatedAt: now }));
/** og markCrossJurisdictionBookAdmissionClosed. */
export const markAdmissionClosed = (
  admissions: BookAdmissions | undefined,
  sourceEntityId: string,
  orderId: string,
  now: number,
  reason: string,
): Result<BookAdmissions | undefined, EntityError> =>
  writeAdmission(admissions, bookAdmissionKey(sourceEntityId, orderId), (a) => ({
    ...a,
    status: "closed",
    closedAt: now,
    closeReason: reason,
    updatedAt: now,
  }));
/**
 * og getCrossJurisdictionBookAdmissionError: owner, both pulls, expiry, then the admitted record for exactly this
 * route. USD risk is not rechecked here.
 */
export const bookAdmissionError = (
  entityId: string,
  admissions: BookAdmissions | undefined,
  route: CrossRoute,
  now: number,
): Result<string | null, EntityError> => map(canonRoute(route), (c) => {
  const current = entityRef(entityId);
  const owner = crossBookOwnerRef(c);
  if (owner !== current) return `CROSS_J_ORDER_WRONG_BOOK_OWNER: order=${c.orderId} owner=${owner} current=${current}`;
  if (!c.sourcePull || !c.targetPull) return `CROSS_J_ORDER_LOCK_REF_MISSING: order=${c.orderId}`;
  if (isCrossExpired(c, now)) return `CROSS_J_ORDER_ROUTE_EXPIRED: order=${c.orderId}`;
  const a = admissions?.get(bookAdmissionKey(c.source.entityId, c.orderId));
  if (a === undefined) return `CROSS_J_BOOK_ADMISSION_PENDING: order=${c.orderId} leg=both`;
  if (a.status === "closed") return `CROSS_J_BOOK_ADMISSION_CLOSED: order=${c.orderId} reason=${a.closeReason || ""}`;
  if (a.status === "resolving") return `CROSS_J_BOOK_ADMISSION_RESOLVING: order=${c.orderId}`;
  const exact = a.orderId === c.orderId
    && a.routeHash.toLowerCase() === (c.routeHash || "").toLowerCase()
    && entityRef(a.bookOwnerEntityId) === owner;
  return exact ? null : `CROSS_J_BOOK_ADMISSION_ROUTE_MISMATCH: order=${c.orderId}`;
});
export type BookAdmissionFailure = { readonly kind: "pending" | "risk_reject" | "invalid"; readonly message: string };
const failureKind = (message: string): BookAdmissionFailure["kind"] => {
  switch (true) {
    case message.startsWith("CROSS_J_BOOK_ADMISSION_PENDING:"):
      return "pending";
    case message.startsWith("CROSS_J_BOOK_USD_CAP_EXCEEDED:"):
      return "risk_reject";
    default:
      return "invalid";
  }
};
/** og getTypedCrossJurisdictionBookAdmissionFailure. */
export const bookAdmissionFailure = (
  entityId: string,
  admissions: BookAdmissions | undefined,
  route: CrossRoute,
  now: number,
): Result<BookAdmissionFailure | null, EntityError> =>
  map(bookAdmissionError(entityId, admissions, route, now), (message) =>
    message === null ? null : { kind: failureKind(message), message });


// -- USD risk: what one leg is worth at the hub's own accepted reference price

/**
 * og internalUsdPrice: a reference stable at par; any other token at the hub's last accepted USD authority ask against
 * its reference token, when one exists.
 */
const internalUsdPrice = (ext: OrderbookExt | undefined, tokenId: number): Result<bigint | null, EntityError> => {
  if (REFERENCE_STABLES.has(tokenId)) return ok(PRICE_SCALE);
  if (ext === undefined) return ok(null);
  const reference = Number(ext.hubProfile.referenceTokenId);
  if (!REFERENCE_STABLES.has(reference)) return invariant(`CROSS_J_BOOK_USD_REFERENCE_INVALID:token=${reference}`);
  const price = ext.books.get(canonicalPairOf(tokenId, reference).pairId)?.lastAcceptedUsdAskPriceTicks ?? 0n;
  return ok(price > 0n ? price : null);
};
const usdMicrosAt = (tokenId: number, amount: bigint, price: bigint): Result<bigint, EntityError> =>
  amount <= 0n
    ? invariant(`CROSS_J_BOOK_USD_AMOUNT_INVALID:token=${tokenId}`)
    : map(tokenDecimals(tokenId), (d) => ceilDiv(amount * price * 1_000_000n, 10n ** d * PRICE_SCALE));
/** og crossJurisdictionLegUsdMicros. */
export const crossLegUsdMicros = (
  ext: OrderbookExt | undefined,
  tokenId: number,
  amount: bigint,
): Result<bigint, EntityError> =>
  chain(internalUsdPrice(ext, tokenId), (price) =>
    price === null ? invariant(`CROSS_J_USD_PRICE_UNAVAILABLE:token=${tokenId}`) : usdMicrosAt(tokenId, amount, price),
  );
type LegRole = "source" | "target";
const LEG_ROLES: readonly LegRole[] = ["source", "target"];
/**
 * og getCrossJurisdictionLegUsdCapError: only the leg this hub bears, and only once it has a price for it (unpriced is
 * permissionless).
 */
export const crossLegUsdCapError = (
  ext: OrderbookExt | undefined,
  route: CrossRoute,
  role: LegRole,
): Result<string | null, EntityError> => {
  const leg = route[role];
  const tokenId = Number(leg.tokenId);
  const cap = CROSS_J_BOOK_MAX_USD_MICROS;
  return chain(internalUsdPrice(ext, tokenId), (price) =>
    price === null
      ? ok(null)
      : map(usdMicrosAt(tokenId, BigInt(leg.amount), price), (usdMicros) =>
          usdMicros > cap
            ? `CROSS_J_BOOK_USD_CAP_EXCEEDED:order=${route.orderId}:leg=${role}:usdMicros=${usdMicros}:cap=${cap}`
            : null,
        ),
  );
};
/**
 * og getCrossJurisdictionLocalUsdCapError: exactly one local hub leg (by entity and stack), else a validator-leg error.
 */
export const crossLocalUsdCapError = (
  v: { readonly id: string; readonly jurisdiction: Domain; readonly ext?: OrderbookExt | undefined },
  route: CrossRoute,
): Result<string | null, EntityError> => {
  const entity = entityRef(v.id);
  const stack = stackIdOf(v.jurisdiction).toLowerCase();
  const hubOf = { source: route.source.counterpartyEntityId, target: route.target.entityId };
  const bears = (role: LegRole): boolean =>
    entity === entityRef(hubOf[role]) && stack === String(route[role].jurisdiction).toLowerCase();
  const roles = LEG_ROLES.filter(bears);
  const role = roles[0];
  const at = `order=${route.orderId}:entity=${entity}:stack=${stack}`;
  if (roles.length === 1 && role !== undefined) return crossLegUsdCapError(v.ext, route, role);
  return ok(`CROSS_J_BOOK_USD_VALIDATOR_LEG_INVALID:${at}:matches=${roles.length}`);
};


// -- a cross-j route as one book order, and its fills as hub-internal progress

/** og crossJurisdictionBookQtyLots: the floor of the base remainder in book lots. */
export const crossBookQtyLots = (baseTokenId: number, baseAmount: bigint): Result<bigint, EntityError> =>
  baseAmount <= 0n ? ok(0n) : map(tokenDecimals(baseTokenId), (d) => baseAmount / lotScale(Number(d)));
export type CrossRemaining = {
  readonly sourceTotal: bigint;
  readonly targetTotal: bigint;
  readonly filledSourceAmount: bigint;
  readonly filledTargetAmount: bigint;
  readonly sourceRemaining: bigint;
  readonly targetRemaining: bigint;
  readonly fillRatio: number;
};
/** og getCrossJurisdictionRouteRemainingAmounts. */
export const crossRemaining = (r: CrossRoute): Result<CrossRemaining, EntityError> => {
  const sourceTotal = BigInt(r.source.amount);
  const targetTotal = BigInt(r.target.amount);
  if (sourceTotal <= 0n || targetTotal <= 0n) return invariant(`CROSS_J_ROUTE_AMOUNT_INVALID: order=${r.orderId}`);
  return chain(fatalCross(crossFillAmounts(r)), (c): Result<CrossRemaining, EntityError> => {
    const { filledSourceAmount, filledTargetAmount } = c;
    const valid =
      filledSourceAmount >= 0n &&
      filledTargetAmount >= 0n &&
      filledSourceAmount <= sourceTotal &&
      filledTargetAmount <= targetTotal;
    const progress = `source=${filledSourceAmount}/${sourceTotal} target=${filledTargetAmount}/${targetTotal}`;
    if (!valid) return invariant(`CROSS_J_ROUTE_FILL_INVALID: order=${r.orderId} ${progress}`);
    return ok({
      sourceTotal,
      targetTotal,
      filledSourceAmount,
      filledTargetAmount,
      sourceRemaining: sourceTotal - filledSourceAmount,
      targetRemaining: targetTotal - filledTargetAmount,
      fillRatio: c.fillRatio,
    });
  });
};
/** og NormalizedOrderbookOffer carrying its cross-j route. */
export type CrossBookOffer = BookOffer & { readonly crossJurisdiction: CrossRoute };
/** og CrossMarketOffer: the route's committed remainder as one book order on the canonical cross venue. */
export type CrossMarketOffer = {
  readonly offer: CrossBookOffer;
  readonly route: CrossRoute;
  readonly pairId: string;
  readonly side: BookSide;
  readonly baseTokenId: number;
  readonly quoteTokenId: number;
  readonly baseAmount: bigint;
  readonly quoteAmount: bigint;
  readonly priceTicks: bigint;
  readonly makerId: string;
};
/**
 * og buildCrossJurisdictionMarketOffer: only this book owner's working route; side, amounts and price come from the
 * route remainder, never from the Account offer.
 */
export const crossMarketOffer = (
  offer: CrossBookOffer,
  hubEntityId: string,
): Result<CrossMarketOffer | null, EntityError> => {
  const route = offer.crossJurisdiction;
  const owner = entityRef(route.bookOwnerEntityId || route.source.counterpartyEntityId || route.hubEntityId);
  if (owner && owner !== entityRef(hubEntityId)) return ok(null);
  if (route.status !== "resting" && route.status !== "partially_filled") return ok(null);
  return chain(fatalCross(crossMarket(route)), (m) => {
    if (!m.sourceKey || !m.targetKey || m.sourceKey === m.targetKey) return ok(null);
    const side: BookSide = m.sourceIsBase ? 1 : 0;
    const [baseLeg, quoteLeg] = m.sourceIsBase ? [route.source, route.target] : [route.target, route.source];
    const baseTokenId = Number(baseLeg.tokenId);
    const quoteTokenId = Number(quoteLeg.tokenId);
    return chain(crossRemaining(route), (rem) => {
      const [baseAmount, quoteAmount] = m.sourceIsBase
        ? [rem.sourceRemaining, rem.targetRemaining]
        : [rem.targetRemaining, rem.sourceRemaining];
      const decimals = all({ bd: tokenDecimals(baseTokenId), qd: tokenDecimals(quoteTokenId) });
      return map(decimals, ({ bd, qd }): CrossMarketOffer | null => {
        const priceTicks = priceTicksOf({ side, bd: Number(bd), qd: Number(qd) }, baseAmount, quoteAmount);
        if (baseAmount <= 0n || quoteAmount <= 0n || priceTicks <= 0n) return null;
        return {
          offer,
          route,
          pairId: m.venueId,
          side,
          baseTokenId,
          quoteTokenId,
          baseAmount,
          quoteAmount,
          priceTicks,
          makerId: makerOf(offer),
        };
      });
    });
  });
};
/**
 * og resolveCrossJurisdictionExecutionPriceTicks: one price-improvement lane, so a cross-j trade always executes at the
 * ask.
 */
export const crossExecutionPrice = (first: CrossMarketOffer, second: CrossMarketOffer): Result<bigint, EntityError> => {
  const samePair =
    first.pairId === second.pairId &&
    first.baseTokenId === second.baseTokenId &&
    first.quoteTokenId === second.quoteTokenId;
  if (!samePair) return invariant(`CROSS_J_TRADE_PAIR_MISMATCH:${first.pairId}:${second.pairId}`);
  if (first.side === second.side) return invariant(`CROSS_J_TRADE_SIDE_MISMATCH:${first.side}:${second.side}`);
  const [sell, buy] = first.side === 1 ? [first, second] : [second, first];
  const crossed = sell.priceTicks > 0n && buy.priceTicks > 0n && sell.priceTicks <= buy.priceTicks;
  return crossed
    ? ok(sell.priceTicks)
    : invariant(`CROSS_J_TRADE_PRICE_NOT_CROSSED:ask=${sell.priceTicks}:bid=${buy.priceTicks}`);
};
export type CrossBookFill = {
  readonly filledLots: bigint;
  readonly weightedCost: bigint;
  readonly cancelRemainder?: boolean | undefined;
};
type CrossExecution = { readonly executionSourceAmount: bigint; readonly executionTargetAmount: bigint };
/**
 * og crossJurisdictionExecutionAmounts: the executed book amounts of one aggregated fill in route (source/target)
 * terms.
 */
export const crossExecutionAmounts = (
  meta: CrossMarketOffer,
  fill: CrossBookFill,
): Result<CrossExecution | null, EntityError> => {
  if (fill.filledLots <= 0n || fill.weightedCost <= 0n) return ok(null);
  return map(all({ bd: tokenDecimals(meta.baseTokenId), qd: tokenDecimals(meta.quoteTokenId) }), ({ bd, qd }) => {
    const lot = lotScale(Number(bd));
    const base = fill.filledLots * lot;
    const quote = quoteAt(Number(bd), Number(qd), lot, fill.weightedCost);
    const [executionSourceAmount, executionTargetAmount] = meta.side === 1 ? [base, quote] : [quote, base];
    return executionSourceAmount <= 0n || executionTargetAmount <= 0n
      ? null
      : { executionSourceAmount, executionTargetAmount };
  });
};
/**
 * og CrossJurisdictionFillInstruction: hub-internal progress of one order, one uint16 ratio; the exact executed amounts
 * only feed conservation.
 */
export type CrossFillInstruction = SwapRef & CrossExecution & {
  readonly orderId: string;
  readonly route: CrossRoute;
  readonly fillSeq: number;
  readonly fillRatio: number;
  readonly cancelRemainder: boolean;
};
const currentFillSeq = (r: CrossRoute): number => Math.max(0, Math.floor(Number(r.fillSeq ?? 0) || 0));
/**
 * og buildCrossJurisdictionFillInstruction: the cumulative target-side ratio; a step that moves neither or only one
 * leg's claim is absorbed by the hub (null).
 */
export const crossFillInstruction = (
  accountId: string,
  offerId: string,
  orderId: string,
  meta: CrossMarketOffer,
  fill: CrossBookFill,
): Result<CrossFillInstruction | null, EntityError> =>
  chain(crossExecutionAmounts(meta, fill), (execution) =>
    execution === null
      ? ok(null)
      : map(fatalCross(crossFillAmounts(meta.route)), (c): CrossFillInstruction | null => {
          const { executionSourceAmount, executionTargetAmount } = execution;
          const overfills =
            c.filledSourceAmount + executionSourceAmount > c.sourceTotal ||
            c.filledTargetAmount + executionTargetAmount > c.targetTotal;
          if (overfills) return null;
          const fillRatio = fillRatioOf(exactFillRatio(c.targetTotal, c.filledTargetAmount + executionTargetAmount));
          if (fillRatio <= c.fillRatio) return null;
          const ratio = BigInt(fillRatio);
          const max = BigInt(MAX_FILL);
          const project = (total: bigint): bigint => (ratio >= max ? total : (total * ratio) / max);
          if (project(c.sourceTotal) <= c.filledSourceAmount || project(c.targetTotal) <= c.filledTargetAmount)
            return null;
          return {
            accountId,
            offerId,
            orderId,
            route: meta.route,
            fillSeq: currentFillSeq(meta.route) + 1,
            fillRatio,
            cancelRemainder: fill.cancelRemainder === true,
            executionSourceAmount,
            executionTargetAmount,
          };
        }),
  );
/**
 * og buildCrossJurisdictionCancelInstruction: a terminal cancel of the unfilled remainder at the committed progress.
 */
export const crossCancelInstruction = (
  accountId: string,
  offerId: string,
  orderId: string,
  route: CrossRoute,
): Result<CrossFillInstruction, EntityError> =>
  map(fatalCross(crossFillAmounts(route)), (c) => ({
    accountId,
    offerId,
    orderId,
    route,
    fillSeq: currentFillSeq(route),
    fillRatio: c.fillRatio,
    cancelRemainder: true,
    executionSourceAmount: 0n,
    executionTargetAmount: 0n,
  }));
/** og normalizeSwapOfferForOrderbook for a cross-j offer: the book view keeps the route. */
const normalizeCross = (o: RawOffer, accountId: string, route: CrossRoute): Result<CrossBookOffer, EntityError> =>
  map(normalizeOffer(o, accountId), (b) => ({ ...b, crossJurisdiction: route }));
/**
 * A remote user's admitted route as the offer it stands for: its remainder, source to target, with no Account behind
 * it.
 */
const remoteOffer = (offerId: string, route: CrossRoute): Result<RawOffer, EntityError> => {
  const facts = all({
    rem: crossRemaining(route),
    gd: tokenDecimals(Number(route.source.tokenId)),
    wd: tokenDecimals(Number(route.target.tokenId)),
  });
  return map(facts, ({ rem, gd, wd }) => ({
    offerId,
    makerIsLeft: true,
    fromEntity: route.source.entityId,
    toEntity: route.source.counterpartyEntityId,
    createdHeight: 0,
    giveTokenId: Number(route.source.tokenId),
    giveTokenDecimals: Number(gd),
    giveAmount: rem.sourceRemaining,
    wantTokenId: Number(route.target.tokenId),
    wantTokenDecimals: Number(wd),
    wantAmount: rem.targetRemaining,
    maxFee: 0n,
    minNetReceive: rem.targetRemaining,
    ...opt("priceTicks", route.priceTicks === undefined ? undefined : BigInt(route.priceTicks)),
  }));
};
/**
 * og buildCrossMarketOfferFromBookOrder: the Account offer at its progressed (admitted) route, else a remote admitted
 * route without a local Account.
 */
const crossMetaFromBookOrder = (hub: Hub, orderId: string): Result<CrossMarketOffer | null, EntityError> =>
  chain(parseOrderId(orderId, "ORDERBOOK_CROSS_J_MALFORMED_BOOK_ORDER"), ({ accountId, offerId }) => {
    const account = hub.accounts.get(accountId);
    const o = account?.offers.get(offerId);
    const admission = hub.crossAdmissions?.get(bookAdmissionKey(accountId, offerId));
    const market = (raw: RawOffer, route: CrossRoute) =>
      chain(normalizeCross(raw, accountId, route), (n) => crossMarketOffer(n, hub.id));
    if (account !== undefined && o?.crossJurisdiction !== undefined) {
      return market(storedOffer(account, offerId, o), admission?.route ?? o.crossJurisdiction);
    }
    if (admission === undefined || admission.status !== "admitted") return ok(null);
    return chain(remoteOffer(offerId, admission.route), (raw) => market(raw, admission.route));
  });


// -- the cross-j pass: speculative placement on working books, fills aggregated into hub-internal progress

type CrossFillAgg = { readonly filledLots: bigint; readonly weightedCost: bigint; readonly cancelRemainder: boolean };
/**
 * og CrossOrderbookPass: shares the same-j pass's hot book cache, touched books and queued resolves; working books stay
 * speculative until committed.
 */
type CrossPass = {
  readonly pass: Pass;
  readonly meta: ReadonlyMap<string, CrossMarketOffer>;
  readonly fills: ReadonlyMap<string, CrossFillAgg>;
  readonly suspended: ReadonlySet<string>;
  readonly working: ReadonlyMap<string, Book>;
  readonly speculative: ReadonlySet<string>;
  readonly aliased: ReadonlySet<string>;
  readonly out: readonly CrossFillInstruction[];
};
type CrossPassed<T> = { readonly cp: CrossPass; readonly value: T };
/** What judging a cross-j maker taught the pass: the row's market offer, remembered under its order id. */
type LearnedMeta = readonly [orderId: string, meta: CrossMarketOffer];
const learnMeta = (cp: CrossPass, learned: readonly LearnedMeta[]): CrossPass => ({
  ...cp,
  meta: mapSetAll(cp.meta, learned),
});
/** og rejectInvalidCrossOffer in live mode: every invalid cross-j offer halts the frame. */
const liveReject = (accountId: string, offerId: string, reason: string): Result<never, EntityError> =>
  invariant(`ORDERBOOK_LIVE_PROJECTION_REJECT: account=${accountId} offer=${offerId} reason=${reason}`);
/** og getCrossMarketOffer: the admitted route (or the hub's route mirror) carries the progressed remainder. */
const crossMetaOf = (cp: CrossPass, o: CrossBookOffer): Result<CrossPassed<CrossMarketOffer | null>, EntityError> => {
  const key = swapKeyOf(o.accountId, o.offerId);
  const cached = cp.meta.get(key);
  const hub = cp.pass.hub;
  if (cached !== undefined) return ok({ cp, value: cached });
  const progressed = hub.crossAdmissions?.get(bookAdmissionKey(o.accountId, o.offerId))?.route
    ?? hub.crossSwaps?.get(o.offerId)
    ?? o.crossJurisdiction;
  const offer = progressed === o.crossJurisdiction ? o : { ...o, crossJurisdiction: progressed };
  return map(crossMarketOffer(offer, hub.id), (m) => ({ cp: m === null ? cp : learnMeta(cp, [[key, m]]), value: m }));
};
const crossMeta = (cp: CrossPass, orderId: string): Result<CrossMarketOffer | null, EntityError> => {
  const m = cp.meta.get(orderId);
  return m !== undefined ? ok(m) : crossMetaFromBookOrder(cp.pass.hub, orderId);
};
/** og committedCrossRouteStatus. */
const committedCrossStatus = (hub: Hub, accountId: string, offerId: string): string | undefined => {
  const admission = hub.crossAdmissions?.get(bookAdmissionKey(accountId, offerId));
  if (admission !== undefined && admission.status !== "admitted") return `admission:${admission.status}`;
  const mirror = hub.crossSwaps?.get(offerId);
  if (mirror?.status) return mirror.status;
  return hub.accounts.get(accountId)?.offers.get(offerId)?.crossJurisdiction?.status ?? admission?.route.status;
};
/** The resting cross-j row must be exactly its route remainder. */
const crossRowMatches = (pairId: string, order: BookOrder, meta: CrossMarketOffer): Result<void, EntityError> =>
  chain(crossBookQtyLots(meta.baseTokenId, meta.baseAmount), (qty) => {
    const at = `ORDERBOOK_CROSS_J_CACHE_MISMATCH: pair=${pairId} order=${order.orderId}`;
    const sized: readonly Mismatch[] = [["Qty", order.qtyLots, qty], ["Price", order.priceTicks, meta.priceTicks]];
    const placed: readonly Mismatch[] = [["Pair", pairId, meta.pairId], ["Owner", order.ownerId, meta.makerId]];
    if (meta.pairId !== pairId || order.priceTicks !== meta.priceTicks || order.ownerId !== meta.makerId) {
      return invariant(`${at} ${mismatchText([...placed, ...sized])}`);
    }
    return order.qtyLots === qty ? ok(undefined) : invariant(`${at} ${mismatchText(sized)}`);
  });
/**
 * og classifyCrossBookMaker: a disputed local Account, a non-working or expired route cancels the row; a matched row is
 * suspended; the row must equal its route remainder. Once the row's market offer is known, og remembers it for the rest
 * of the pass.
 */
const classifyCrossMaker = (
  cp: CrossPass,
  pairId: string,
  order: BookOrder,
): Result<MakerVerdict<LearnedMeta>, EntityError> =>
  chain(parseOrderId(order.orderId, "ORDERBOOK_CROSS_J_MALFORMED_BOOK_ORDER"), ({ accountId, offerId }) => {
    const hub = cp.pass.hub;
    const account = hub.accounts.get(accountId);
    const status = committedCrossStatus(hub, accountId, offerId);
    if (account !== undefined && !account.active) return ok({ disposition: "cancel" });
    if (status && status !== "resting" && status !== "partially_filled") return ok({ disposition: "cancel" });
    return chain(crossMeta(cp, order.orderId), (meta): Result<MakerVerdict<LearnedMeta>, EntityError> => {
      const at = `pair=${pairId} order=${order.orderId} account=${accountId} offer=${offerId}`;
      if (meta === null) return invariant(`ORDERBOOK_CROSS_J_SNAPSHOT_MISSING: ${at}`);
      const learned: LearnedMeta = [order.orderId, meta];
      if (isCrossExpired(meta.route, Number(hub.timestamp ?? 0))) return ok({ disposition: "cancel", learned });
      if (cp.suspended.has(order.orderId)) return ok({ disposition: "suspended", learned });
      return map(crossRowMatches(pairId, order, meta), () => ({ disposition: "eligible", learned }));
    });
  });
type PreparedCross = {
  readonly raw: CrossBookOffer;
  readonly orderId: string;
  readonly meta: CrossMarketOffer;
  readonly qtyLots: bigint;
  readonly bd: number;
  readonly qd: number;
  readonly book: Book;
};
/**
 * og processCrossOrderbookOffer's book options: the pass's matched rows sit out, and a cross-j trade executes at the
 * ask.
 */
const crossBookOptions = (cp: CrossPass, p: PreparedCross): BookOptions<EntityError, LearnedMeta> => ({
  suspendedOrderIds: cp.suspended,
  makerVerdict: (maker) => classifyCrossMaker(cp, p.meta.pairId, maker),
  executionPriceTicksForMatch: (maker, taker, takerSide) => (takerSide === 1 ? taker : maker),
  executionQtyMultipleAtPrice: (price) => exactQuoteLots(p.bd, p.qd, price),
});
/** The route's remainder in book lots: dust, oversize and a quote-misaligned remainder are invalid. */
const crossLots = (
  raw: CrossBookOffer,
  meta: CrossMarketOffer,
): Result<Omit<PreparedCross, "orderId" | "book">, EntityError> => {
  const { accountId, offerId } = raw;
  return chain(crossBookQtyLots(meta.baseTokenId, meta.baseAmount), (qtyLots) => {
    const n = meta.offer;
    const [bd, qd] =
      meta.side === 1 ? [n.giveTokenDecimals, n.wantTokenDecimals] : [n.wantTokenDecimals, n.giveTokenDecimals];
    if (qtyLots <= 0n) return liveReject(accountId, offerId, `cross-dust-remainder:${meta.baseAmount}`);
    if (qtyLots > MAX_ORDERBOOK_QTY_LOTS) return liveReject(accountId, offerId, `invalid-cross-qty:${qtyLots}`);
    const multiple = exactQuoteLots(bd, qd, meta.priceTicks);
    if (qtyLots % multiple !== 0n)
      return liveReject(accountId, offerId, `cross-quote-lot-misaligned:${qtyLots}:${multiple}`);
    return ok({ raw, meta, qtyLots, bd, qd });
  });
};
/**
 * og prepareCrossOrderbookOffer: dust, size and exact-quote alignment; a resolving offer or an identical resting row is
 * skipped, a changed row halts.
 */
const prepareCross = (cp: CrossPass, raw: CrossBookOffer): Result<CrossPassed<PreparedCross | null>, EntityError> => {
  const { accountId, offerId } = raw;
  const orderId = swapKeyOf(accountId, offerId);
  return chain(crossMetaOf(cp, raw), ({ cp: known, value: meta }) => {
    if (meta === null) return liveReject(accountId, offerId, "invalid-cross-j-route");
    return chain(crossLots(raw, meta), (lots) => {
      const skip = ok({ cp: known, value: null });
      if (hasQueuedResolve(known.pass, accountId, offerId)) return skip;
      const policy = PAIR_POLICIES.get(`${raw.giveTokenId}/${raw.wantTokenId}`) ?? DEFAULT_PAIR_POLICY;
      return chain(
        hotBook(known.pass, meta.pairId, () => freshBook(policy)),
        ({ pass, book }): Result<CrossPassed<PreparedCross | null>, EntityError> => {
          const hot: CrossPass = { ...known, pass: { ...pass, cache: mapSet(pass.cache, meta.pairId, book) } };
          const existing = book.orders.get(orderId);
          if (existing === undefined) return ok({ cp: hot, value: { ...lots, orderId, book } });
          const same =
            existing.ownerId === meta.makerId &&
            existing.side === meta.side &&
            existing.priceTicks === meta.priceTicks &&
            existing.qtyLots === lots.qtyLots;
          if (same) return ok({ cp: hot, value: null });
          const fields = mismatchText([
            ["Owner", existing.ownerId, meta.makerId],
            ["Qty", existing.qtyLots, lots.qtyLots],
            ["Price", existing.priceTicks, meta.priceTicks],
          ]);
          return invariant(
            `ORDERBOOK_CROSS_J_DUPLICATE_SNAPSHOT_MISMATCH: pair=${meta.pairId} order=${orderId} ${fields}`,
          );
        },
      );
    });
  });
};
/** og removeCrossBookOrderAfterFill: a terminal fill takes the row off its committed book. */
const removeCrossRowAfterFill = (cp: CrossPass, pairId: string, orderId: string): Result<CrossPass, EntityError> => {
  const pass = cp.pass;
  const book = pass.cache.get(pairId) ?? pass.hub.ext.books.get(pairId);
  const order = book?.orders.get(orderId);
  if (book === undefined || order === undefined) return ok(cp);
  return map(cancelRow(book, order), (next) => ({ ...cp, pass: publishBook(pass, pairId, next) }));
};
const EXPECTED_CROSS_REJECTS: ReadonlySet<string> = new Set([
  "no fill",
  "FOK cannot fill entirely",
  "STP cancel taker",
]);
type CrossTrade = { readonly trade: Trade; readonly maker: CrossMarketOffer; readonly taker: CrossMarketOffer };
/** og canonicalCrossTradeEvents: both sides' market offers must exist, and the trade executes at the ask. */
const crossTrade = (cp: CrossPass, t: Trade): Result<CrossTrade, EntityError> =>
  chain(crossMeta(cp, t.makerOrderId), (maker) =>
    chain(crossMeta(cp, t.takerOrderId), (taker) => {
      if (maker === null || taker === null)
        return invariant(`ORDERBOOK_CROSS_J_TRADE_META_MISSING:maker=${t.makerOrderId}:taker=${t.takerOrderId}`);
      return map(crossExecutionPrice(maker, taker), (price) => ({ trade: { ...t, price }, maker, taker }));
    }),
  );
const addCrossFill = (fills: ReadonlyMap<string, CrossFillAgg>, orderId: string, fill: SameFill, cancels: boolean) => {
  const current = fills.get(orderId);
  const next: CrossFillAgg = current === undefined
    ? { filledLots: fill.filledLots, weightedCost: fill.weightedCost, cancelRemainder: cancels }
    : {
      filledLots: current.filledLots + fill.filledLots,
      weightedCost: current.weightedCost + fill.weightedCost,
      cancelRemainder: current.cancelRemainder || cancels,
    };
  return mapSet(fills, orderId, next);
};
/**
 * og commitRestingCrossOffer publishes the working overlay itself: from then on the pair's committed book and working
 * book are one object, so later speculative trades on that pair land in the published book too (commitBookOverlay folds
 * each step into the shared overlay).
 */
const settleWorking = (cp: CrossPass, pairId: string, book: Book, traded: boolean): CrossPass => {
  const working: CrossPass = { ...cp, working: mapSet(cp.working, pairId, book) };
  const publishes = (!traded && !cp.speculative.has(pairId)) || cp.aliased.has(pairId);
  const published: CrossPass = publishes
    ? { ...working, pass: publishBook(working.pass, pairId, book), aliased: withMember(working.aliased, pairId) }
    : working;
  return traded ? { ...published, speculative: withMember(published.speculative, pairId) } : published;
};
/**
 * og aggregateCrossTrades: a matched route never matches again in this pass; each order's fills add up, and the taker's
 * remainder is cancelled for IOC/FOK or an expected reject.
 */
const aggregateCrossTrades = (
  cp: CrossPass,
  trades: readonly CrossTrade[],
  takerOrderId: string,
  cancelTaker: boolean,
): CrossPass => {
  const matched = trades.flatMap(({ trade }) => [trade.makerOrderId, trade.takerOrderId]);
  const perOrder = aggregateFills(trades.map(({ trade }) => trade));
  return {
    ...cp,
    suspended: matched.reduce((suspended, orderId) => withMember(suspended, orderId), cp.suspended),
    fills: [...perOrder].reduce(
      (fills, [orderId, fill]) => addCrossFill(fills, orderId, fill, orderId === takerOrderId && cancelTaker),
      cp.fills,
    ),
  };
};
/**
 * The placement's outcome once its trades are known: a lone expected reject cancels the offer, anything else unexpected
 * halts.
 */
const crossOutcome = (
  cp: CrossPass,
  p: PreparedCross,
  result: BookStep,
  trades: readonly CrossTrade[],
): Result<CrossPass, EntityError> => {
  const { accountId, offerId } = p.raw;
  const rejects = result.events.flatMap((e) => (e.type === "REJECT" && e.orderId === p.orderId ? [e] : []));
  const expected = rejects.length > 0 && rejects.every((e) => EXPECTED_CROSS_REJECTS.has(e.reason));
  const reasons = rejects.map((e) => e.reason).join(",");
  if (rejects.length > 0 && trades.length === 0) {
    if (!expected) return liveReject(accountId, offerId, `cross-post-only-reject:${reasons}`);
    return map(crossCancelInstruction(accountId, offerId, p.orderId, p.meta.route), (i) => ({
      ...cp,
      suspended: withMember(cp.suspended, p.orderId),
      out: [...cp.out, i],
    }));
  }
  if (rejects.length > 0 && !expected) return liveReject(accountId, offerId, `cross-order-reject:${reasons}`);
  const settled = settleWorking(cp, p.meta.pairId, result.state, trades.length > 0);
  return ok(aggregateCrossTrades(settled, trades, p.orderId, p.raw.timeInForce !== 0 || expected));
};
/**
 * og processCrossOrderbookOffer: speculative placement on the working book; a resting-only placement commits, trades
 * aggregate into hub-internal fills.
 */
const processCrossOffer = (cp: CrossPass, raw: CrossBookOffer): Result<CrossPass, EntityError> =>
  chain(prepareCross(cp, raw), ({ cp: prepared, value: p }): Result<CrossPass, EntityError> => {
    if (p === null) return ok(prepared);
    const pairId = p.meta.pairId;
    const start = prepared.working.get(pairId) ?? p.book;
    const placing: CrossPass = { ...prepared, working: mapSet(prepared.working, pairId, start) };
    const cmd: OrderCmd = {
      kind: 0,
      ownerId: p.meta.makerId,
      orderId: p.orderId,
      side: p.meta.side,
      tif: raw.timeInForce,
      postOnly: false,
      priceTicks: p.meta.priceTicks,
      qtyLots: p.qtyLots,
    };
    const placed = judgedBookCommand(start, cmd, crossBookOptions(placing, p));
    if (!placed.ok) return liveReject(raw.accountId, raw.offerId, `cross-pair-error:${bookFailureText(placed.error)}`);
    const judged = learnMeta(placing, placed.value.learned);
    const result = placed.value.value;
    const rawTrades = result.events.flatMap((e) => (e.type === "TRADE" ? [e] : []));
    return chain(traverse(rawTrades, (t) => crossTrade(judged, t)), (trades) => {
      const known = learnMeta(judged, trades.flatMap(({ trade, maker, taker }) => [
        [trade.makerOrderId, maker] as const,
        [trade.takerOrderId, taker] as const,
      ]));
      return crossOutcome(known, p, result, trades);
    });
  });
type CrossPlan = { readonly net: ReadonlyMap<string, bigint>; readonly planned: readonly PlannedCrossFill[] };
type PlannedCrossFill = { readonly instruction: CrossFillInstruction; readonly pairId: string };
/** Per asset, what the hub paid out (negative) and took in (positive) across every executed amount. */
const netted = (
  net: ReadonlyMap<string, bigint>,
  route: CrossRoute,
  execution: CrossExecution | null,
): Result<ReadonlyMap<string, bigint>, EntityError> => {
  if (execution === null) return ok(net);
  const assets = all({
    source: fatalCross(assetKey(route.source.jurisdiction, route.source.tokenId)),
    target: fatalCross(assetKey(route.target.jurisdiction, route.target.tokenId)),
  });
  return map(assets, ({ source, target }) =>
    bump(bump(net, source, -execution.executionSourceAmount), target, execution.executionTargetAmount),
  );
};
/**
 * og planCrossFills: one order's aggregated fill as its instruction, or its terminal cancel when the fill moves
 * nothing.
 */
const planCrossFill =
  (cp: CrossPass) =>
  (plan: CrossPlan, [orderId, fill]: readonly [string, CrossFillAgg]): Result<CrossPlan, EntityError> =>
    chain(crossMeta(cp, orderId), (meta) => {
      if (meta === null) return invariant(`ORDERBOOK_CROSS_J_FILL_META_MISSING: order=${orderId}`);
      return chain(crossExecutionAmounts(meta, fill), (execution) => {
        const ref = parseOrderId(orderId, "ORDERBOOK_CROSS_J_MALFORMED_FILL_ORDER");
        return chain(netted(plan.net, meta.route, execution), (net) =>
          chain(ref, ({ accountId, offerId }) => {
            const instruction = chain(crossFillInstruction(accountId, offerId, orderId, meta, fill), (i) =>
              i === null && fill.cancelRemainder
                ? crossCancelInstruction(accountId, offerId, orderId, meta.route)
                : ok(i),
            );
            return map(instruction, (i) => ({
              net,
              planned: i === null ? plan.planned : [...plan.planned, { instruction: i, pairId: meta.pairId }],
            }));
          }),
        );
      });
    });
/** og commitCrossFill: a terminal fill leaves its book; every instruction goes out. */
const commitCrossFill = (cp: CrossPass, { instruction, pairId }: PlannedCrossFill): Result<CrossPass, EntityError> => {
  const removed = instruction.cancelRemainder ? removeCrossRowAfterFill(cp, pairId, instruction.orderId) : ok(cp);
  return map(removed, (next) => ({ ...next, out: [...next.out, instruction] }));
};
/**
 * og planCrossFills + commitCrossFill: fills in order-id order, conserved per asset across every executed amount; a
 * terminal one leaves the book.
 */
const finalizeCrossFills = (cp: CrossPass): Result<CrossPass, EntityError> => {
  const fills = [...cp.fills].toSorted(([a], [b]) => asc(a, b));
  const start: CrossPlan = { net: new Map(), planned: [] };
  return chain(foldResult(fills, start, planCrossFill(cp)), ({ net, planned }) => {
    const bad = [...net].toSorted(([a], [b]) => asc(a, b));
    if (bad.length > 0)
      return invariant(`CROSS_J_TRADE_CONSERVATION_FAILED:${bad.map(([asset, v]) => `${asset}=${v}`).join(",")}`);
    return foldResult(planned, cp, commitCrossFill);
  });
};
/** og processCrossJurisdictionOrderbookOffers: each cross-j offer in book order, then the pass's fills. */
const processCrossOffers = (
  pass: Pass,
  offers: readonly CrossBookOffer[],
): Result<Passed<readonly CrossFillInstruction[]>, EntityError> => {
  const start: CrossPass = {
    pass,
    meta: new Map(),
    fills: new Map(),
    suspended: new Set(),
    working: new Map(),
    speculative: new Set(),
    aliased: new Set(),
    out: [],
  };
  return map(chain(foldResult(offers, start, processCrossOffer), finalizeCrossFills), (cp) => ({
    pass: cp.pass,
    value: cp.out,
  }));
};

// ---- cross-j book owner and source hub lifecycle: og entity/tx/handlers/cross-j/
// {book-order,book-removal-ack,fill}.ts, account-cross-j-followups.ts (applyCrossJurisdictionOrderbookFill,
// applySourceHubCrossJurisdictionFillProgress), orderbook/cross-j/index.ts (row resize / materialize / remove),
// account/orderbook/cancels.ts routeRemoteCrossJurisdictionBookCancels. og mutates the Entity candidate in place; each
// step here returns the next host. ----
/** og CrossJurisdictionFillProgressData (crossJurisdictionFillNotice data). */
export type CrossProgress = {
  readonly orderId: string;
  readonly routeHash?: string | undefined;
  readonly fillSeq: number;
  readonly cumulativeFillRatio: number;
  readonly cancelRemainder?: boolean | undefined;
};
/** The og EntityState fields the book owner / source hub lifecycle reads and writes. */
export type BookHost = {
  readonly id: string;
  readonly timestamp: number;
  readonly validators: readonly string[];
  readonly ext?: OrderbookExt | undefined;
  readonly swaps?: ReadonlyMap<string, CrossRoute> | undefined;
  readonly admissions?: BookAdmissions | undefined;
  readonly accounts: ReadonlyMap<string, HubAccount>;
};
/**
 * One lifecycle step: the next host, raw cross-j Entity outputs, frame messages, and the swap offers it created for
 * this frame's matcher.
 */
export type BookHostStep = {
  readonly host: BookHost;
  readonly outputs: readonly CrossEntityOutput[];
  readonly messages: readonly string[];
  readonly created: readonly SwapOfferEvent[];
};
const hostStep = (host: BookHost, o: Partial<Omit<BookHostStep, "host">> = {}): BookHostStep =>
  ({ host, outputs: [], messages: [], created: [], ...o });
/** The next host, and whether the step changed anything. */
type HostChange = { readonly host: BookHost; readonly changed: boolean };
const unchanged = (host: BookHost): HostChange => ({ host, changed: false });
/** The last `chars` characters of a trimmed id, for a short log tag. */
const shortTail = (v: unknown, chars: number): string => {
  const t = String(v || "").trim();
  return t.length > chars ? t.slice(-chars) : t;
};
/** og crossJurisdictionBookOrderIdFor (orderbook/cross-j/index.ts): lowercased source, raw order id. */
const bookRowId = (sourceEntityId: string, orderId: string): string =>
  `${lowerText(sourceEntityId)}:${String(orderId)}`;
const withBook = (h: BookHost, ext: OrderbookExt, pairId: string, book: Book): BookHost =>
  ({ ...h, ext: { ...ext, books: mapSet(ext.books, pairId, book) } });
const bookHalt = <T,>(r: Result<T, BookError>): Result<T, EntityError> => mapErr(r, bookFault);


// -- book rows by id: og's derived order-pair index finds the one book that holds a row

type HeldRow = { readonly ext: OrderbookExt; readonly pairId: string; readonly book: Book };
/** The one book that holds a row; a row in two books halts. */
const rowHolder = (h: BookHost, id: string): Result<HeldRow | undefined, EntityError> => {
  const ext = h.ext;
  if (ext === undefined) return ok(undefined);
  const pairs = pairsHolding(ext.books, id);
  if (pairs.length > 1) return invariant(`ORDERBOOK_DUPLICATE_BOOK_ORDER: order=${id} matches=${pairs.length}`);
  const pairId = pairs[0];
  const book = pairId === undefined ? undefined : ext.books.get(pairId);
  return ok(pairId === undefined || book === undefined ? undefined : { ext, pairId, book });
};
/** og removeBookOrderByIdWithPair. */
const removeRowById = (h: BookHost, id: string): Result<HostChange, EntityError> =>
  chain(rowHolder(h, id), (held) => {
    const order = held?.book.orders.get(id);
    if (held === undefined || order === undefined) return ok(unchanged(h));
    return map(cancelRow(held.book, order), (book) => ({
      host: withBook(h, held.ext, held.pairId, book),
      changed: true,
    }));
  });
/** og resizeBookOrderById: a committed cross-j progress shrinks the row; never matcher repair. */
const resizeRowById = (h: BookHost, id: string, qty: bigint): Result<HostChange, EntityError> => {
  if (qty <= 0n || qty > MAX_ORDERBOOK_QTY_LOTS) return invariant(`ORDERBOOK_RESIZE_INVALID: order=${id} qty=${qty}`);
  return chain(rowHolder(h, id), (held) => {
    if (held === undefined) return ok(unchanged(h));
    return map(bookHalt(reduceBookOrderQuantity(held.book, id, qty)), (book) => ({
      host: withBook(h, held.ext, held.pairId, book),
      changed: true,
    }));
  });
};
type RowPlacement = {
  readonly pairId: string;
  readonly sourceEntityId: string;
  readonly orderId: string;
  readonly ownerId: string;
  readonly side: BookSide;
  readonly priceTicks: bigint;
  readonly qtyLots: bigint;
};
/** og materializeCrossJurisdictionBookRemainder: the committed remainder rests again, once, on its pair's book. */
const materializeRow = (h: BookHost, x: RowPlacement): Result<HostChange, EntityError> => {
  const ext = h.ext;
  if (ext === undefined) return ok(unchanged(h));
  const id = bookRowId(x.sourceEntityId, x.orderId);
  if (pairsHolding(ext.books, id).length > 0) return invariant(`ORDERBOOK_REMAINDER_ALREADY_PRESENT: order=${id}`);
  const book = ext.books.get(x.pairId);
  if (book === undefined) return ok(unchanged(h));
  const row = { orderId: id, ownerId: x.ownerId, side: x.side, priceTicks: x.priceTicks, qtyLots: x.qtyLots };
  return map(bookHalt(materializeCommittedRemainder(book, row)), (next) => ({
    host: withBook(h, ext, x.pairId, next),
    changed: true,
  }));
};


// -- route progress

const proofRatioE = (r: ProofRatioInput): Result<number, EntityError> => fatalCross(crossProofRatio(r));
const transitionE = (r: CrossRoute, next: CrossStatus, at: number): Result<CrossRoute, EntityError> =>
  crossTransitionAllowed(r.status, next)
    ? ok({ ...r, status: next, updatedAt: at })
    : invariant(`CROSS_J_ROUTE_TRANSITION_INVALID: route=${r.orderId} ${r.status || "intent"}->${next}`);
/** The route moves to `clear_requested` under the given clearing policy. */
const requestClear = (
  r: CrossRoute,
  at: number,
  policy: ClearingPolicy,
): Result<CrossRoute, EntityError> =>
  map(transitionE(r, "clear_requested", at), (next): CrossRoute => ({ ...next, clearingPolicy: policy }));
/**
 * og applyCrossJurisdictionFillProgress at a uint16 ratio (numerator = ratio, denominator = 65535); the prefix names
 * the caller's halt.
 */
const applyRatioProgress = (
  r: CrossRoute,
  fillSeq: number,
  ratio: number,
  at: number,
  prefix: string,
): Result<CrossRoute, EntityError> => {
  if (!Number.isFinite(ratio))
    return invariant(`RangeError: The number ${ratio} cannot be converted to a BigInt because it is not an integer`);
  const fill = { fillSeq, cumulativeFillRatio: ratio, fillNumerator: BigInt(ratio), fillDenominator: BigInt(MAX_FILL) };
  const next = applyCrossFill(r, fill, at);
  return next.ok ? ok(next.value) : invariant(`${prefix}: route=${r.orderId} ${next.error.reason}`);
};
const seqOf = (r: { readonly fillSeq?: number | undefined }): number => Math.floor(Number(r.fillSeq ?? 0));


// -- the book owner: admission, the committed order it exposes, and the progress it applies

/** A route exposed at its committed remainder: the source user's account id, the remainder, and the route itself. */
type Exposure = {
  readonly route: CrossRoute;
  readonly accountId: string;
  readonly rem: CrossRemaining;
  readonly clone: CrossRoute;
};
/** A route whose source has no Account on this Entity, exposed as the order its remainder stands for. */
const remoteOfferEvent = ({ route, accountId, rem, clone }: Exposure): Result<SwapOfferEvent, EntityError> => {
  const decimals = all({
    gd: tokenDecimals(Number(route.source.tokenId)),
    wd: tokenDecimals(Number(route.target.tokenId)),
  });
  return map(decimals, ({ gd, wd }): SwapOfferEvent => ({
    offerId: route.orderId,
    accountId,
    makerIsLeft: true,
    fromEntity: accountId,
    toEntity: entityRef(route.source.counterpartyEntityId),
    createdHeight: 0,
    giveTokenId: Number(route.source.tokenId),
    giveTokenDecimals: Number(gd),
    giveAmount: rem.sourceRemaining,
    wantTokenId: Number(route.target.tokenId),
    wantTokenDecimals: Number(wd),
    wantAmount: rem.targetRemaining,
    maxFee: 0n,
    minNetReceive: rem.targetRemaining,
    ...opt("priceTicks", route.priceTicks === undefined ? undefined : BigInt(route.priceTicks)),
    crossJurisdiction: clone,
  }));
};
/** A route whose source Account is here: the Account offer's shape at the route's remainder. */
const localOfferEvent = (
  { route, accountId, rem, clone }: Exposure,
  account: HubAccount,
  offer: SwapOffer,
): SwapOfferEvent => ({
  offerId: route.orderId,
  accountId,
  makerIsLeft: offer.makerIsLeft,
  fromEntity: account.left,
  toEntity: account.right,
  createdHeight: offer.createdHeight,
  giveTokenId: Number(offer.giveTokenId),
  giveTokenDecimals: offer.giveTokenDecimals,
  giveAmount: rem.sourceRemaining,
  wantTokenId: Number(offer.wantTokenId),
  wantTokenDecimals: offer.wantTokenDecimals,
  wantAmount: rem.targetRemaining,
  maxFee: 0n,
  minNetReceive: rem.targetRemaining,
  priceTicks: offer.priceTicks,
  ...opt("timeInForce", tif(offer.timeInForce)),
  crossJurisdiction: clone,
});
/**
 * og buildCommittedCrossJurisdictionOfferEvent: the order at its committed remainder. A local source Account supplies
 * its offer's shape; a remote source (the book owner is the target-side hub) is exposed from the route alone.
 */
export const committedCrossOfferEvent = (h: BookHost, route: CrossRoute): Result<SwapOfferEvent, EntityError> => {
  const accountId = entityRef(route.source.entityId);
  const account = h.accounts.get(accountId);
  const offer = account?.offers.get(route.orderId);
  return chain(crossRemaining(route), (rem) => chain(fatalCross(cloneCrossRoute(route)), (clone) => {
    const exposure: Exposure = { route, accountId, rem, clone };
    return account === undefined || offer?.crossJurisdiction === undefined
      ? remoteOfferEvent(exposure)
      : ok(localOfferEvent(exposure, account, offer));
  }));
};
/**
 * og admit: the route mirror takes the admitted route unless it already ended; a stale copy of the same route merges
 * the other way.
 */
const recordAdmittedRoute = (
  swaps: ReadonlyMap<string, CrossRoute>,
  route: CrossRoute,
): Result<ReadonlyMap<string, CrossRoute>, EntityError> => {
  const existing = swaps.get(route.orderId);
  if (existing !== undefined && isCrossTerminal(existing.status)) return ok(swaps);
  const transitionError = crossRouteTransitionError(existing, route);
  const eh = existing?.routeHash?.toLowerCase();
  const rh = route.routeHash?.toLowerCase();
  const staleSameRoute = Boolean(eh && rh) && eh === rh && compareCrossStatus(existing?.status, route.status) < 0;
  if (transitionError && !staleSameRoute)
    return invariant(`CROSS_J_BOOK_ADMIT_ROUTE_INVALID: order=${route.orderId} ${transitionError}`);
  const merged =
    staleSameRoute && existing !== undefined ? mergeCrossRoute(route, existing) : mergeCrossRoute(existing, route);
  return map(merged, (m) => mapSet(swaps, route.orderId, m));
};
/**
 * og handleAdmitCrossJurisdictionBookOrderEntityTx: the book owner records the route, merges the admission, and exposes
 * the committed order to this frame's matcher.
 */
export const admitBookOrder = (
  h: BookHost,
  data: { readonly route: CrossRoute; readonly reason?: string | undefined },
): Result<BookHostStep, EntityError> =>
  chain(canonRoute(data.route), (route) => {
    const now = h.timestamp;
    const owner = crossBookOwnerRef(route);
    const key = bookAdmissionKey(route.source.entityId, route.orderId);
    const prior = h.admissions?.get(key);
    const say = (what: string): readonly string[] => [`🌉 Cross-j book ${what}`];
    if (owner !== entityRef(h.id))
      return invariant(`CROSS_J_BOOK_ADMIT_WRONG_OWNER: order=${route.orderId} owner=${owner} current=${h.id}`);
    if (prior?.status === "closed" || prior?.status === "resolving") {
      const sameRoute = (prior.routeHash || "").toLowerCase() === (route.routeHash || "").toLowerCase();
      if (!sameRoute)
        return invariant(
          `CROSS_J_BOOK_ADMIT_ROUTE_INVALID: order=${route.orderId} existing admission route hash mismatch`,
        );
      return ok(hostStep(h, { messages: say(`admit ${route.orderId}: duplicate ${prior.status}`) }));
    }
    return chain(recordAdmittedRoute(h.swaps ?? new Map<string, CrossRoute>(), route), (swaps) =>
      chain(mergeBookAdmission(h.admissions, route, now), ({ admissions, admission }) => {
        const merged: BookHost = { ...h, swaps, admissions };
        const checked = all({
          event: committedCrossOfferEvent(merged, admission.route),
          failure: bookAdmissionFailure(h.id, admissions, admission.route, now),
        });
        return chain(checked, ({ event, failure }): Result<BookHostStep, EntityError> => {
          if (failure === null) {
            const admitted: BookAdmission = {
              ...admission,
              status: "admitted",
              admittedAt: admission.admittedAt ?? now,
              updatedAt: now,
            };
            const because = data.reason ? `: ${data.reason}` : "";
            return ok(
              hostStep(
                { ...merged, admissions: mapSet(admissions, key, admitted) },
                { messages: say(`admit ${route.orderId}${because}`), created: [event] },
              ),
            );
          }
          switch (failure.kind) {
            case "pending":
              return ok(hostStep(merged, { messages: say(`admit ${route.orderId}: pending ${failure.message}`) }));
            case "risk_reject": {
              const { source, orderId } = admission.route;
              return map(markAdmissionClosed(admissions, source.entityId, orderId, now, failure.message), (closed) =>
                hostStep(
                  { ...merged, admissions: closed },
                  { messages: say(`reject ${route.orderId}: ${failure.message}`) },
                ),
              );
            }
            case "invalid":
              return invariant(failure.message);
          }
        });
      }),
    );
  });
/** The book order a partially filled route stands for now. */
const progressMarket = (h: BookHost, route: CrossRoute): Result<CrossMarketOffer, EntityError> =>
  chain(committedCrossOfferEvent(h, route), (event) =>
    chain(normalizeCross(event, event.accountId || route.source.entityId, route), (n) =>
      chain(crossMarketOffer(n, h.id), (market) =>
        market === null ? invariant(`CROSS_J_BOOK_PROGRESS_MARKET_INVALID: order=${route.orderId}`) : ok(market))));
/**
 * og updateBookOrderForProgress: a partial fill resizes (or re-materializes) the row at the committed remainder; a
 * terminal one removes what still rests.
 */
const updateRowForProgress = (h: BookHost, route: CrossRoute): Result<BookHost, EntityError> => {
  const id = bookRowId(route.source.entityId, route.orderId);
  if (route.status !== "partially_filled") return map(removeRowById(h, id), (r) => r.host);
  return chain(progressMarket(h, route), (market) =>
    chain(crossBookQtyLots(market.baseTokenId, market.baseAmount), (qtyLots) =>
      chain(resizeRowById(h, id, qtyLots), (resized) => {
        if (resized.changed) return ok(resized.host);
        const placement: RowPlacement = {
          pairId: market.pairId,
          sourceEntityId: route.source.entityId,
          orderId: route.orderId,
          ownerId: market.makerId,
          side: market.side,
          priceTicks: market.priceTicks,
          qtyLots,
        };
        return chain(materializeRow(h, placement), (m) =>
          m.changed ? ok(m.host) : invariant(`CROSS_J_BOOK_PROGRESS_ORDER_MISSING: order=${route.orderId}`),
        );
      }),
    ),
  );
};
/** One progress notice at the book owner, with the admission it lands on. */
type BookFill = {
  readonly h: BookHost;
  readonly key: string;
  readonly admission: BookAdmission;
  readonly admissions: BookAdmissions;
  readonly route: CrossRoute;
  readonly data: CrossProgress;
  /** The source user sits behind a sibling hub, so this Entity also keeps the route mirror. */
  readonly remoteSource: boolean;
};
/** A repeated notice: the admission is touched, and a cancel closes it and asks the mirror for the clear. */
const repeatBookFill = ({
  h,
  key,
  admission,
  admissions,
  route,
  data,
  remoteSource,
}: BookFill): Result<HostChange, EntityError> => {
  const now = h.timestamp;
  const touched = mapSet(admissions, key, { ...admission, updatedAt: now });
  if (!data.cancelRemainder) return ok(unchanged({ ...h, admissions: touched }));
  const mirror = h.swaps?.get(route.orderId);
  const swaps =
    h.swaps !== undefined &&
    mirror !== undefined &&
    remoteSource &&
    (mirror.status === "resting" || mirror.status === "partially_filled")
      ? mapSet(h.swaps, route.orderId, {
          ...mirror,
          status: "clear_requested" as const,
          clearingPolicy: "cancel_and_clear" as const,
          updatedAt: now,
        })
      : h.swaps;
  return map(markAdmissionClosed(touched, route.source.entityId, route.orderId, now, "cancel_request"), (closed) =>
    unchanged({ ...h, admissions: closed, swaps }),
  );
};
/**
 * A newer notice: the route advances, the mirror follows it, the row resizes or leaves, and a terminal fill closes the
 * admission.
 */
const advanceBookFill = ({
  h,
  key,
  admission,
  admissions,
  route,
  data,
  remoteSource,
}: BookFill): Result<HostChange, EntityError> => {
  const now = h.timestamp;
  const currentSeq = seqOf(route);
  if (Math.floor(Number(data.fillSeq)) <= currentSeq) {
    return invariant(`CROSS_J_BOOK_PROGRESS_STALE: order=${route.orderId} seq=${data.fillSeq} current=${currentSeq}`);
  }
  const ratio = Math.floor(Number(data.cumulativeFillRatio));
  const progressed = chain(
    applyRatioProgress(route, data.fillSeq, ratio, now, "CROSS_J_BOOK_PROGRESS_INVALID"),
    (next) => (data.cancelRemainder ? requestClear(next, now, "cancel_and_clear") : ok(next)),
  );
  return chain(progressed, (next) => {
    const mirror = h.swaps?.get(route.orderId);
    const swaps =
      h.swaps !== undefined && mirror !== undefined && remoteSource
        ? map(mergeCrossRoute(mirror, next), (m) => mapSet(h.swaps ?? new Map<string, CrossRoute>(), route.orderId, m))
        : ok(h.swaps);
    const reason = data.cancelRemainder ? "cancel_request" : "fill_closed";
    return chain(swaps, (s) => {
      const moved: BookHost = {
        ...h,
        swaps: s,
        admissions: mapSet(admissions, key, { ...admission, route: next, updatedAt: now }),
      };
      return chain(updateRowForProgress(moved, next), (host) =>
        next.status === "partially_filled"
          ? ok({ host, changed: true })
          : map(markAdmissionClosed(host.admissions, next.source.entityId, next.orderId, now, reason), (closed) => ({
              host: { ...host, admissions: closed },
              changed: true,
            })),
      );
    });
  });
};
/** A notice that repeats the committed sequence and ratio exactly. */
const isRepeatedProgress = (route: CrossRoute, data: CrossProgress): Result<boolean, EntityError> =>
  seqOf(route) === Math.floor(Number(data.fillSeq))
    ? map(proofRatioE(route), (ratio) => ratio === Math.floor(Number(data.cumulativeFillRatio)))
    : ok(false);
/**
 * og applyCrossJurisdictionBookFillToState: the book owner's admitted route and row take the progress; returns whether
 * anything new applied.
 */
export const bookFillToState = (
  h: BookHost,
  sourceEntityId: string,
  data: CrossProgress,
): Result<HostChange, EntityError> => {
  const key = bookAdmissionKey(sourceEntityId, data.orderId);
  const admission = h.admissions?.get(key);
  const admissions = h.admissions;
  if (admission === undefined || admissions === undefined) {
    return invariant(`CROSS_J_BOOK_PROGRESS_ADMISSION_MISSING: order=${data.orderId} source=${sourceEntityId}`);
  }
  if (admission.status === "closed" && data.cancelRemainder) return ok(unchanged(h));
  if (admission.status !== "admitted" && admission.status !== "resolving") {
    return invariant(`CROSS_J_BOOK_PROGRESS_ADMISSION_NOT_ADMITTED: order=${data.orderId} status=${admission.status}`);
  }
  return chain(canonRoute(admission.route), (route) => {
    const owner = crossBookOwnerRef(route);
    const self = entityRef(h.id);
    if (owner !== self)
      return invariant(`CROSS_J_BOOK_PROGRESS_WRONG_OWNER: order=${route.orderId} owner=${owner} current=${h.id}`);
    const fill: BookFill = {
      h,
      key,
      admission,
      admissions,
      route,
      data,
      remoteSource: entityRef(route.source.counterpartyEntityId) !== self,
    };
    return chain(isRepeatedProgress(route, data), (repeated) =>
      repeated ? repeatBookFill(fill) : advanceBookFill(fill),
    );
  });
};


// -- the source hub: the route mirror follows the book owner's progress and asks for the clear at the end

/**
 * og routeBookOwnerEntityId / resolveLocalBookOwner (followups): the stored owner, else the canonical stack owner; none
 * means this Entity.
 */
const localBookOwner = (h: BookHost, route: CrossRoute): Result<boolean, EntityError> => {
  const owner = route.bookOwnerEntityId ? ok(route.bookOwnerEntityId) : fatalCross(crossBookOwner(route));
  return map(owner, (o) => !entityRef(o) || entityRef(o) === entityRef(h.id));
};
/**
 * og applyCommittedFillProgress: a cancel at or below the committed ratio only requests the clear; otherwise the ratio
 * advances and a terminal one requests it.
 */
const committedFillProgress = (
  route: CrossRoute,
  fill: CrossProgress,
  ratio: number,
  at: number,
): Result<CrossRoute, EntityError> =>
  chain(proofRatioE(route), (current) => {
    if (fill.cancelRemainder && ratio <= current) return requestClear(route, at, "cancel_and_clear");
    const terminalOf = (next: CrossRoute) =>
      fatalCross(isCrossFillTerminal(next, { nextRatio: ratio, cancelRemainder: fill.cancelRemainder }));
    const policy = fill.cancelRemainder || ratio < MAX_FILL ? "cancel_and_clear" : "full_fill";
    return chain(applyRatioProgress(route, fill.fillSeq, ratio, at, "CROSS_J_FILL_PROGRESS_INVALID"), (next) =>
      chain(transitionE(route, next.status, at), () =>
        chain(terminalOf(next), (terminal) => (terminal ? requestClear(next, at, policy) : ok(next))),
      ),
    );
  });
type HubProgress = {
  readonly host: BookHost;
  readonly applied: boolean;
  readonly outputs: readonly CrossEntityOutput[];
};
/**
 * A terminal progress at the source hub: a local book row leaves, and this Entity's proposer is asked for the clear.
 */
const requestClearAtSource = (
  h: BookHost,
  host: BookHost,
  next: CrossRoute,
  fill: CrossProgress,
): Result<HubProgress, EntityError> => {
  const at = h.timestamp;
  const removed = chain(localBookOwner(host, next), (local) => {
    if (!local) return ok(host);
    return chain(removeRowById(host, bookRowId(next.source.entityId, next.orderId)), (r) =>
      map(
        markAdmissionClosed(r.host.admissions, next.source.entityId, next.orderId, at, "fill_closed"),
        (admissions) => ({ ...r.host, admissions }),
      ),
    );
  });
  return chain(removed, (after) => {
    const signer = trimLower(h.validators[0] || "");
    if (!signer) return invariant(`CROSS_J_SELF_SIGNER_MISSING:${next.orderId}:${h.id}`);
    const request = { orderId: next.orderId, cancelRemainder: Boolean(fill.cancelRemainder) };
    const clear: CrossEntityOutput = {
      entityId: h.id,
      signerId: signer,
      txs: [{ type: "requestCrossJurisdictionClear", data: request }],
    };
    return ok({ host: after, applied: true, outputs: [clear] });
  });
};
/**
 * og applySourceHubCrossJurisdictionFillProgress: the source hub's route mirror takes the progress (a duplicate or late
 * one is ignored); a terminal progress removes a local book row and asks this Entity's proposer for the clear.
 */
export const sourceHubFillProgress = (h: BookHost, fill: CrossProgress): Result<HubProgress, EntityError> => {
  const at = h.timestamp;
  const route = h.swaps?.get(fill.orderId);
  const swaps = h.swaps;
  const ignored: HubProgress = { host: h, applied: false, outputs: [] };
  if (route === undefined || swaps === undefined) {
    const tag = `entity=${shortTail(h.id, 4)} offer=${shortTail(fill.orderId, 12)}`;
    return invariant(
      `CROSS_J_FILL_ROUTE_MISSING: ${tag} ratio=${fill.cumulativeFillRatio} cancel=${Boolean(fill.cancelRemainder)}`,
    );
  }
  if (entityRef(h.id) !== entityRef(route.source.counterpartyEntityId)) {
    return invariant(`CROSS_J_FILL_SOURCE_HUB_REQUIRED: order=${fill.orderId} entity=${h.id}`);
  }
  if (fill.routeHash && route.routeHash && fill.routeHash.toLowerCase() !== route.routeHash.toLowerCase()) {
    return invariant(
      `CROSS_J_FILL_ROUTE_HASH_MISMATCH: order=${fill.orderId} got=${fill.routeHash} expected=${route.routeHash}`,
    );
  }
  if (isCrossTerminal(route.status) || route.status === "clear_requested" || route.status === "clearing")
    return ok(ignored);
  if (!Number.isSafeInteger(fill.fillSeq) || !Number.isSafeInteger(fill.cumulativeFillRatio)) {
    return invariant(
      `CROSS_J_FILL_NOTICE_INVALID: order=${fill.orderId} seq=${fill.fillSeq} ratio=${fill.cumulativeFillRatio}`,
    );
  }
  const ratio = Math.max(0, Math.min(MAX_FILL, fill.cumulativeFillRatio));
  const currentSeq = currentFillSeq(route);
  const incoming = fill.fillSeq;
  const isCancel = Boolean(fill.cancelRemainder) && incoming === currentSeq;
  const conflict = incoming === currentSeq ? map(proofRatioE(route), (committed) => ratio !== committed) : ok(false);
  return chain(conflict, (stale): Result<HubProgress, EntityError> => {
    if (stale)
      return invariant(`CROSS_J_FILL_NOTICE_STALE_CONFLICT: order=${fill.orderId} seq=${incoming} ratio=${ratio}`);
    if (!isCancel && incoming <= currentSeq) return ok(ignored);
    return chain(committedFillProgress(route, fill, ratio, at), (progressed) => {
      const next: CrossRoute = { ...progressed, updatedAt: at };
      const host: BookHost = { ...h, swaps: mapSet(swaps, fill.orderId, next) };
      const terminal = fatalCross(
        isCrossFillTerminal(next, { nextRatio: ratio, cancelRemainder: fill.cancelRemainder }),
      );
      return chain(terminal, (ends) =>
        ends ? requestClearAtSource(h, host, next, fill) : ok({ host, applied: true, outputs: [] }),
      );
    });
  });
};
/** og buildCrossJurisdictionFillProgressData. */
const progressOf = (i: CrossFillInstruction): CrossProgress => ({
  orderId: i.offerId,
  ...opt("routeHash", i.route.routeHash || undefined),
  fillSeq: i.fillSeq,
  cumulativeFillRatio: i.fillRatio,
  cancelRemainder: i.cancelRemainder,
});
/**
 * og applyCrossJurisdictionOrderbookFill: the book owner applies the progress, then hands it to the source hub
 * (locally, or as a fill notice).
 */
export const orderbookFill = (
  h: BookHost,
  i: CrossFillInstruction,
): Result<{ readonly host: BookHost; readonly outputs: readonly CrossEntityOutput[] }, EntityError> => {
  const data = progressOf(i);
  return chain(bookFillToState(h, i.accountId, data), ({ host }) => {
    if (entityRef(i.route.source.counterpartyEntityId) === entityRef(host.id)) {
      return map(sourceHubFillProgress(host, data), (s) => ({ host: s.host, outputs: s.outputs }));
    }
    const sourceHub = trimLower(i.route.source.counterpartyEntityId);
    const signer = trimLower(i.route.sourceHubSignerId || "");
    if (!sourceHub || !signer) return invariant(`CROSS_J_FILL_NOTICE_SOURCE_HUB_MISSING:${i.offerId}`);
    return map(crossOutput(sourceHub, signer, [{ type: "crossJurisdictionFillNotice", data }]), (out) => ({
      host,
      outputs: [out],
    }));
  });
};


// -- removal: the book owner takes a route off its book and ACKs; the source hub closes it out

type RemovalRequest = {
  readonly orderId: string;
  readonly sourceEntityId: string;
  readonly sourceAccountId?: string | undefined;
  readonly route?: CrossRoute | undefined;
  readonly reason?: string | undefined;
};
/** og's removal ACK to the source hub, carrying this book's progress; only a request from a source Account gets one. */
const removalAck = (
  host: BookHost,
  ackRoute: CrossRoute,
  data: RemovalRequest,
): Result<readonly CrossEntityOutput[], EntityError> => {
  if (!data.sourceAccountId) return ok([]);
  const sourceHub = entityRef(ackRoute.source.counterpartyEntityId);
  const at = `order=${ackRoute.orderId}:target=${sourceHub}`;
  if (!sourceHub || sourceHub === entityRef(host.id)) return invariant(`CROSS_J_BOOK_REMOVAL_ACK_TARGET_INVALID:${at}`);
  const signer = crossRouteSigner(ackRoute, sourceHub);
  if (!signer) return invariant(`CROSS_J_BOOK_REMOVAL_ACK_SIGNER_MISSING:${at}`);
  const removed = {
    orderId: ackRoute.orderId,
    sourceEntityId: ackRoute.source.entityId,
    sourceAccountId: data.sourceAccountId ?? "",
    route: ackRoute,
    removedAt: host.timestamp,
    reason: data.reason || "cancel_request",
  };
  return map(crossOutput(sourceHub, signer, [{ type: "crossJurisdictionBookOrderRemoved", data: removed }]), (o) => [
    o,
  ]);
};
/**
 * og handleRemoveCrossJurisdictionBookOrderEntityTx: the named admitted route leaves this book; the source hub gets an
 * ACK carrying this book's progress.
 */
export const removeCrossBookOrder = (h: BookHost, data: RemovalRequest): Result<BookHostStep, EntityError> => {
  if (data.route === undefined) return invariant(`CROSS_J_BOOK_REMOVAL_ROUTE_MISSING:${data.orderId}`);
  return chain(canonRoute(data.route), (route) => {
    const named =
      route.orderId === data.orderId &&
      entityRef(route.source.entityId) === entityRef(data.sourceEntityId) &&
      crossBookOwnerRef(route) === entityRef(h.id);
    if (!named) return invariant(`CROSS_J_BOOK_REMOVAL_ROUTE_MISMATCH:${data.orderId}`);
    const admission = h.admissions?.get(bookAdmissionKey(data.sourceEntityId, data.orderId));
    if (admission !== undefined && entityRef(admission.routeHash || "") !== entityRef(route.routeHash || "")) {
      return invariant(`CROSS_J_CANCEL_ADMISSION_ROUTE_MISMATCH:${data.orderId}`);
    }
    return chain(removeRowById(h, bookRowId(data.sourceEntityId, data.orderId)), ({ host, changed }) => {
      const reason = data.reason || "removeCrossJurisdictionBookOrder";
      const because = data.reason ? `: ${data.reason}` : "";
      const note = `🌉 Cross-j book remove ${data.orderId}${because} ${changed ? "removed" : "not-present"}`;
      return chain(removalAck(host, host.swaps?.get(data.orderId) ?? route, data), (outputs) =>
        map(
          markAdmissionClosed(host.admissions, data.sourceEntityId, data.orderId, host.timestamp, reason),
          (admissions) => hostStep({ ...host, admissions }, { outputs, messages: [note] }),
        ),
      );
    });
  });
};
type RemovalAck = {
  readonly orderId: string;
  readonly sourceEntityId: string;
  readonly sourceAccountId: string;
  readonly route: CrossRoute;
  readonly removedAt: number;
  readonly reason?: string | undefined;
};
/**
 * og handleCrossJurisdictionBookOrderRemovedEntityTx: the source hub closes the admission and requests the clear from
 * the later of its mirror and the ACK's progress. og's dispute-preparing branch (confirmDisputeBookRemoval +
 * draftPreparedDisputeStartIfReady) belongs to the dispute port.
 */
export const bookOrderRemoved = (h: BookHost, data: RemovalAck): Result<BookHostStep, EntityError> =>
  chain(canonRoute(data.route), (route) => {
    if (entityRef(h.id) !== entityRef(route.source.counterpartyEntityId)) {
      return invariant(`CROSS_J_BOOK_REMOVAL_ACK_SOURCE_HUB_REQUIRED:order=${route.orderId}:entity=${h.id}`);
    }
    const visible = h.accounts.get(data.sourceAccountId);
    const offer = visible?.offers.get(route.orderId);
    const current = h.swaps?.get(route.orderId);
    const at = `order=${route.orderId}:account=${data.sourceAccountId}`;
    const missing = `CROSS_J_BOOK_REMOVAL_ACK_SOURCE_STATE_MISSING:${at}`;
    if (current === undefined) return invariant(missing);
    if (entityRef(current.routeHash || "") !== entityRef(route.routeHash || "")) {
      return invariant(`CROSS_J_BOOK_REMOVAL_ACK_ROUTE_HASH_MISMATCH:order=${route.orderId}`);
    }
    if (isCrossTerminal(current.status)) return ok(hostStep(h));
    if (visible === undefined || offer?.crossJurisdiction === undefined) return invariant(missing);
    const closing = markAdmissionClosed(
      h.admissions,
      route.source.entityId,
      route.orderId,
      data.removedAt,
      data.reason || "cancel_request",
    );
    return chain(closing, (admissions) => {
      const carriedAhead = currentFillSeq(route) > currentFillSeq(current);
      const fillSeq = carriedAhead ? currentFillSeq(current) + 1 : currentFillSeq(current);
      return chain(proofRatioE(carriedAhead ? route : current), (ratio) => {
        const progress: CrossProgress = {
          orderId: route.orderId,
          ...opt("routeHash", current.routeHash || undefined),
          fillSeq,
          cumulativeFillRatio: ratio,
          cancelRemainder: true,
        };
        return map(sourceHubFillProgress({ ...h, admissions }, progress), (s) => {
          const note = s.applied ? "removal committed" : "removal already cleared";
          return hostStep(s.host, { outputs: s.outputs, messages: [`🌉 Cross-j book ${note} ${route.orderId}`] });
        });
      });
    });
  });
/** og handleCrossJurisdictionFillNoticeEntityTx: the book owner's progress reaches the source hub. */
export const crossFillNotice = (h: BookHost, data: CrossProgress): Result<BookHostStep, EntityError> =>
  map(sourceHubFillProgress(h, data), (s) => {
    const note = s.applied
      ? `applied ${data.cumulativeFillRatio}`
      : `duplicate seq ${Math.floor(Number(data.fillSeq))}`;
    return hostStep(s.host, { outputs: s.outputs, messages: [`🌉 Cross-j fill notice ${data.orderId} ${note}`] });
  });


// -- cancels that reach a cross-j order

type RemoteCancels = {
  readonly host: BookHost;
  readonly local: readonly SwapRef[];
  readonly outputs: readonly CrossEntityOutput[];
};
/**
 * One cancel: a local book keeps it, a sibling hub's book gets a removal request, and the admission starts resolving.
 */
const routeRemoteCancel = (acc: RemoteCancels, cancel: SwapRef): Result<RemoteCancels, EntityError> => {
  const route = acc.host.accounts.get(cancel.accountId)?.offers.get(cancel.offerId)?.crossJurisdiction;
  const kept: RemoteCancels = { ...acc, local: [...acc.local, cancel] };
  if (route === undefined || !acc.host.swaps?.has(cancel.offerId)) return ok(kept);
  const current = trimLower(acc.host.id);
  const sourceHub = trimLower(route.source.counterpartyEntityId);
  if (current !== sourceHub)
    return invariant(
      `CROSS_J_CANCEL_SOURCE_HUB_REQUIRED:offer=${cancel.offerId}:entity=${current}:sourceHub=${sourceHub}`,
    );
  const owner = crossBookOwnerRef(route);
  if (!owner) return invariant(`CROSS_J_CANCEL_BOOK_OWNER_MISSING:offer=${cancel.offerId}`);
  if (owner === current) return ok(kept);
  const signer = crossRouteSigner(route, owner);
  if (!signer) return invariant(`CROSS_J_CANCEL_BOOK_OWNER_SIGNER_MISSING:offer=${cancel.offerId}:owner=${owner}`);
  const removal = {
    orderId: cancel.offerId,
    sourceEntityId: route.source.entityId,
    sourceAccountId: cancel.accountId,
    route,
    reason: "cancel_request",
  };
  return chain(markAdmissionResolving(acc.host.admissions, route, acc.host.timestamp), (admissions) =>
    map(crossOutput(owner, signer, [{ type: "removeCrossJurisdictionBookOrder", data: removal }]), (out) => ({
      host: { ...acc.host, admissions },
      local: acc.local,
      outputs: [...acc.outputs, out],
    })),
  );
};
/**
 * og routeRemoteCrossJurisdictionBookCancels: a cross-j cancel whose book lives on a sibling hub becomes a removal
 * request there; the admission starts resolving.
 */
export const routeRemoteCancels = (h: BookHost, cancels: readonly SwapRef[]): Result<RemoteCancels, EntityError> =>
  foldResult(cancels, { host: h, local: [], outputs: [] }, routeRemoteCancel);
/**
 * og applyCommittedSwapCancelsToOrderbook's cross branch: a committed removal of a still-visible cross-j offer closes
 * its admission (`committed_cancel`).
 */
export const closeCommittedCrossCancels = (h: BookHost, cancels: readonly SwapRef[]): Result<BookHost, EntityError> => {
  const ext = h.ext;
  if (ext === undefined || cancels.length === 0) return ok(h);
  const keyOf = ({ accountId, offerId }: SwapRef): string => swapKeyOf(accountId, offerId);
  // og walks the cancels with a `gone` set: each order counts once, and only while exactly one book holds it
  const held = firstBy(cancels, keyOf).filter((c) => pairsHolding(ext.books, keyOf(c)).length === 1);
  return foldResult(held, h, (acc, { accountId, offerId }) => {
    const route = acc.accounts.get(entityRef(accountId))?.offers.get(offerId)?.crossJurisdiction;
    if (route === undefined) return ok(acc);
    return map(
      markAdmissionClosed(acc.admissions, route.source.entityId, offerId, acc.timestamp, "committed_cancel"),
      (admissions) => ({ ...acc, admissions }),
    );
  });
};


// -- a cross-j offer the source Account already holds, checked before it may match

const COMMITTED_POSITIVE = ["priceTicks", "quantizedGive", "quantizedWant"] as const;
/**
 * og requireCommittedSwapOffer for a cross-j candidate its source Account already holds: the offer is committed, idle,
 * and matches field for field.
 */
const committedCrossOfferError = (account: HubAccount, o: BookOfferInput): string | null => {
  const committed = account.offers.get(o.offerId);
  const who = `account=${o.accountId} offer=${o.offerId}`;
  if (committed === undefined) return `ORDERBOOK_ORDER_NOT_COMMITTED: ${who}`;
  const resolving = account.queued.some(
    (tx) => (tx.type === "swap_resolve" || tx.type === "swap_cancel_request") && tx.offerId === o.offerId,
  );
  if (resolving) return `ORDERBOOK_ORDER_NOT_READY: ${who}`;
  const incomplete = COMMITTED_POSITIVE.find((field) => {
    const value: unknown = committed[field];
    return typeof value !== "bigint" || value <= 0n;
  });
  if (incomplete !== undefined) return `ORDERBOOK_ORDER_COMMITTED_INCOMPLETE: ${who} field=${incomplete}`;
  if (committed.quantizedGive !== committed.giveAmount || committed.quantizedWant !== committed.wantAmount) {
    const give = `give=${committed.giveAmount}/${committed.quantizedGive}`;
    const want = `want=${committed.wantAmount}/${committed.quantizedWant}`;
    return `ORDERBOOK_ORDER_COMMITTED_QUANTIZATION_DRIFT: ${who} ${give} ${want}`;
  }
  const pairs: readonly (readonly [committed: unknown, offered: unknown])[] = [
    [Number(committed.giveTokenId), o.giveTokenId],
    [committed.giveTokenDecimals, o.giveTokenDecimals],
    [Number(committed.wantTokenId), o.wantTokenId],
    [committed.wantTokenDecimals, o.wantTokenDecimals],
    [committed.quantizedGive, o.giveAmount],
    [committed.quantizedWant, o.wantAmount],
    [committed.maxFee, o.maxFee],
    [committed.minNetReceive, o.minNetReceive],
    [committed.priceTicks, o.priceTicks],
    [committed.makerIsLeft, o.makerIsLeft],
    [committed.crossJurisdiction !== undefined, o.crossJurisdiction !== undefined],
  ];
  return pairs.every(([held, offered]) => held === offered) ? null : `ORDERBOOK_ORDER_COMMITTED_MISMATCH: ${who}`;
};
/**
 * og admitOrderbookOfferForMatching (cross branch): a working route only; a live Account; a pending or risk-rejected
 * admission waits; any other failure halts.
 */
const admitCrossForMatching = (hub: Hub, o: CrossBookOffer): Result<boolean, EntityError> => {
  const status = o.crossJurisdiction.status;
  if (status !== "resting" && status !== "partially_filled") {
    return invariant(`CROSS_J_ORDERBOOK_ROUTE_NOT_WORKING: offer=${o.offerId} status=${status}`);
  }
  const account = hub.accounts.get(entityRef(o.accountId));
  if (account !== undefined && !account.active) return ok(false);
  const bad = account?.offers.has(o.offerId) ? committedCrossOfferError(account, o) : null;
  if (bad !== null) return invariant(bad);
  const failure = bookAdmissionFailure(hub.id, hub.crossAdmissions, o.crossJurisdiction, Number(hub.timestamp ?? 0));
  return chain(failure, (f) => (f?.kind === "invalid" ? invariant(f.message) : ok(f === null)));
};

// ---- og entity/tx/handlers/cross-j/clear.ts (requestCrossJurisdictionClear, materializeCrossJurisdictionClear),
// payments/pull.ts (crossPullClose) and cross-j/sweep.ts (orderbookSweepCrossJurisdiction). og mutates the Entity
// candidate in place; each step here returns the next host and the Account work. ----
/** A cross-j step that also returns Account work (og AccountTxTarget[]). */
export type CrossHostStep = BookHostStep & { readonly accountTxs: readonly AccountTxTarget[] };
type CrossAcc = {
  readonly host: BookHost;
  readonly messages: readonly string[];
  readonly outputs: readonly CrossEntityOutput[];
  readonly accountTxs: readonly AccountTxTarget[];
};
const crossAcc = (host: BookHost): CrossAcc => ({ host, messages: [], outputs: [], accountTxs: [] });
const accNote = (a: CrossAcc, message: string): CrossAcc => ({ ...a, messages: [...a.messages, message] });
const accStep = (a: CrossAcc): CrossHostStep => ({
  ...hostStep(a.host, { outputs: a.outputs, messages: a.messages }),
  accountTxs: a.accountTxs,
});
/** A step that only notes why nothing happened. */
const crossNoted = (h: BookHost, message: string): Result<CrossHostStep, never> =>
  ok(accStep(accNote(crossAcc(h), message)));
const putRoute = <H extends BookHost>(h: H, route: CrossRoute): H =>
  ({ ...h, swaps: mapSet(h.swaps ?? new Map<string, CrossRoute>(), route.orderId, route) });
/** og accountHasCrossPullCloseQueued: a cross_pull_close for this pull in the mempool or our pending frame. */
const pullCloseQueued = (a: HubAccount, pullId: string): boolean =>
  a.queued.some((tx) => tx.type === "cross_pull_close" && tx.pullId === pullId);
/** og's proposer wake: an empty input to this Entity's validators[0], as stored. */
const selfWake = (h: BookHost): readonly CrossEntityOutput[] => {
  const v = h.validators[0];
  return v ? [{ entityId: h.id, signerId: v, txs: [] }] : [];
};
const fillRatioE = (r: CrossRoute): Result<number, EntityError> =>
  map(fatalCross(crossFillAmounts(r)), (f) => f.fillRatio);
const closeProofE = (r: CrossRoute, binary: string): Result<CrossCloseProof, EntityError> =>
  fatalCross(buildCrossCloseProof(r, binary));
const EXACT_PROOF_FIELDS = [
  "orderId",
  "sourcePullId",
  "targetPullId",
  "fillRatio",
  "cumulativeSourceAmount",
  "cumulativeTargetAmount",
  "closeMode",
] as const;
/** og closeProofMatches / closeProofsMatch: route and binary hashes compare lowercased, the rest exactly. */
const closeProofSame = (a: CrossCloseProof, b: CrossCloseProof): boolean =>
  lowerText(a.routeHash) === lowerText(b.routeHash)
  && lowerText(a.binaryHash) === lowerText(b.binaryHash)
  && EXACT_PROOF_FIELDS.every((field) => a[field] === b[field]);
/** The local route enters `clearing` carrying the source close proof. */
const enterClearing = (route: CrossRoute, proof: CrossCloseProof, at: number): Result<CrossRoute, EntityError> =>
  transitionE({ ...route, sourceCloseProof: proof }, "clearing", at);
/**
 * og's atomic Hub close: the sibling hub receives the paired target close, carrying the route as it enters `clearing`.
 */
const pairedTargetClose = (
  route: CrossRoute,
  targetPullId: string,
  binary: string,
  proof: CrossCloseProof,
  at: number,
  description: string,
): Result<CrossEntityOutput, EntityError> =>
  chain(cloneRouteE(route), (clone) => chain(enterClearing(clone, proof, at), (command) => {
    const close = {
      counterpartyEntityId: route.target.counterpartyEntityId,
      pullId: targetPullId,
      binary,
      proof,
      route: command,
      description,
    };
    return crossOutput(route.target.entityId, route.targetHubSignerId, [{ type: "crossPullClose", data: close }]);
  }));


// -- asking for the clear

/**
 * og requestPureCancel: nothing filled, so both pulls close at ratio 0 in one Hub cohort (the source here, the target
 * through the sibling hub).
 */
const pureCancelClear = (
  a: CrossAcc,
  route: CrossRoute,
  accountId: string | null,
  orderId: string,
  cancel: boolean,
): Result<CrossHostStep, EntityError> => {
  if (!cancel) return ok(accStep(accNote(a, `🌉 Cross-j clear ${orderId} ignored: no pending fill`)));
  const at = a.host.timestamp;
  const { sourcePull, targetPull } = route;
  return chain(closeProofE(route, "0x"), (proof) => {
    const account = accountId === null ? undefined : a.host.accounts.get(accountId);
    const holdsPull = account?.pulls?.has(sourcePull?.pullId ?? "") ?? false;
    if (accountId === null || sourcePull === undefined || targetPull === undefined || !holdsPull) {
      return ok(accStep(accNote(a, `🌉 Cross-j clear ${orderId} waiting for source close proof`)));
    }
    const description = `Cross-j ${orderId} paired pure-cancel target close`;
    return chain(pairedTargetClose(route, targetPull.pullId, "0x", proof, at, description), (out) =>
      map(enterClearing(route, proof, at), (r): CrossHostStep =>
        accStep({
          host: putRoute(a.host, { ...r, pendingClearRequestedAt: at, clearingPolicy: "cancel_and_clear" }),
          messages: [...a.messages, `🌉 Cross-j clear ${orderId} queued atomic Hub pure-cancel close`],
          outputs: [...a.outputs, out, ...selfWake(a.host)],
          accountTxs: [
            ...a.accountTxs,
            { accountId, tx: { type: "cross_pull_close", pullId: sourcePull.pullId, binary: "0x", proof } },
          ],
        }),
      ),
    );
  });
};
/**
 * og requestFilledRouteReveal: a committed fill waits for the default proposer's ladder reveal
 * (materializeCrossJurisdictionClear).
 */
const filledRevealClear = (
  a: CrossAcc,
  route: CrossRoute,
  accountId: string | null,
  orderId: string,
  cancel: boolean,
  ratio: number,
): Result<CrossHostStep, EntityError> => {
  const account = accountId === null ? undefined : a.host.accounts.get(accountId);
  const pullId = route.sourcePull?.pullId ?? "";
  const ignored = (why: string): Result<CrossHostStep, never> =>
    ok(accStep(accNote(a, `🌉 Cross-j clear ${orderId} ignored: ${why}`)));
  if (account === undefined)
    return ok(
      accStep(accNote(a, `❌ Cross-j clear ${orderId} blocked: no source account with ${route.source.entityId}`)),
    );
  if (!(account.pulls?.has(pullId) ?? false)) return ignored("source pull already closed");
  if (pullCloseQueued(account, pullId)) return ignored("source pull close already queued");
  const at = a.host.timestamp;
  const clearingPolicy = cancel || ratio < MAX_FILL ? "cancel_and_clear" : "full_fill";
  return map(transitionE(route, "clear_requested", at), (r) =>
    accStep({
      ...a,
      host: putRoute(a.host, { ...r, pendingClearRequestedAt: at, clearingPolicy }),
      messages: [...a.messages, `🌉 Cross-j clear ${orderId} awaiting proposer reveal ratio=${ratio}/${MAX_FILL}`],
      outputs: [...a.outputs, ...selfWake(a.host)],
    }),
  );
};
/**
 * og findCrossJurisdictionOfferRoute: the Account offer's opening snapshot, when there is one, must name the same
 * route.
 */
const offerSnapshotMatches = (h: BookHost, stored: CrossRoute, peer: string): Result<void, EntityError> => {
  const offerRoute = peer ? h.accounts.get(peer)?.offers.get(stored.orderId)?.crossJurisdiction : undefined;
  if (offerRoute === undefined) return ok(undefined);
  return chain(canonRoute(offerRoute), (c) =>
    lowerText(c.routeHash) === lowerText(stored.routeHash)
      ? ok(undefined)
      : invariant(`CROSS_J_CLEAR_ROUTE_HASH_MISMATCH:${stored.orderId}`),
  );
};
/**
 * og requestClearThroughSourceAccount: the user cannot address the remote hub; its Account carries the cancel to the
 * source hub.
 */
const clearThroughSourceAccount = (
  h: BookHost,
  route: CrossRoute,
  srcHub: string,
  cancel: boolean,
): Result<CrossHostStep, EntityError> => {
  const orderId = route.orderId;
  if (h.accounts.get(srcHub)?.offers.get(orderId)?.crossJurisdiction === undefined) {
    return invariant(`CROSS_J_CLEAR_SOURCE_OFFER_MISSING:${orderId}:${h.id}:${srcHub}`);
  }
  return chain(cancel ? ok(1) : fillRatioE(route), (ratio) => {
    if (ratio <= 0) return crossNoted(h, `🌉 Cross-j clear ${orderId} ignored: no pending fill`);
    const clearingPolicy = cancel ? "cancel_and_clear" : "manual";
    return map(transitionE(route, "clear_requested", h.timestamp), (r) =>
      accStep({
        host: putRoute(h, { ...r, pendingClearRequestedAt: h.timestamp, clearingPolicy }),
        messages: [`🌉 Cross-j clear ${orderId} queued through source Account`],
        outputs: [],
        accountTxs: [{ accountId: srcHub, tx: { type: "swap_cancel_request", offerId: orderId } }],
      }),
    );
  });
};
/**
 * The source hub's own clear: a still-resting local row leaves, then an unfilled route closes at once and a filled one
 * waits for the reveal.
 */
const clearAtSourceHub = (
  h: BookHost,
  route: CrossRoute,
  src: string,
  cancel: boolean,
): Result<CrossHostStep, EntityError> =>
  chain(canonRoute(route), (canonical) => {
    const orderId = route.orderId;
    if (!canonical.sourcePull || !canonical.targetPull)
      return invariant(`CROSS_J_CLEAR_CORRUPT_ROUTE: order=${orderId} pull commitments missing`);
    if (canonical.status === "clearing")
      return crossNoted(h, `🌉 Cross-j clear ${orderId} ignored: close already queued`);
    return chain(fillRatioE(canonical), (ratio) => {
      const accountId = h.accounts.has(src) ? src : null;
      // og: the user's Account offer stays open until the pull close deletes it; only a still-resting local book row
      // leaves before the reveal
      const removed = accountId === null ? ok(unchanged(h)) : removeRowById(h, `${accountId}:${orderId}`);
      return chain(removed, ({ host, changed }) => {
        const a = changed
          ? accNote(crossAcc(host), `🌉 Cross-j clear ${orderId} removed live book order`)
          : crossAcc(host);
        return ratio <= 0
          ? pureCancelClear(a, canonical, accountId, orderId, cancel)
          : filledRevealClear(a, canonical, accountId, orderId, cancel, ratio);
      });
    });
  });
/**
 * og handleRequestCrossJurisdictionClearEntityTx: a source user asks through its Account (swap_cancel_request); the
 * source hub removes a still-resting local row, then closes an unfilled route at once (pure cancel) or asks its
 * proposer for the ladder reveal of the committed fill.
 */
export const requestCrossClear = (
  h: BookHost,
  data: { readonly orderId: string; readonly cancelRemainder?: boolean | undefined },
): Result<CrossHostStep, EntityError> => {
  const orderId = data.orderId;
  const cancel = data.cancelRemainder ?? false;
  const stored = h.swaps?.get(orderId);
  if (stored === undefined) return invariant(`CROSS_J_CLEAR_ROUTE_MISSING:${orderId}`);
  if (isCrossTerminal(stored.status))
    return crossNoted(h, `🌉 Cross-j clear ${orderId} ignored: route ${stored.status}`);
  const self = entityRef(h.id);
  const src = entityRef(stored.source.entityId);
  const srcHub = entityRef(stored.source.counterpartyEntityId);
  const peer = self === src ? srcHub : self === srcHub ? src : "";
  return chain(offerSnapshotMatches(h, stored, peer), () =>
    chain(cloneRouteE(stored), (route) => {
      if (self === srcHub) return clearAtSourceHub(h, route, src, cancel);
      if (self !== src) return invariant(`CROSS_J_CLEAR_SOURCE_PARTICIPANT_REQUIRED:${orderId}:${h.id}:${src}`);
      return clearThroughSourceAccount(h, route, srcHub, cancel);
    }),
  );
};


// -- the proposer's reveal, and the pull closes it drives

/** og materializeCrossJurisdictionClear data: the default proposer's public reveal of the committed fill. */
export type CrossClearReveal = {
  readonly proposerSignerId: string;
  readonly orderId: string;
  readonly binary: string;
  readonly proof: CrossCloseProof;
};
type VerifiedReveal = { readonly fillRatio: number; readonly proof: CrossCloseProof; readonly accountId: string };
/**
 * Every validator checks the reveal against the committed source pull: the ladder opens at the committed ratio and
 * yields the same proof.
 */
const verifyReveal = (h: BookHost, route: CrossRoute, data: CrossClearReveal): Result<VerifiedReveal, EntityError> => {
  const { orderId, binary } = data;
  const sp = route.sourcePull;
  if (sp === undefined || route.targetPull === undefined)
    return invariant(`CROSS_J_CLEAR_MATERIALIZE_PULLS_MISSING:${orderId}`);
  if (entityRef(route.source.counterpartyEntityId) !== entityRef(h.id))
    return invariant(`CROSS_J_CLEAR_MATERIALIZE_SOURCE_HUB_MISMATCH:${orderId}`);
  return chain(fillRatioE(route), (fillRatio) => {
    if (fillRatio <= 0) return invariant(`CROSS_J_CLEAR_MATERIALIZE_FILL_MISSING:${orderId}`);
    const decoded = verifyHashLadderBinary({ fullHash: sp.fullHash, partialRoot: sp.partialRoot }, binary);
    if (!decoded.ok) return invariant(`CROSS_J_CLEAR_MATERIALIZE_BINARY_INVALID:${orderId}:${decoded.error.reason}`);
    if (decoded.value.fillRatio !== fillRatio) {
      return invariant(`CROSS_J_CLEAR_MATERIALIZE_RATIO_MISMATCH:${orderId}:${decoded.value.fillRatio}:${fillRatio}`);
    }
    return chain(closeProofE(route, binary), (proof) => {
      if (!closeProofSame(data.proof, proof)) return invariant(`CROSS_J_CLEAR_MATERIALIZE_PROOF_MISMATCH:${orderId}`);
      const accountId = entityRef(route.source.entityId);
      const account = h.accounts.get(accountId);
      if (account === undefined || !(account.pulls?.has(sp.pullId) ?? false))
        return invariant(`CROSS_J_CLEAR_MATERIALIZE_SOURCE_PULL_MISSING:${orderId}`);
      if (pullCloseQueued(account, sp.pullId)) return invariant(`CROSS_J_CLEAR_MATERIALIZE_ALREADY_QUEUED:${orderId}`);
      return ok({ fillRatio, proof, accountId });
    });
  });
};
/**
 * og handleMaterializeCrossJurisdictionClearEntityTx: every validator verifies the proposer's reveal against the
 * committed source pull (the private seed never enters replay), then the hub closes its source pull and sends the
 * paired target close to the sibling hub.
 */
export const materializeCrossClear = (h: BookHost, data: CrossClearReveal): Result<CrossHostStep, EntityError> => {
  const { orderId, binary } = data;
  const expected = entityRef(h.validators[0] || "");
  const claimed = entityRef(data.proposerSignerId);
  if (!expected || claimed !== expected) {
    return crossEvict(`CROSS_J_CLEAR_MATERIALIZE_PROPOSER_INVALID:${claimed || "missing"}:${expected || "missing"}`);
  }
  const stored = h.swaps?.get(orderId);
  if (stored === undefined || stored.status !== "clear_requested")
    return invariant(`CROSS_J_CLEAR_MATERIALIZE_INTENT_MISSING:${orderId}`);
  return chain(canonRoute(stored), (route) =>
    chain(verifyReveal(h, route, data), ({ fillRatio, proof, accountId }) =>
      // og writes the stored route (its fork), which must carry the canonical hash exactly
      chain(cloneRouteE(stored), (fork) => {
        const at = h.timestamp;
        const { sourcePull, targetPull } = fork;
        const ratio = `${fillRatio}/${MAX_FILL}`;
        if (route.routeHash && fork.routeHash !== route.routeHash)
          return invariant(`CROSS_J_CLEAR_MATERIALIZE_ROUTE_FORK_MISMATCH:${orderId}`);
        if (sourcePull === undefined) return invariant(`CROSS_J_CLEAR_SOURCE_PULL_MISSING:${fork.orderId}`);
        if (targetPull === undefined) return invariant(`CROSS_J_CLEAR_TARGET_PULL_MISSING:${orderId}`);
        const description = `Cross-j ${fork.orderId} paired target close ${ratio}`;
        return chain(pairedTargetClose(fork, targetPull.pullId, binary, proof, at, description), (out) =>
          map(enterClearing(fork, proof, at), (next) =>
            accStep({
              host: putRoute(h, next),
              messages: [`🌉 Cross-j clear ${orderId} queued atomic Hub source+target close ratio=${ratio}`],
              outputs: [out, ...selfWake(h)],
              accountTxs: [{ accountId, tx: { type: "cross_pull_close", pullId: sourcePull.pullId, binary, proof } }],
            }),
          ),
        );
      }),
    ),
  );
};
/** og crossPullClose Entity tx data. */
export type CrossPullCloseData = {
  readonly counterpartyEntityId: string;
  readonly pullId: string;
  readonly binary: string;
  readonly proof: CrossCloseProof;
  readonly route?: CrossRoute | undefined;
  readonly description?: string | undefined;
};
type PullLeg = "source" | "target";
/** The route a close command carries must name the proof's order, route and both pulls. */
const commandRouteError = (command: CrossRoute | undefined, proof: CrossCloseProof): string | null => {
  if (command === undefined) return null;
  switch (true) {
    case command.orderId !== proof.orderId:
      return `command route order ${command.orderId} != ${proof.orderId}`;
    case lowerText(command.routeHash) !== lowerText(proof.routeHash):
      return `command route hash ${command.routeHash} != ${proof.routeHash}`;
    case command.sourcePull?.pullId !== proof.sourcePullId:
      return `command source pull ${command.sourcePull?.pullId} != ${proof.sourcePullId}`;
    case command.targetPull?.pullId !== proof.targetPullId:
      return `command target pull ${command.targetPull?.pullId} != ${proof.targetPullId}`;
    default:
      return null;
  }
};
/** The proof against the one og builds at the proof's own ratio: amounts and mode must agree. */
const expectedProofError = (proof: CrossCloseProof, e: CrossCloseProof): string | null => {
  switch (true) {
    case proof.fillRatio !== e.fillRatio:
      return `ratio ${proof.fillRatio} != ${e.fillRatio}`;
    case proof.cumulativeSourceAmount !== e.cumulativeSourceAmount:
      return `source amount ${proof.cumulativeSourceAmount} != ${e.cumulativeSourceAmount}`;
    case proof.cumulativeTargetAmount !== e.cumulativeTargetAmount:
      return `target amount ${proof.cumulativeTargetAmount} != ${e.cumulativeTargetAmount}`;
    case proof.closeMode !== e.closeMode:
      return `mode ${proof.closeMode} != ${e.closeMode}`;
    default:
      return null;
  }
};
/** A target close must carry the source close proof it pairs with. */
const pairedProofError = (
  route: CrossRoute,
  proof: CrossCloseProof,
  leg: PullLeg,
  command: CrossRoute | undefined,
): string | null => {
  if (leg !== "target") return null;
  const sourceProof = route.sourceCloseProof ?? command?.sourceCloseProof;
  if (!sourceProof) return "source close proof missing";
  return closeProofSame(sourceProof, proof) ? null : "source close proof mismatch";
};
/**
 * og proofRouteError (payments/pull.ts): the close must name this route and pull, open its ladder at the proof ratio,
 * and never roll the informed ratio back.
 */
const pullCloseProofError = (
  route: CrossRoute,
  proof: CrossCloseProof,
  binary: string,
  leg: PullLeg,
  command: CrossRoute | undefined,
): Result<string | null, EntityError> => {
  const routeHash = lowerText(route.routeHash);
  const { sourcePull, targetPull } = route;
  if (!routeHash) return ok("route hash missing");
  if (lowerText(proof.routeHash) !== routeHash) return ok(`route hash ${proof.routeHash} != ${routeHash}`);
  const commandError = commandRouteError(command, proof);
  if (commandError !== null) return ok(commandError);
  if (proof.orderId !== route.orderId) return ok(`order ${proof.orderId} != ${route.orderId}`);
  if (!sourcePull || !targetPull) return ok("pull commitments missing");
  if (proof.sourcePullId !== sourcePull.pullId) return ok(`source pull ${proof.sourcePullId} != ${sourcePull.pullId}`);
  if (proof.targetPullId !== targetPull.pullId) return ok(`target pull ${proof.targetPullId} != ${targetPull.pullId}`);
  const commitment = leg === "source" ? sourcePull : targetPull;
  const ladder = { fullHash: commitment.fullHash, partialRoot: commitment.partialRoot };
  return chain(fatalCross(crossCloseBinaryHash(binary)), (binaryHash) => {
    if (lowerText(proof.binaryHash) !== binaryHash.toLowerCase()) return ok("binary hash mismatch");
    return chain(fatalCross(verifyHashLadderBinary(ladder, binary)), (decoded) => {
      if (decoded.fillRatio !== proof.fillRatio)
        return ok(`binary ratio ${decoded.fillRatio} != proof ${proof.fillRatio}`);
      const pairing = pairedProofError(route, proof, leg, command);
      if (pairing !== null) return ok(pairing);
      return chain(proofRatioE(route), (routeRatio) => {
        if (proof.fillRatio < routeRatio) return ok(`ratio ${proof.fillRatio} < informed ${routeRatio}`);
        if (leg !== "source" && routeRatio <= 0) return ok(null);
        // og: off-chain progress never gates the close; the expectation is built at the proof's ratio
        return map(closeProofE(withCloseProofProgress(route, proof, route.updatedAt), binary), (e) =>
          expectedProofError(proof, e),
        );
      });
    });
  });
};
/** The route a pull close finds: this hub's source leg with the user, else its target leg with the sibling hub. */
const closedLeg = (
  h: BookHost,
  pullId: string,
  cp: string,
): { readonly route: CrossRoute; readonly leg: PullLeg } | undefined => {
  const self = entityRef(h.id);
  const routes = [...(h.swaps?.values() ?? [])];
  const source = routes.find(
    (r) =>
      r.sourcePull?.pullId === pullId &&
      entityRef(r.source.counterpartyEntityId) === self &&
      entityRef(r.source.entityId) === cp,
  );
  const target = routes.find(
    (r) =>
      r.targetPull?.pullId === pullId &&
      entityRef(r.target.entityId) === self &&
      entityRef(r.target.counterpartyEntityId) === cp,
  );
  if (source !== undefined) return { route: source, leg: "source" };
  return target === undefined ? undefined : { route: target, leg: "target" };
};
/** The target hub's route after its close: the proof's progress, then `clearing` under a cancel-and-clear policy. */
const targetClearing = (withProof: CrossRoute, proof: CrossCloseProof, at: number): Result<CrossRoute, EntityError> => {
  const progressed = withCloseProofProgress(withProof, proof, withProof.updatedAt);
  const pendingClearRequestedAt = progressed.pendingClearRequestedAt || at;
  return transitionE({ ...progressed, clearingPolicy: "cancel_and_clear", pendingClearRequestedAt }, "clearing", at);
};
/**
 * og handleCrossPullCloseEntityTx: the source hub closes its user's source pull, or the target hub closes the paired
 * target pull the source hub sent; terminal or not-yet-clearing routes only note it, invalid close data halts, and
 * every gate runs before the mirror moves.
 */
export const crossPullCloseTx = (h: BookHost, data: CrossPullCloseData): Result<CrossHostStep, EntityError> => {
  const { pullId, binary, proof } = data;
  const cp = entityRef(data.counterpartyEntityId);
  if (!h.accounts.has(cp)) return invariant(`CROSS_J_PULL_CLOSE_ACCOUNT_MISSING:${data.counterpartyEntityId}`);
  const found = closedLeg(h, pullId, cp);
  if (found === undefined) return invariant(`CROSS_J_PULL_CLOSE_ROUTE_MISSING:${pullId}`);
  const { route, leg } = found;
  const short = pullId.slice(0, 8);
  if (isCrossTerminal(route.status))
    return crossNoted(h, `❌ Cross-j ${leg} pull close ${short} blocked: route ${route.status}`);
  if (leg === "source" && route.status !== "clearing" && route.status !== "clear_requested") {
    return crossNoted(h, `❌ Cross-j source pull close ${short} blocked: route ${route.status}`);
  }
  return chain(pullCloseProofError(route, proof, binary, leg, data.route), (bad) => {
    if (bad !== null) return invariant(`CROSS_J_PULL_CLOSE_PROOF_INVALID:${pullId}:${bad}`);
    return chain(fatalCross(cloneCloseProof(proof)), (closeProof) =>
      chain(cloneRouteE(route), (fork) => {
        const withProof: CrossRoute = { ...fork, sourceCloseProof: closeProof };
        const next = leg === "source" ? ok(withProof) : targetClearing(withProof, proof, h.timestamp);
        return map(next, (r) =>
          accStep({
            host: putRoute(h, r),
            messages: [],
            outputs: selfWake(h),
            accountTxs: [{ accountId: cp, tx: { type: "cross_pull_close", pullId, binary, proof } }],
          }),
        );
      }),
    );
  });
};


// -- the book-TTL sweep

type SweepTally = CrossAcc & { readonly expired: number; readonly closed: number; readonly waiting: number };
/**
 * One route under the sweep: a live one waits, an expired one this hub sources is cleared, anyone else's is counted.
 */
const sweepRoute =
  (at: number) =>
  (s: SweepTally, [orderId, route]: readonly [string, CrossRoute]): Result<SweepTally, EntityError> => {
    if (isCrossTerminal(route.status)) return ok(s);
    if (!isCrossExpired(route, at)) return ok({ ...s, waiting: s.waiting + 1 });
    const sourceHub = lowerText(route.source.counterpartyEntityId);
    if (!sourceHub) return invariant(`CROSS_J_SWEEP_SOURCE_HUB_MISSING:${orderId}`);
    if (lowerText(s.host.id) !== sourceHub) return ok({ ...s, expired: s.expired + 1, waiting: s.waiting + 1 });
    return map(requestCrossClear(s.host, { orderId, cancelRemainder: true }), (c): SweepTally => ({
      host: c.host,
      messages: [...s.messages, ...c.messages],
      outputs: [...s.outputs, ...c.outputs],
      accountTxs: [...s.accountTxs, ...c.accountTxs],
      expired: s.expired + 1,
      closed: s.closed + (c.accountTxs.some((t) => t.tx.type === "cross_pull_close") ? 1 : 0),
      waiting: s.waiting,
    }));
  };
/**
 * og handleOrderbookSweepCrossJurisdictionEntityTx: the book-TTL sweep; the source hub clears each expired route it
 * owns (cancelling the remainder).
 */
export const crossSweep = (h: BookHost, reason?: string | undefined): Result<CrossHostStep, EntityError> => {
  const start: SweepTally = { ...crossAcc(h), expired: 0, closed: 0, waiting: 0 };
  const because = reason ? `: ${reason}` : "";
  return map(foldResult([...(h.swaps?.entries() ?? [])], start, sweepRoute(h.timestamp)), (s) =>
    accStep(
      accNote(
        s,
        `🌉 Cross-j orderbook sweep${because} expired=${s.expired} closedOffers=${s.closed} waiting=${s.waiting}`,
      ),
    ),
  );
};

// ---- og entity/tx/handlers/account-cross-j-followups.ts applyCommittedCrossJurisdictionAccountTxFollowup: what a
// committed cross_pull_lock / cross_pull_close does to the Entity (route mirror, one-shot user authorization, expiry
// hook, book admission or removal). ----
/**
 * The Entity fields a committed cross-j Account tx rewrites: the book host plus the user authorizations and the
 * crontab.
 */
export type CommittedCrossHost = BookHost & {
  readonly auths?: ReadonlyMap<string, CrossRoute> | undefined;
  readonly crontab?: Crontab | undefined;
};
export type CommittedCrossStep = {
  readonly host: CommittedCrossHost;
  readonly outputs: readonly CrossEntityOutput[];
  readonly messages: readonly string[];
  readonly created: readonly SwapOfferEvent[];
  readonly handled: boolean;
};
/** og routeBookOwnerEntityId: the stored owner, else the canonical market's. */
const bookOwnerIdE = (route: CrossRoute): Result<string, EntityError> =>
  map(route.bookOwnerEntityId ? ok(route.bookOwnerEntityId) : fatalCross(crossBookOwner(route)), entityRef);
/** The four parties of a route: the source user and its hub, the target hub and its user. */
type RouteParties = {
  readonly sourceUser: string;
  readonly sourceHub: string;
  readonly targetHub: string;
  readonly targetUser: string;
};
const partiesOf = (route: CrossRoute): RouteParties => ({
  sourceUser: entityRef(route.source.entityId),
  sourceHub: entityRef(route.source.counterpartyEntityId),
  targetHub: entityRef(route.target.entityId),
  targetUser: entityRef(route.target.counterpartyEntityId),
});
/**
 * og removeOrRouteCrossJurisdictionBookOrder: a local book drops the row and closes the admission; a sibling book owner
 * gets a removal request.
 */
const removeOrRouteBookOrder = (
  s: CommittedCrossStep,
  route: CrossRoute,
  reason: string,
): Result<CommittedCrossStep, EntityError> =>
  chain(bookOwnerIdE(route), (owner): Result<CommittedCrossStep, EntityError> => {
    const h = s.host;
    if (!owner || owner === entityRef(h.id)) {
      return chain(removeRowById(h, bookRowId(route.source.entityId, route.orderId)), (r) =>
        map(
          markAdmissionClosed(r.host.admissions, route.source.entityId, route.orderId, h.timestamp, reason),
          (admissions) => ({ ...s, host: { ...h, ext: r.host.ext, admissions } }),
        ),
      );
    }
    const signer = crossRouteSigner(route, owner);
    if (!signer) return invariant(`CROSS_J_ROUTE_SIGNER_MISSING:${route.orderId}:${owner}`);
    const removal = { orderId: route.orderId, sourceEntityId: route.source.entityId, route, reason };
    return map(crossOutput(owner, signer, [{ type: "removeCrossJurisdictionBookOrder", data: removal }]), (out) => ({
      ...s,
      outputs: [...s.outputs, out],
    }));
  });


// -- a committed pull lock: the route goes resting, and the source hub admits it to the book

/** og committedPullMatchesRoute: the committed lock is exactly the route's pull on this leg. */
const committedPullMatches = (tx: TxOf<"cross_pull_lock">, route: CrossRoute, leg: PullLeg): boolean => {
  const pull = leg === "source" ? route.sourcePull : route.targetPull;
  const b = tx.crossJurisdiction;
  if (pull === undefined || b.leg !== leg || b.orderId !== route.orderId) return false;
  return lowerText(b.routeHash) === lowerText(route.routeHash)
    && tx.pullId === pull.pullId
    && Number(tx.tokenId) === pull.tokenId
    && tx.amount === pull.signedAmount
    && lowerText(tx.fullHash) === pull.fullHash.toLowerCase()
    && lowerText(tx.partialRoot) === pull.partialRoot.toLowerCase();
};
type PullRole = { readonly leg: PullLeg; readonly sourceHub: boolean };
/**
 * og getCommittedPullRole: which leg this pull is, and whether this Entity is the source hub committing it with the
 * source user.
 */
const committedPullRole = (route: CrossRoute, self: string, cp: string, pullId: string): PullRole | null => {
  const p = partiesOf(route);
  const sourcePull = route.sourcePull?.pullId === pullId;
  const targetPull = route.targetPull?.pullId === pullId;
  const between = (a: string, b: string): boolean => (self === a && cp === b) || (self === b && cp === a);
  switch (true) {
    case sourcePull && self === p.sourceHub && cp === p.sourceUser:
      return { leg: "source", sourceHub: true };
    case sourcePull && self === p.sourceUser && cp === p.sourceHub:
      return { leg: "source", sourceHub: false };
    case targetPull && between(p.targetHub, p.targetUser):
      return { leg: "target", sourceHub: false };
    default:
      return null;
  }
};
/**
 * og admitCommittedSourcePullToBook: the expiry sweep hook, then the book admission (here, or at the sibling book
 * owner).
 */
const admitCommittedPull = (s: CommittedCrossStep, route: CrossRoute): Result<CommittedCrossStep, EntityError> => {
  const crontab = s.host.crontab;
  if (crontab === undefined) return invariant(`CROSS_J_EXPIRY_CRONTAB_MISSING:${route.orderId}`);
  const expiresAt = Math.floor(Number(route.expiresAt || 0));
  if (!Number.isSafeInteger(expiresAt) || expiresAt <= s.host.timestamp) {
    return invariant(`CROSS_J_EXPIRY_INVALID:${route.orderId}:${String(route.expiresAt)}`);
  }
  const hook = {
    id: `cross-j-expiry:${route.orderId}`,
    type: "cross_j_orderbook_sweep",
    triggerAt: expiresAt,
    data: { reason: `cross-j-expiry:${route.orderId}` },
  } as const;
  const hooked: CommittedCrossStep = {
    ...s,
    messages: [...s.messages, `🌉 Cross-j swap ${route.orderId} committed by both Account legs`],
    host: { ...s.host, crontab: scheduleHook(crontab, hook) },
  };
  return chain(bookOwnerIdE(route), (owner) => chain(cloneRouteE(route), (clone) => {
    const data = { route: clone, reason: "atomic_account_pair_committed" };
    // og drops a local admission's outputs; only its created offers reach this frame's matcher
    if (owner === entityRef(s.host.id)) {
      return map(admitBookOrder(hooked.host, data), (a): CommittedCrossStep => ({
        ...hooked,
        host: { ...hooked.host, ...a.host },
        messages: [...hooked.messages, ...a.messages],
        created: [...hooked.created, ...a.created],
      }));
    }
    const signer = crossRouteSigner(route, owner);
    if (!signer) return invariant(`CROSS_J_ROUTE_SIGNER_MISSING:${route.orderId}:${owner}`);
    return map(crossOutput(owner, signer, [{ type: "admitCrossJurisdictionBookOrder", data }]), (out) =>
      ({ ...hooked, outputs: [...hooked.outputs, out] }));
  }));
};
/**
 * One mirrored route naming the committed pull: its user leg spends the one-shot authorization, and it goes resting.
 */
const lockRoute =
  (tx: TxOf<"cross_pull_lock">, self: string, cp: string, committedAt: number) =>
  (acc: CommittedCrossStep, orderId: string): Result<CommittedCrossStep, EntityError> => {
    const route = acc.host.swaps?.get(orderId);
    const role = route === undefined ? null : committedPullRole(route, self, cp, tx.pullId);
    if (route === undefined || role === null) return ok(acc);
    if (!committedPullMatches(tx, route, role.leg)) {
      return invariant(
        `CROSS_J_COMMITTED_PULL_ROUTE_MISMATCH: route=${route.orderId} leg=${role.leg} pull=${tx.pullId}`,
      );
    }
    const userLeg = self === entityRef(route.source.entityId) || self === entityRef(route.target.counterpartyEntityId);
    const auth = acc.host.auths?.get(route.orderId);
    if (userLeg && (auth === undefined || entityRef(auth.routeHash || "") !== entityRef(route.routeHash || ""))) {
      return invariant(`CROSS_J_COMMITTED_PULL_AUTH_MISSING:${route.orderId}:${self}`);
    }
    const host: CommittedCrossHost =
      userLeg && acc.host.auths !== undefined
        ? { ...acc.host, auths: mapDelete(acc.host.auths, route.orderId) }
        : acc.host;
    return chain(cloneRouteE(route), (clone) =>
      chain(transitionE(clone, "resting", committedAt), (resting) => {
        const next: CommittedCrossStep = { ...acc, host: putRoute(host, { ...route, ...resting }), handled: true };
        return role.sourceHub ? admitCommittedPull(next, resting) : ok(next);
      }),
    );
  };
/**
 * og queueBookAdmissionOnCommittedPull: the carried route joins the mirror; each route naming this pull goes resting, a
 * user's one-shot authorization is consumed, the source hub admits the order.
 */
const committedPullLock = (
  start: CommittedCrossStep,
  cp: string,
  tx: TxOf<"cross_pull_lock">,
  committedAt: number,
): Result<CommittedCrossStep, EntityError> =>
  chain(cloneRouteE(tx.crossJurisdictionRoute), (carried) => {
    const existing = start.host.swaps?.get(carried.orderId);
    if (
      existing?.routeHash &&
      carried.routeHash &&
      existing.routeHash.toLowerCase() !== carried.routeHash.toLowerCase()
    ) {
      return invariant(`CROSS_J_COMMITTED_PULL_ROUTE_CONFLICT:${carried.orderId}`);
    }
    const s: CommittedCrossStep = { ...start, host: putRoute(start.host, { ...existing, ...carried }) };
    const orderIds = [...(s.host.swaps?.keys() ?? [])];
    return foldResult(orderIds, s, lockRoute(tx, entityRef(s.host.id), entityRef(cp), committedAt));
  });


// -- a committed pull close: every route naming the pull projects the close and ends

/** og assertTerminalPullReplay: a close replayed against a terminal mirror must be the recorded close exactly. */
const terminalPullReplay = (
  route: CrossRoute,
  fillRatio: number,
  binary: string,
  supplied: CrossCloseProof,
): Result<boolean, EntityError> => {
  if (!isCrossTerminal(route.status)) return ok(false);
  const proof = route.sourceCloseProof;
  return chain(fatalCross(crossFillAmounts(route)), (c) =>
    chain(fatalCross(crossCloseBinaryHash(binary)), (binaryHash) => {
      const recorded =
        proof !== undefined &&
        fillRatio === c.fillRatio &&
        proof.fillRatio === c.fillRatio &&
        entityRef(proof.binaryHash) === entityRef(binaryHash) &&
        proof.cumulativeSourceAmount === c.filledSourceAmount &&
        proof.cumulativeTargetAmount === c.filledTargetAmount;
      if (!recorded)
        return invariant(`CROSS_J_TERMINAL_PULL_REPLAY_MISMATCH: route=${route.orderId} ratio=${fillRatio}`);
      const same =
        entityRef(supplied.routeHash) === entityRef(proof.routeHash) &&
        entityRef(supplied.binaryHash) === entityRef(proof.binaryHash) &&
        EXACT_PROOF_FIELDS.every((field) => supplied[field] === proof[field]);
      return same ? ok(true) : invariant(`CROSS_J_TERMINAL_PULL_PROOF_REPLAY_MISMATCH: route=${route.orderId}`);
    }),
  );
};
/** The mirror states a hub may close each leg from. */
const CLOSABLE_FROM: Readonly<Record<PullLeg, ReadonlySet<CrossStatus | undefined>>> = {
  source: new Set(["clearing", "clear_requested"]),
  target: new Set(["resting", "partially_filled", "clear_requested", "clearing"]),
};
/**
 * og assertCrossPullCloseAllowed: the proof names this route, its amounts are the ratio's projection, it never rolls
 * back, and a hub mirror is already clearing.
 */
const pullCloseAllowed = (
  route: CrossRoute,
  fillRatio: number,
  leg: PullLeg,
  hubCommitted: boolean,
  proof: CrossCloseProof,
): Result<void, EntityError> => {
  const names =
    proof.orderId === route.orderId &&
    entityRef(proof.routeHash) === entityRef(route.routeHash || "") &&
    proof.sourcePullId === route.sourcePull?.pullId &&
    proof.targetPullId === route.targetPull?.pullId;
  if (!names) return invariant(`CROSS_J_PULL_CLOSE_PROOF_MISMATCH: route=${route.orderId}`);
  const ratio = BigInt(fillRatio);
  const max = BigInt(MAX_FILL);
  const project = (total: bigint): bigint => (ratio >= max ? total : (total * ratio) / max);
  const projected =
    proof.cumulativeSourceAmount === project(BigInt(route.source.amount)) &&
    proof.cumulativeTargetAmount === project(BigInt(route.target.amount));
  if (!projected) return invariant(`CROSS_J_PULL_CLOSE_ECONOMICS_MISMATCH: route=${route.orderId} ratio=${fillRatio}`);
  return chain(proofRatioE(route), (committed): Result<void, EntityError> => {
    if (fillRatio < committed)
      return invariant(`CROSS_J_PULL_CLOSE_ROLLBACK: route=${route.orderId} ratio=${fillRatio} informed=${committed}`);
    if (fillRatio <= 0 || !hubCommitted || CLOSABLE_FROM[leg].has(route.status)) return ok(undefined);
    return invariant(`CROSS_J_PULL_CLOSE_STATE_INVALID: route=${route.orderId} leg=${leg} status=${route.status}`);
  });
};
/** og transitionTargetLegTerminal: a filled close settles; an unfilled one expired or was cancelled. */
const closedAs = (fillRatio: number, route: CrossRoute, at: number): CrossStatus => {
  switch (true) {
    case fillRatio > 0:
      return "settled";
    case isCrossExpired(route, at):
      return "expired";
    default:
      return "cancelled";
  }
};
type ClosedRoute = { readonly step: CommittedCrossStep; readonly route: CrossRoute; readonly terminal: CrossStatus };
/**
 * og applyCrossPullCloseProgress + transitionTargetLegTerminal: the mirror takes the close at its ratio and ends
 * settled, expired or cancelled; the expiry hook goes.
 */
const closeProgress = (
  s: CommittedCrossStep,
  orderId: string,
  proof: CrossCloseProof,
  fillRatio: number,
): Result<ClosedRoute, EntityError> => {
  const stored = s.host.swaps?.get(orderId);
  const at = s.host.timestamp;
  if (stored === undefined) return invariant(`CROSS_J_PULL_CLOSE_ROUTE_FORK_MISSING:${orderId}`);
  return chain(fatalCross(cloneCloseProof(proof)), (closeProof) => {
    const progressed: CrossRoute = {
      ...withCloseProofProgress(stored, proof, at),
      sourceCloseProof: closeProof,
      targetCloseProof: closeProof,
    };
    const clearing = progressed.status !== "clearing" ? transitionE(progressed, "clearing", at) : ok(progressed);
    return chain(clearing, (c) => {
      const terminal = closedAs(fillRatio, c, at);
      return map(transitionE(c, terminal, at), (ended) => {
        const route: CrossRoute = terminal === "settled" ? { ...ended, settledAt: at } : ended;
        const crontab = s.host.crontab;
        const unhooked = opt(
          "crontab",
          crontab === undefined ? undefined : cancelHook(crontab, `cross-j-expiry:${orderId}`),
        );
        return { step: { ...s, host: { ...putRoute(s.host, route), ...unhooked } }, route, terminal };
      });
    });
  });
};
type CloseWalk = { readonly step: CommittedCrossStep; readonly matched: boolean };
/**
 * The source leg closes: a replay is only checked, a new close projects; the source hub then drops or routes the book
 * order.
 */
const closeSourceLeg = (
  w: CloseWalk,
  route: CrossRoute,
  tx: TxOf<"cross_pull_close">,
  sourceHub: boolean,
): Result<CloseWalk, EntityError> => {
  const fillRatio = tx.proof.fillRatio;
  const matched = (step: CommittedCrossStep): CloseWalk => ({ step, matched: true });
  return chain(terminalPullReplay(route, fillRatio, tx.binary, tx.proof), (replay) => {
    if (replay) return map(sourceHub ? removeOrRouteBookOrder(w.step, route, "settled") : ok(w.step), matched);
    return chain(pullCloseAllowed(route, fillRatio, "source", sourceHub, tx.proof), () =>
      chain(closeProgress(w.step, route.orderId, tx.proof, fillRatio), (p) =>
        map(sourceHub ? removeOrRouteBookOrder(p.step, p.route, p.terminal) : ok(p.step), matched),
      ),
    );
  });
};
/** The target leg closes: a replay is only checked, a new close projects. */
const closeTargetLeg = (
  w: CloseWalk,
  route: CrossRoute,
  tx: TxOf<"cross_pull_close">,
  targetHub: boolean,
): Result<CloseWalk, EntityError> => {
  const fillRatio = tx.proof.fillRatio;
  return chain(terminalPullReplay(route, fillRatio, tx.binary, tx.proof), (replay) => {
    if (replay) return ok({ step: w.step, matched: true });
    return chain(pullCloseAllowed(route, fillRatio, "target", targetHub, tx.proof), () =>
      map(closeProgress(w.step, route.orderId, tx.proof, fillRatio), (p) => ({ step: p.step, matched: true })),
    );
  });
};
/** One mirrored route: which side of the closed pull this Entity is on decides the leg it closes. */
const closeRoute =
  (tx: TxOf<"cross_pull_close">, self: string, peer: string) =>
  (w: CloseWalk, orderId: string): Result<CloseWalk, EntityError> => {
    const route = w.step.host.swaps?.get(orderId);
    if (route === undefined) return ok(w);
    const p = partiesOf(route);
    const sourcePull = route.sourcePull?.pullId === tx.pullId;
    const targetPull = route.targetPull?.pullId === tx.pullId;
    const sourceHub =
      sourcePull && route.targetPull?.pullId !== undefined && self === p.sourceHub && peer === p.sourceUser;
    const sourceUser = sourcePull && self === p.sourceUser && peer === p.sourceHub;
    const targetUser = targetPull && self === p.targetUser && peer === p.targetHub;
    const targetHub = targetPull && self === p.targetHub && peer === p.targetUser;
    if (sourceHub || sourceUser) return closeSourceLeg(w, route, tx, sourceHub);
    return targetUser || targetHub ? closeTargetLeg(w, route, tx, targetHub) : ok(w);
  };
/**
 * og applyCrossPullCloseFollowup: every mirrored route naming this pull on this Account projects the committed close;
 * the source hub then drops or routes the book order.
 */
const committedPullClose = (
  start: CommittedCrossStep,
  cp: string,
  tx: TxOf<"cross_pull_close">,
): Result<CommittedCrossStep, EntityError> => {
  const fillRatio = tx.proof.fillRatio;
  if (!Number.isSafeInteger(fillRatio) || fillRatio < 0 || fillRatio > MAX_FILL)
    return invariant(`CROSS_J_CLOSE_PROOF_RATIO_INVALID:${fillRatio}`);
  return chain(fatalCross(decodeHashLadderBinary(tx.binary)), (decoded) => {
    if (decoded.fillRatio !== fillRatio) {
      return invariant(
        `CROSS_J_CLOSE_BINARY_RATIO_MISMATCH: pull=${tx.pullId} binary=${decoded.fillRatio} proof=${fillRatio}`,
      );
    }
    const orderIds = [...(start.host.swaps?.keys() ?? [])];
    const walked = foldResult(
      orderIds,
      { step: start, matched: false },
      closeRoute(tx, entityRef(start.host.id), entityRef(cp)),
    );
    return chain(walked, (w) =>
      w.matched
        ? ok({ ...w.step, handled: true })
        : invariant(`CROSS_J_PULL_CLOSE_ROUTE_MISSING: pull=${tx.pullId} order=${tx.proof.orderId}`),
    );
  });
};
/**
 * og applyCommittedCrossJurisdictionAccountTxFollowup: `handled` is og's return (a cross-j tx that the HTLC followup
 * must skip).
 */
export const committedCrossFollowup = (
  h: CommittedCrossHost,
  counterpartyId: string,
  tx: WireAccountTx,
  committedAt: number,
): Result<CommittedCrossStep, EntityError> => {
  const start: CommittedCrossStep = { host: h, outputs: [], messages: [], created: [], handled: false };
  switch (tx.type) {
    case "cross_pull_lock":
      return committedPullLock(start, counterpartyId, tx, committedAt);
    case "cross_pull_close":
      return committedPullClose(start, counterpartyId, tx);
    default:
      return ok(start);
  }
};
